#[test]
fn empty_list_call_arguments_inherit_parameter_types() {
    let source = r#"
fn consume(values: i64[]) -> i64 {
    return values.count
}

fn consumeNamed(seed: i64, *, values: i64[]) -> i64 {
    return seed + values.count
}

fn main() -> i64 {
    let positional: i64 = consume([])
    return positional + consumeNamed(3, values: [])
}
"#;
    let generated = compile_to_c(source)
        .expect("empty list call arguments should inherit their parameter list type");
    assert!(
        generated
            .contains("(struct flux__list){ .data = NULL, .len = 0, .stride = sizeof(int64_t) }"),
        "{generated}"
    );
    assert!(generated.contains("flux__fn_consume"), "{generated}");
    assert!(generated.contains("flux__fn_consumeNamed"), "{generated}");
}

#[test]
fn empty_collection_call_arguments_inherit_parameter_types() {
    let source = r#"
fn countList(values: i64[]) -> i64 {
    return values.count
}

fn countSet(values: set<i64>) -> i64 {
    return values.count
}

fn countSetNamed(seed: i64, *, values: set<i64>) -> i64 {
    return seed + values.count
}

fn countMap(values: map<str, i64>) -> i64 {
    return values.count
}

fn countMapNamed(seed: i64, *, values: map<str, i64>) -> i64 {
    return seed + values.count
}

fn applyList(transform: fn(i64[]) -> i64) -> i64 {
    return transform([])
}

fn applySet(transform: fn(set<i64>) -> i64) -> i64 {
    return transform({})
}

fn applyMap(transform: fn(map<str, i64>) -> i64) -> i64 {
    return transform(map{})
}

fn main() -> i64 {
    let listCount: i64 = applyList(countList)
    let setCount: i64 = applySet(countSet)
    let mapCount: i64 = applyMap(countMap)
    return listCount + setCount + mapCount + countSet({}) + countSetNamed(3, values: {}) + countMap(map{}) + countMapNamed(4, values: map{})
}
"#;
    let generated = compile_to_c(source)
        .expect("empty collection call arguments should inherit exact parameter types");
    assert!(
        generated
            .contains("(struct flux__list){ .data = NULL, .len = 0, .stride = sizeof(int64_t) }"),
        "{generated}"
    );
    assert!(
        generated.contains("flux__typed_borrowed_list"),
        "empty list calls should lower through typed-IR borrowed descriptors: {generated}"
    );
    assert!(
        generated.contains("flux__typed_borrowed_set"),
        "empty set calls should lower through typed-IR borrowed descriptors: {generated}"
    );
    assert!(
        generated.contains("flux__typed_borrowed_map"),
        "empty map calls should lower through typed-IR borrowed descriptors: {generated}"
    );
    assert!(generated.contains("flux__fn_countList"), "{generated}");
    assert!(generated.contains("flux__fn_countSet"), "{generated}");
    assert!(generated.contains("flux__fn_countSetNamed"), "{generated}");
    assert!(generated.contains("flux__fn_countMap"), "{generated}");
    assert!(generated.contains("flux__fn_countMapNamed"), "{generated}");
}

#[test]
fn empty_qualified_list_arguments_inherit_builtin_types() {
    let source = r#"
fn ready(_socket: i64) -> void {
}

fn main() -> i64 {
    let _tlsFailure: error = tls.writeBytes(1, [])
    let _websocketFailure: error = websocket.writeBytes(1, [])
    let (_written, _writeFailure) = net.writeBytes(1, [])
    let _partsFailure: error = net.writeParts(1, [])
    let (_datagramWritten, _datagramFailure) = net.writeBytesTo(1, "127.0.0.1", 1, [])
    let (_partDatagramWritten, _partDatagramFailure) = net.writeBytesToParts(1, "127.0.0.1", 1, [])
    let (_readyCount, _readyFailure) = net.readableMany([], 0, ready)
    let (_workerHandle, _workerFailure) = worker.waitAny([])
    let _requestFailure: error = http.requestBytes(1, "GET", "/", "localhost", "application/octet-stream", [])
    let _responseFailure: error = http.respondBytes(1, 200, "application/octet-stream", [])
    return 0
}
"#;
    let generated = compile_to_c(source)
        .expect("empty qualified list arguments should inherit exact builtin parameter types");

    assert!(
        generated.matches(".data = NULL, .len = 0").count() >= 10,
        "empty builtin list arguments should lower as storage-free typed descriptors: {generated}"
    );
    assert!(
        generated.contains(".stride = sizeof(const char *)"),
        "empty text-part lists should preserve their exact contextual element type: {generated}"
    );
    assert!(
        generated.contains(".stride = sizeof(struct flux__list)"),
        "empty nested byte-part lists should preserve their exact contextual element type: {generated}"
    );
}

