#[test]
fn named_time_zone_operations_share_one_process_global_transaction_lock() {
    let source = r#"
fn emit(value: str) -> void {
    print(value)
}
fn main() -> i64 {
    let formatted: error = time.formatZone(946782245006, "America/New_York", emit)
    let (offset, offsetError) = time.zoneOffset(946782245006, "America/New_York")
    if formatted != nil:
        return 1
    if offsetError != nil:
        return 2
    return offset
}
"#;
    let generated = compile_to_c(source).expect("combined named-zone operations should lower");
    assert_eq!(
        generated
            .matches("static volatile int flux_time_zone_transaction_lock")
            .count(),
        1,
        "both TZ operations should declare one shared process-global transaction lock"
    );
    assert!(generated.matches("flux_time_zone_transaction_lock").count() > 2);
    assert!(!generated.contains("flux_time_zone_offset_lock"));
}

#[test]
fn ui_targets_integrate_callbacks_with_native_event_loops() {
    let source = r#"
view Screen {
    state clicked: bool = false
    grid columns: 1fr
    grid rows: auto
    Button action at 1,1
        text: "Press"
        onPress: clicked => !clicked
}
app Screen(title: "Flux", width: 320, height: 200)
"#;
    let program = fluxc::parser::parse(source).expect("UI source should parse");
    let signatures = fluxc::typecheck::check(&program).expect("UI source should typecheck");
    let paths = std::collections::HashMap::new();
    let linux = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &paths,
        fluxc::codegen::NativeTarget::Linux,
    )
    .expect("Linux UI should lower");
    assert!(linux.contains("g_signal_connect(application, \"activate\","));
    assert!(linux.contains("g_application_run(G_APPLICATION(application), argc, argv)"));
    assert!(linux.contains("G_CALLBACK(flux__ui_click_action)"));

    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &paths,
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("Android UI should lower");
    assert!(android.contains("ANativeActivity_onCreate"));
    assert!(android.contains("Java_app_flux_runtime_FluxActivity_nativeOnClick"));
    assert!(android.contains("Java_app_flux_runtime_FluxActivity_nativeBuildUi"));
}

#[test]
fn extern_c_imports_lower_to_exact_native_symbols_with_safe_boundaries() {
    let source = r#"
extern c "flux_test_double" fn nativeDouble(value: i64) -> i64

fn main() -> i64 {
    return nativeDouble(21)
}
"#;

    check_source(source).expect("safe extern C import should typecheck");
    let formatted = fluxc::formatter::format_source(source).expect("extern C source should format");
    assert!(formatted.contains("extern c \"flux_test_double\" fn nativeDouble(value: i64) -> i64"));
    let generated = compile_to_c(source).expect("extern C import should lower on Linux");
    assert!(generated.contains("extern int64_t flux_test_double("));
    assert!(generated.contains("flux_test_double(INT64_C(21))"));
    assert!(!generated.contains("flux__fn_nativeDouble("));

    let program = fluxc::parser::parse(source).expect("extern C source should parse");
    let signatures = fluxc::typecheck::check(&program).expect("extern C source should typecheck");
    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("safe extern C imports should also lower for Android NDK linking");
    assert!(android.contains("extern int64_t flux_test_double("));
    assert!(android.contains("flux_test_double(INT64_C(21))"));

    let windows = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Windows,
    )
    .expect("safe extern C imports should also lower for Windows native linking");
    assert!(windows.contains("extern int64_t flux_test_double("));
    assert!(windows.contains("flux_test_double(INT64_C(21))"));
}

#[test]
fn minimal_windows_application_declares_root_window_handle_before_use() {
    let source = r#"
view Screen {
    grid columns: 1fr
    grid rows: auto
    Text title at 1,1
        text: "Windows runtime smoke"
}

app Screen(title: "Flux Windows runtime smoke")
"#;
    let program = fluxc::parser::parse(source).expect("minimal Windows application should parse");
    let signatures =
        fluxc::typecheck::check(&program).expect("minimal Windows application should typecheck");
    let generated = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Windows,
    )
    .expect("minimal Windows application should lower");

    let declaration = generated
        .find("static HWND flux__windows_active_window = NULL;")
        .expect("Windows GUI runtime should declare its root window handle");
    let first_use = generated
        .find("flux__windows_active_window = CreateWindowExW(")
        .expect("Windows GUI runtime should create its root window");
    assert!(declaration < first_use);
    assert!(generated.contains("LoadCursorW(NULL, MAKEINTRESOURCEW(32512))"));
}

#[test]
fn windows_backend_emits_native_win32_window_controls_and_click_dispatch() {
    let source = r##"
view Screen {
    state active: bool = false
    state query: str = ""
    grid columns: 1fr
    grid rows: auto auto auto auto auto
    Text title at 1,1
        text: query
        textAlign: "center"
        color: "#1f2328"
        fontFamily: "Aptos"
        backgroundColor: "surfaceRaised"
        visible: active
    TextInput input at 2,1
        text: query
        enabled: active
        onChange: query, value => value
    Toggle toggle at 3,1
        label: "Enabled"
        checked: active
        onChange: active => !active
    Radio radio at 4,1
        label: "Selected"
        selected: active
        onSelect: active => true
    Button action at 5,1
        text: "Press"
        onPress: active => !active
}
app Screen(title: "Native Flux", width: 640, height: 480)
"##;
    let program = fluxc::parser::parse(source).expect("Windows application source should parse");
    let signatures =
        fluxc::typecheck::check(&program).expect("Windows application should typecheck");
    let generated = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Windows,
    )
    .expect("Windows application should lower to native Win32 C");
    assert!(generated.contains("#include <windows.h>"));
    assert!(generated.contains("WNDCLASSW"));
    assert!(generated.contains("CreateWindowExW(0, L\"STATIC\""));
    assert!(generated.contains("WS_CHILD | WS_VISIBLE | SS_CENTER"));
    assert!(generated.contains("CreateWindowExW(0, L\"EDIT\""));
    assert!(generated.contains("CreateWindowExW(0, L\"BUTTON\""));
    assert!(generated.contains("BS_AUTOCHECKBOX"));
    assert!(generated.contains("BS_AUTORADIOBUTTON"));
    assert!(generated.contains("flux__windows_utf8_to_wide(\"Aptos\")"));
    assert!(generated.contains("Text.font_family is not valid UTF-8"));
    assert!(generated.contains("static bool flux__ui_state_active = false;"));
    assert!(generated.contains("static char *flux__ui_state_owned_query = NULL;"));
    assert!(generated.contains("static void flux__ui_set_state_query(const char *value)"));
    assert!(
        generated.contains("flux__win_set_text_if_changed(flux__ui_title, flux__ui_state_query)")
    );
    assert!(generated.contains("SendMessageA(flux__ui_toggle, BM_SETCHECK"));
    assert!(
        generated
            .contains("ShowWindow(flux__ui_title, (flux__ui_state_active) ? SW_SHOW : SW_HIDE)")
    );
    assert!(
        generated.contains("EnableWindow(flux__ui_input, (flux__ui_state_active) ? TRUE : FALSE)")
    );
    assert!(generated.contains("case WM_COMMAND"));
    assert!(generated.contains("case WM_SIZE"));
    assert!(generated.contains("GetClientRect(hwnd, &client)"));
    assert!(generated.contains("MoveWindow(flux__ui_title"));
    assert!(generated.contains(
        "static void flux__win_change_1(HWND control) { if (flux__win_refreshing) return;"
    ));
    assert!(generated.contains("flux__win_change_1"));
    assert!(generated.contains("flux__win_click_2"));
    assert!(generated.contains("flux__win_click_3"));
    assert!(generated.contains("flux__win_click_4"));
    assert!(
        generated.contains("static const COLORREF flux__win_color_title_color = RGB(31, 35, 40);")
    );
    assert!(generated.contains(
        "static const COLORREF flux__win_color_title_background_color = RGB(255, 255, 255);"
    ));
    assert!(generated.contains("case WM_CTLCOLORSTATIC"));
    assert!(generated.contains("SetTextColor(dc, flux__win_color_title_color)"));
    assert!(generated.contains("CreateSolidBrush(flux__win_color_title_background_color)"));
    assert!(!generated.contains("#include <gtk/gtk.h>"));
    assert!(!generated.contains("android/native_activity.h"));
}

