#[test]
fn windows_selectable_text_uses_native_read_only_edit_control() {
    let source = r#"
view Screen {
    grid columns: 1fr
    grid rows: auto auto
    Text selectable at 1,1
        text: "Copy me"
        selectable: true
        textAlign: "right"
    Text label at 2,1
        text: "Ordinary"
        selectable: false
}
app Screen
"#;
    let program = fluxc::parser::parse(source).expect("selectable Windows Text should parse");
    let signatures =
        fluxc::typecheck::check(&program).expect("selectable Windows Text should typecheck");
    let windows = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Windows,
    )
    .expect("compile-time selectable Windows Text should lower natively");
    assert!(windows.contains(
        "flux__ui_selectable = CreateWindowExW(0, L\"EDIT\", L\"\", WS_CHILD | WS_VISIBLE | WS_TABSTOP | ES_RIGHT | ES_MULTILINE | ES_READONLY"
    ));
    assert!(windows.contains(
        "flux__ui_label = CreateWindowExW(0, L\"STATIC\", L\"\", WS_CHILD | WS_VISIBLE | SS_LEFT"
    ));

    let dynamic = r#"
view Screen {
    state selectable: bool = false
    grid columns: 1fr
    grid rows: auto
    Text label at 1,1
        text: "Dynamic"
        selectable: selectable
}
app Screen
"#;
    let program =
        fluxc::parser::parse(dynamic).expect("dynamic selectable Windows Text should parse");
    let signatures = fluxc::typecheck::check(&program)
        .expect("dynamic selectable Windows Text should typecheck");
    let error = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Windows,
    )
    .expect_err("dynamic Windows Text.selectable must not be silently ignored");
    assert!(
        error
            .message
            .contains("Text.selectable must be a compile-time bool value")
    );

    let tappable = r#"
fn tapped() -> void {
    print("tap")
}

fn swiped(velocityX: i64, velocityY: i64) -> void {
    print(velocityX + velocityY)
}

view Screen {
    grid columns: 1fr
    grid rows: auto
    Text label at 1,1
        text: "Selectable action"
        selectable: true
        onTap: tapped
        onLongPress: tapped
        onSwipe: swiped
}
app Screen
"#;
    let program = fluxc::parser::parse(tappable).expect("tappable selectable Text should parse");
    let signatures =
        fluxc::typecheck::check(&program).expect("tappable selectable Text should typecheck");
    let windows = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Windows,
    )
    .expect("selectable Text should compose with onTap through the native EDIT control");
    assert!(windows.contains(
        "flux__ui_label = CreateWindowExW(0, L\"EDIT\", L\"\", WS_CHILD | WS_VISIBLE | WS_TABSTOP | ES_LEFT | ES_MULTILINE | ES_READONLY"
    ));
    assert!(windows.contains("static LRESULT CALLBACK flux__win_selectable_tap_proc_0"));
    assert!(windows.contains("flux__win_selectable_tap_moved_0"));
    assert!(windows.contains("GetSystemMetrics(SM_CXDRAG)"));
    assert!(windows.contains("GetSystemMetrics(SM_CYDRAG)"));
    assert!(windows.contains("if (activate) flux__win_tap_0();"));
    assert!(windows.contains(
        "if (flux__win_long_press_consumed_0) { flux__win_long_press_consumed_0 = false;"
    ));
    assert!(
        windows.contains("if (flux__win_swipe_consumed_0) { flux__win_swipe_consumed_0 = false;")
    );
    assert!(windows.contains(
        "SetWindowLongPtrW(flux__ui_label, GWLP_WNDPROC, (LONG_PTR)flux__win_selectable_tap_proc_0)"
    ));
    assert!(!windows.contains("case 1000: if (HIWORD(wparam) == STN_CLICKED)"));
    assert!(windows.contains(
        "if (message->wParam == VK_RETURN || message->wParam == VK_SPACE) { flux__win_tap_0(); return true; }"
    ));
}

#[test]
fn windows_backend_keeps_ui_text_on_unicode_win32_path() {
    let source = r#"
view Screen {
    state query: str = "你好"
    grid columns: 1fr
    grid rows: auto auto auto
    Text title at 1,1
        text: "Café 🚀"
    TextInput input at 2,1
        text: query
        onChange: query, value => value
    Button action at 3,1
        text: "保存"
}
app Screen(title: "Flux 日本語")
"#;
    let program = fluxc::parser::parse(source).expect("Unicode Windows UI source should parse");
    let signatures =
        fluxc::typecheck::check(&program).expect("Unicode Windows UI source should typecheck");
    let generated = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Windows,
    )
    .expect("Unicode Windows UI should lower to native Win32 C");

    assert!(generated.contains("WNDCLASSW"));
    assert!(generated.contains("RegisterClassW(&wc)"));
    assert!(generated.contains(r#"CreateWindowExW(0, L"STATIC", L""#));
    assert!(generated.contains(r#"CreateWindowExW(0, L"EDIT", L""#));
    assert!(generated.contains(r#"CreateWindowExW(0, L"BUTTON", L""#));
    assert!(generated.contains("SetWindowTextW(control, wide)"));
    assert!(generated.contains("GetWindowTextW(control, wide, length + 1)"));
    assert!(generated.contains("flux__windows_wide_to_utf8(wide)"));
    assert!(
        generated.contains(
            r#"flux__win_set_text_if_changed(flux__windows_active_window, "Flux 日本語")"#
        )
    );
    assert!(generated.contains(r#"flux__win_set_text_if_changed(flux__ui_title, "Café 🚀")"#));
    assert!(generated.contains(r#"flux__win_set_text_if_changed(flux__ui_action, "保存")"#));
    assert!(generated.contains("TOOLTIPS_CLASSW") || !generated.contains("flux__win_tooltips"));
    assert!(generated.contains("GetMessageW(&message"));
    assert!(generated.contains("DispatchMessageW(&message)"));
    assert!(!generated.contains("GetWindowTextA(control"));
    assert!(!generated.contains("SetWindowTextA(control"));
}

