#[test]
fn accepts_concise_single_expression_functions() {
    let source = r#"
struct Point {
    x: i64
}

fn square(value: i64) -> i64 { value * value }
fn choose(flag: bool) -> i64 {
    if flag:
        return 7
    return 2
}
fn point(value: i64) -> Point { Point { x: value } }
fn pair(value: i64) -> (i64, error) { checked(value) }

fn checked(value: i64) -> (i64, error) {
    return value, nil
}

fn main() -> i64 {
    print(square(6))
    print(choose(false))
    let item: Point = point(9)
    print(item.x)
    let value: i64, err: error = pair(12)
    print(value)
    print(err)
    return 0
}
"#;

    check_source(source).expect("concise functions should typecheck");
    let generated = compile_to_c(source).expect("concise functions should compile");
    assert!(generated.contains("flux__fn_square"));
    assert!(generated.contains("return flux_mul_i64(flux__local_value, flux__local_value);"));
    assert!(generated.contains("flux__fn_pair"));

    let formatted =
        fluxc::formatter::format_source(source).expect("concise functions should format");
    assert!(formatted.contains("fn square(value: i64) -> i64 { value * value }"));
    assert!(formatted.contains("fn point(value: i64) -> Point { Point { x: value } }"));
    let formatted_again = fluxc::formatter::format_source(&formatted)
        .expect("formatted concise functions should reparse");
    assert_eq!(formatted_again, formatted);
}

#[test]
fn shell_style_calls_pipelines_redirection_and_background_are_typed_and_native() {
    let source = r#"
fn increment(value: i64) -> i64 {
    return value + 1
}

fn scale(value: i64, factor: i64) -> i64 {
    return value * factor
}

fn message() -> str {
    return "hello"
}

fn main() -> i64 {
    let result: i64 = increment 2 | scale 5
    print result
    message > "/tmp/flux-shell-output.txt"
    message >> "/tmp/flux-shell-output.txt"
    increment 1 | print &
    return result
}
"#;

    check_source(source).expect("shell-style syntax should typecheck");
    let generated = compile_to_c(source).expect("shell-style syntax should lower natively");
    assert!(generated.contains("flux__fn_scale(flux__fn_increment(INT64_C(2)), INT64_C(5))"));
    assert!(
        generated.contains(
            "flux_redirect_str(\"/tmp/flux-shell-output.txt\", false, flux__fn_message())"
        )
    );
    assert!(
        generated.contains(
            "flux_redirect_str(\"/tmp/flux-shell-output.txt\", true, flux__fn_message())"
        )
    );
    assert!(generated.contains("pid_t flux__bg_pid_"));
    assert!(generated.contains("waitpid("));

    let formatted = fluxc::formatter::format_source(source).expect("shell syntax should format");
    assert!(formatted.contains("let result: i64 = increment 2 | scale 5"));
    assert!(formatted.contains("print result"));
    assert!(formatted.contains("message > \"/tmp/flux-shell-output.txt\""));
    assert!(formatted.contains("message >> \"/tmp/flux-shell-output.txt\""));
    assert!(formatted.contains("increment 1 | print &"));
    let formatted_again =
        fluxc::formatter::format_source(&formatted).expect("formatted shell syntax should reparse");
    assert_eq!(formatted_again, formatted);
}

#[test]
fn functional_cascades_reuse_pipeline_typing_and_evaluate_the_target_once() {
    let source = r#"
fn seed() -> i64 {
    return 2
}

fn scale(value: i64, factor: i64) -> i64 {
    return value * factor
}

fn increment(value: i64) -> i64 {
    return value + 1
}

fn main() -> i64 {
    let result: i64 = seed() .. scale 3 .. increment
    print(result)
    return result
}
"#;

    check_source(source).expect("functional cascade syntax should typecheck like a pipeline");
    let generated = compile_to_c(source).expect("functional cascades should lower natively");
    assert!(generated.contains("flux__fn_increment(flux__fn_scale(flux__fn_seed(), INT64_C(3)))"));

    let formatted =
        fluxc::formatter::format_source(source).expect("cascade syntax should format canonically");
    assert!(formatted.contains("let result: i64 = seed() | scale 3 | increment"));
    let formatted_again = fluxc::formatter::format_source(&formatted)
        .expect("canonical functional cascade output should reparse");
    assert_eq!(formatted_again, formatted);

    let invalid = r#"
fn scale(value: bool) -> bool {
    return value
}

fn main() -> i64 {
    let value: i64 = 1 .. scale
    return value
}
"#;
    let error = check_source(invalid).expect_err("cascade stages must retain pipeline type safety");
    assert!(
        error
            .message
            .contains("argument 1 ('value') to 'scale': expected bool, got i64")
    );
}

#[test]
fn optional_aware_cascades_are_lazy_typed_flattened_and_native() {
    let source = r#"
fn maybeSeed(present: bool) -> i64? {
    if present:
        return 2
    return none
}

fn stageArg() -> i64 {
    print(99)
    return 3
}

fn scale(value: i64, factor: i64) -> i64 {
    print(value)
    return value * factor
}

fn maybeIncrement(value: i64) -> i64? {
    if value == 6:
        return value + 1
    return none
}

fn main() -> i64 {
    let present: i64? = maybeSeed(true) ?.. scale(stageArg()) .. maybeIncrement
    let missing: i64? = maybeSeed(false) ?.. scale(stageArg()) .. maybeIncrement
    print(present ?? -1)
    print(missing ?? -1)
    return 0
}
"#;

    check_source(source).expect("optional-aware cascades should typecheck");
    let formatted = fluxc::formatter::format_source(source)
        .expect("optional-aware cascades should format canonically");
    assert!(
        formatted.contains(
            "let present: i64? = maybeSeed(true) ?.. scale stageArg() ?.. maybeIncrement"
        )
    );
    assert_eq!(
        fluxc::formatter::format_source(&formatted)
            .expect("formatted optional-aware cascades should reparse"),
        formatted
    );

    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1401))
        .expect("optional-aware cascade source should analyze");
    let graph = database
        .control_flow_graph("main")
        .expect("main should have a control-flow graph");
    let scale_cascade = graph
        .values()
        .iter()
        .find(|value| {
            matches!(
                &value.kind,
                ControlFlowValueKind::OptionalCascadeCall { callee, .. } if callee == "scale"
            )
        })
        .expect("optional cascade should remain explicit in typed IR");
    let ControlFlowValueKind::OptionalCascadeCall {
        optional,
        arguments,
        ..
    } = &scale_cascade.kind
    else {
        unreachable!()
    };
    let stage_argument = *arguments
        .first()
        .expect("scale optional cascade should retain its explicit stage argument");
    let stage_use = graph
        .uses_from(scale_cascade.id)
        .find(|usage| usage.value == stage_argument)
        .expect("stage argument should have an IR use");
    assert_eq!(stage_use.kind, ControlFlowValueUseKind::OptionalPresent);
    assert!(matches!(
        graph
            .value_region(stage_use.region.expect("optional stage argument should name a region"))
            .map(|region| region.kind),
        Some(ControlFlowValueRegionKind::OptionalPresent { optional: guarded }) if guarded == *optional
    ));

    let generated = compile_to_c(source).expect("optional-aware cascades should lower natively");
    assert!(generated.contains("flux__optional_cascade_input_"));
    assert!(generated.contains(".has_value)"));

    let root = std::env::temp_dir().join(format!(
        "flux-optional-cascade-{}-{}",
        std::process::id(),
        std::thread::current().name().unwrap_or("test")
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary optional-cascade directory should be writable");
    let c_path = root.join("optional-cascade.c");
    let exe_path = root.join("optional-cascade");
    fs::write(&c_path, generated).expect("generated optional-cascade C should be writable");
    let compile = Command::new("clang")
        .args(["-std=c11", "-O2"])
        .arg(&c_path)
        .arg("-o")
        .arg(&exe_path)
        .output()
        .expect("clang should compile native optional cascades");
    assert!(
        compile.status.success(),
        "optional-cascade C should compile: {}",
        String::from_utf8_lossy(&compile.stderr)
    );
    let output = Command::new(&exe_path)
        .output()
        .expect("optional-cascade program should run");
    assert!(
        output.status.success(),
        "map iteration should exit cleanly: status={:?}, stdout={}, stderr={}",
        output.status.code(),
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(String::from_utf8_lossy(&output.stdout), "99\n2\n7\n-1\n");
    let _ = fs::remove_dir_all(&root);

    let non_optional = r#"
fn increment(value: i64) -> i64 {
    return value + 1
}

fn main() -> i64 {
    let invalid: i64? = 1 ?.. increment
    return invalid ?? 0
}
"#;
    let error = check_source(non_optional)
        .expect_err("optional-aware cascades must require an optional target");
    assert!(
        error
            .message
            .contains("optional cascade '?..' requires an optional target, got i64")
    );

    let void_stage = r#"
fn consume(_value: i64) -> void {
}

fn main() -> i64 {
    let value: i64? = 1
    let invalid: i64? = value ?.. consume
    return invalid ?? 0
}
"#;
    let error =
        check_source(void_stage).expect_err("optional-aware cascade stages must produce a value");
    assert!(
        error
            .message
            .contains("optional cascade stages must return a value")
    );
}

#[test]
fn process_environment_capabilities_are_typed_native_and_tree_shaken() {
    let source = r#"
fn main() -> i64 {
    print(process.pid())
    print(process.parentPid())
    print(process.cpuMillis())
    print(process.peakResidentMemoryBytes())
    print(process.hasEnv("FLUX_PROCESS_TEST"))
    print(process.env("FLUX_PROCESS_TEST", "missing"))
    print(process.env("FLUX_PROCESS_MISSING", "fallback"))
    return 0
}
"#;

    check_source(source).expect("process capabilities should typecheck on portable source");
    let generated = compile_to_c(source).expect("process capabilities should lower on Linux");
    assert!(generated.contains("static inline int64_t flux__process_pid(void)"));
    assert!(generated.contains("static inline int64_t flux__process_parent_pid(void)"));
    assert!(generated.contains("static inline int64_t flux__process_cpu_millis(void)"));
    assert!(
        generated.contains("static inline int64_t flux__process_peak_resident_memory_bytes(void)")
    );
    assert!(generated.contains("static inline bool flux__process_has_env(const char *name)"));
    assert!(generated.contains("while (length <= 1024 && name[length] != '\\0') length += 1"));
    assert!(generated.contains(
        "static inline const char *flux__process_env(const char *name, const char *fallback)"
    ));
    assert!(generated.contains("flux__process_pid()"));
    assert!(generated.contains("flux__process_parent_pid()"));
    assert!(generated.contains("flux__process_cpu_millis()"));
    assert!(generated.contains("flux__process_peak_resident_memory_bytes()"));
    assert!(generated.contains("flux__process_has_env(\"FLUX_PROCESS_TEST\")"));
    assert!(generated.contains("flux__process_env(\"FLUX_PROCESS_TEST\", \"missing\")"));

    let root = std::env::temp_dir().join(format!("flux-process-api-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("process API fixture should be writable");
    let source_path = root.join("main.flux");
    fs::write(&source_path, source).expect("process API source should be writable");
    let binary = root.join("process-api");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("process API binary should build");
    assert!(
        built.status.success(),
        "process API build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .env("FLUX_PROCESS_TEST", "native-value")
        .output()
        .expect("process API binary should run");
    assert!(run.status.success());
    let lines = String::from_utf8_lossy(&run.stdout)
        .lines()
        .map(str::to_string)
        .collect::<Vec<_>>();
    assert_eq!(lines.len(), 7);
    assert!(lines[0].parse::<i64>().is_ok());
    assert!(lines[1].parse::<i64>().is_ok());
    assert!(lines[2].parse::<i64>().is_ok_and(|value| value >= 0));
    assert!(lines[3].parse::<i64>().is_ok_and(|value| value > 0));
    assert_eq!(&lines[4..], &["true", "native-value", "fallback"]);

    let unused = r#"
fn hidden() -> void {
    print(process.pid())
    print(process.cpuMillis())
    print(process.peakResidentMemoryBytes())
    print(process.env("HOME", ""))
    print(process.terminationRequested())
    process.exit(0)
}
fn main() -> i64 {
    return 0
}
"#;
    let unused_generated =
        compile_to_c(unused).expect("dead process calls should not poison Linux");
    assert!(!unused_generated.contains("flux__process_pid(void)"));
    assert!(!unused_generated.contains("flux__process_cpu_millis(void)"));
    assert!(!unused_generated.contains("flux__process_peak_resident_memory_bytes(void)"));
    assert!(!unused_generated.contains("flux__process_env(const char"));
    assert!(!unused_generated.contains("flux__process_termination_requested(void)"));
    assert!(!unused_generated.contains("flux__process_exit(int64_t code)"));

    let invalid = r#"
fn main() -> i64 {
    process.pid(1)
    process.parentPid(false)
    process.cpuMillis(1)
    process.peakResidentMemoryBytes(1)
    process.terminationRequested(1)
    process.exit(false)
    process.exit(256)
    process.hasEnv(42)
    process.env("HOME", 1)
    process.unknown()
    return 0
}
"#;
    let errors =
        check_source_all(invalid).expect_err("invalid process calls should fail statically");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("process.pid expects 0 arguments, got 1")
    }));
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("process.parentPid expects 0 arguments, got 1")
    }));
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("process.cpuMillis expects 0 arguments, got 1")
    }));
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("process.peakResidentMemoryBytes expects 0 arguments, got 1")
    }));
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("process.terminationRequested expects 0 arguments, got 1")
    }));
    assert!(errors.iter().any(|error| {
        error.message.contains("process.exit code") && error.message.contains("expected i64")
    }));
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("process.exit code must be between 0 and 255")
    }));
    assert!(
        errors
            .iter()
            .any(|error| error.message.contains("process.hasEnv name")
                && error.message.contains("expected str"))
    );
    assert!(
        errors
            .iter()
            .any(|error| error.message.contains("process.env fallback")
                && error.message.contains("expected str"))
    );
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("process module has no function 'unknown'")
    }));

    let android_root = root.join("android");
    fs::create_dir_all(android_root.join("src"))
        .expect("Android process rejection fixture should be writable");
    fs::write(
        android_root.join("flux.toml"),
        "[package]\nname = \"process-android\"\nentry = \"src/main.flux\"\n",
    )
    .expect("Android process manifest should be writable");
    fs::write(
        android_root.join("src/main.flux"),
        "fn main() -> i64 {\n    print(process.pid())\n    return 0\n}\n",
    )
    .expect("Android process source should be writable");
    let analysis =
        fluxc::project::analyze(&android_root).expect("Android process fixture should analyze");
    let error = analysis
        .emit_c_for_target(fluxc::codegen::NativeTarget::Android)
        .expect_err("process APIs must reject Android lowering");
    assert!(
        error
            .message
            .contains("process.* APIs require a desktop/server target")
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn tcp_socket_lifecycle_is_typed_native_tree_shaken_and_runnable() {
    let source = r#"
fn main() -> i64 {
    let (listener, listenError) = net.tcpListen("127.0.0.1", 0, 8)
    print(listenError)
    let (port, portError) = net.localPort(listener)
    print(port)
    print(portError)
    print(net.setKeepAlive(listener, true))
    print(net.close(listener))
    return 0
}
"#;
    check_source(source).expect("TCP socket lifecycle should typecheck");
    let generated = compile_to_c(source).expect("TCP socket lifecycle should lower on Linux");
    assert!(generated.contains("struct flux__net_i64_error"));
    assert!(generated.contains("flux__net_tcp_listen("));
    assert!(generated.contains("flux__net_local_port("));
    assert!(generated.contains("flux__net_close("));
    assert!(generated.contains("#include <sys/socket.h>"));
    assert!(generated.contains("#include <netdb.h>"));

    let root = std::env::temp_dir().join(format!("flux-net-api-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("network API fixture should be writable");
    let source_path = root.join("listen.flux");
    fs::write(&source_path, source).expect("network API source should be writable");
    let binary = root.join("listen");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("network API binary should build");
    assert!(
        built.status.success(),
        "network API build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("network API binary should run");
    assert!(run.status.success());
    let lines = String::from_utf8_lossy(&run.stdout)
        .lines()
        .map(str::to_string)
        .collect::<Vec<_>>();
    assert_eq!(lines.len(), 5);
    assert_eq!(lines[0], "nil");
    assert!(lines[1].parse::<u16>().is_ok_and(|port| port > 0));
    assert_eq!(lines[2], "nil");
    assert_eq!(lines[3], "setKeepAlive requires a connected TCP socket");
    assert_eq!(lines[4], "nil");

    let rust_listener = TcpListener::bind("127.0.0.1:0").expect("loopback listener should bind");
    let connect_port = rust_listener.local_addr().unwrap().port();
    let connect_source = format!(
        "fn main() -> i64 {{\n    let (socket, failure) = net.tcpConnect(\"127.0.0.1\", {connect_port})\n    print(failure)\n    print(net.setNoDelay(socket, true))\n    print(net.setNoDelay(socket, false))\n    print(net.setKeepAlive(socket, true))\n    print(net.setKeepAlive(socket, false))\n    print(net.close(socket))\n    return 0\n}}\n"
    );
    let connect_generated =
        compile_to_c(&connect_source).expect("TCP no-delay should lower on Linux");
    assert!(connect_generated.contains("flux__net_set_no_delay("));
    assert!(connect_generated.contains("flux__net_set_keep_alive("));
    assert!(connect_generated.contains("SO_KEEPALIVE"));
    assert!(connect_generated.contains("#include <netinet/tcp.h>"));
    assert!(connect_generated.contains("TCP_NODELAY"));
    let connect_path = root.join("connect.flux");
    fs::write(&connect_path, connect_source).expect("TCP connect source should be writable");
    let connect_binary = root.join("connect");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&connect_path)
        .arg("-o")
        .arg(&connect_binary)
        .output()
        .expect("TCP connect binary should build");
    assert!(
        built.status.success(),
        "TCP connect build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&connect_binary)
        .output()
        .expect("TCP connect binary should run");
    assert!(run.status.success());
    assert_eq!(
        String::from_utf8_lossy(&run.stdout),
        "nil\nnil\nnil\nnil\nnil\nnil\n"
    );
    drop(rust_listener);

    let invalid = r#"
fn main() -> i64 {
    let (socket, failure) = net.tcpConnect(1, 70000)
    let (listener, listenFailure) = net.tcpListen("127.0.0.1", -1, 0)
    let (accepted, acceptFailure) = net.tcpAccept("bad")
    print(socket)
    print(failure)
    print(listener)
    print(listenFailure)
    print(accepted)
    print(acceptFailure)
    print(net.close(false))
    print(net.setNoDelay("bad", true))
    print(net.setNoDelay(1, 1))
    print(net.setKeepAlive("bad", true))
    print(net.setKeepAlive(1, 1))
    net.unknown()
    return 0
}
"#;
    let errors =
        check_source_all(invalid).expect_err("invalid network calls should fail statically");
    assert!(
        errors
            .iter()
            .any(|error| error.message.contains("net.tcpConnect host")
                && error.message.contains("expected str"))
    );
    let connect_port_error = check_source("fn main() -> i64 {\n    let (socket, failure) = net.tcpConnect(\"127.0.0.1\", 70000)\n    return 0\n}\n")
        .expect_err("constant TCP connect ports outside the valid range must fail");
    assert!(
        connect_port_error
            .message
            .contains("net.tcpConnect port must be between 1 and 65535")
    );
    let listen_port_error = check_source("fn main() -> i64 {\n    let (listener, failure) = net.tcpListen(\"127.0.0.1\", -1, 8)\n    return 0\n}\n")
        .expect_err("constant TCP listen ports outside the valid range must fail");
    assert!(
        listen_port_error
            .message
            .contains("net.tcpListen port must be between 0 and 65535")
    );
    let backlog_error = check_source("fn main() -> i64 {\n    let (listener, failure) = net.tcpListen(\"127.0.0.1\", 0, 0)\n    return 0\n}\n")
        .expect_err("constant TCP listen backlogs must be positive");
    assert!(
        backlog_error
            .message
            .contains("net.tcpListen backlog must be between 1 and 2147483647")
    );
    assert!(
        errors
            .iter()
            .any(|error| error.message.contains("net.tcpAccept socket")
                && error.message.contains("expected i64"))
    );
    assert!(
        errors
            .iter()
            .any(|error| error.message.contains("net.close socket")
                && error.message.contains("expected i64"))
    );
    assert!(errors.iter().any(|error| {
        error.message.contains("net.setNoDelay socket") && error.message.contains("expected i64")
    }));
    assert!(errors.iter().any(|error| {
        error.message.contains("net.setNoDelay enabled") && error.message.contains("expected bool")
    }));
    assert!(errors.iter().any(|error| {
        error.message.contains("net.setKeepAlive socket") && error.message.contains("expected i64")
    }));
    assert!(errors.iter().any(|error| {
        error.message.contains("net.setKeepAlive enabled")
            && error.message.contains("expected bool")
    }));
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("net module has no function 'unknown'")
    }));

    let unused = r#"
fn hidden() -> void {
    let (listener, failure) = net.tcpListen("127.0.0.1", 0, 8)
    print(listener)
    print(failure)
    print(net.setNoDelay(listener, true))
    print(net.setKeepAlive(listener, true))
}
fn main() -> i64 {
    return 0
}
"#;
    let unused_generated = compile_to_c(unused).expect("dead network calls should tree-shake");
    assert!(!unused_generated.contains("flux__net_tcp_listen("));
    assert!(!unused_generated.contains("flux__net_set_no_delay("));
    assert!(!unused_generated.contains("flux__net_set_keep_alive("));
    assert!(!unused_generated.contains("#include <netinet/tcp.h>"));
    assert!(!unused_generated.contains("#include <sys/socket.h>"));

    let android_root = root.join("android");
    fs::create_dir_all(android_root.join("src"))
        .expect("Android network fixture should be writable");
    fs::write(
        android_root.join("flux.toml"),
        "[package]\nname = \"network-android\"\nentry = \"src/main.flux\"\n",
    )
    .expect("Android network manifest should be writable");
    fs::write(
        android_root.join("src/main.flux"),
        "fn main() -> i64 {\n    let (socket, failure) = net.tcpConnect(\"127.0.0.1\", 80)\n    print(socket)\n    print(failure)\n    return 0\n}\n",
    )
    .expect("Android network source should be writable");
    let analysis =
        fluxc::project::analyze(&android_root).expect("Android network fixture should analyze");
    let error = analysis
        .emit_c_for_target(fluxc::codegen::NativeTarget::Android)
        .expect_err("network APIs must reject Android lowering");
    assert!(
        error
            .message
            .contains("net.* APIs require a desktop/server target")
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn tcp_accept_many_drains_nonblocking_listener_and_tree_shakes() {
    let source = r#"
fn accepted(socket: i64) -> void {
    print(net.close(socket))
}
fn main() -> i64 {
    let (listener, listenError) = net.tcpListen("127.0.0.1", 0, 8)
    print(listenError)
    let (port, portError) = net.localPort(listener)
    print(portError)
    let (first, firstError) = net.tcpConnect("127.0.0.1", port)
    print(firstError)
    let (second, secondError) = net.tcpConnect("127.0.0.1", port)
    print(secondError)
    let (third, thirdError) = net.tcpConnect("127.0.0.1", port)
    print(thirdError)
    print(net.setNonblocking(listener, true))
    let (acceptedCount, acceptError) = net.tcpAcceptMany(listener, 8, accepted)
    print(acceptedCount)
    print(acceptError)
    print(net.close(first))
    print(net.close(second))
    print(net.close(third))
    print(net.close(listener))
    return 0
}
"#;
    check_source(source).expect("batched TCP accept should typecheck");
    let generated = compile_to_c(source).expect("batched TCP accept should lower natively");
    assert!(generated.contains("flux__net_tcp_accept_many("));
    assert!(generated.contains("O_NONBLOCK"));
    assert!(generated.contains("EAGAIN"));
    assert!(generated.contains("SO_ACCEPTCONN"));
    assert!(generated.contains("acceptMany cancelled by worker scope"));

    let root = std::env::temp_dir().join(format!("flux-net-accept-many-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("batched accept fixture should be writable");
    let source_path = root.join("accept_many.flux");
    fs::write(&source_path, source).expect("batched accept source should be writable");
    let binary = root.join("accept_many");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("batched accept binary should build");
    assert!(
        built.status.success(),
        "batched accept build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("batched accept binary should run");
    assert!(run.status.success());
    let lines = String::from_utf8_lossy(&run.stdout)
        .lines()
        .map(str::to_string)
        .collect::<Vec<_>>();
    assert_eq!(lines.len(), 15);
    assert!(lines.iter().all(|line| line == "nil" || line == "3"));
    assert_eq!(lines[9], "3");
    assert_eq!(lines[10], "nil");

    let blocking = r#"
fn accepted(socket: i64) -> void {
    print(net.close(socket))
}
fn main() -> i64 {
    let (listener, listenError) = net.tcpListen("127.0.0.1", 0, 8)
    print(listenError)
    let (count, failure) = net.tcpAcceptMany(listener, 1, accepted)
    print(count)
    print(failure)
    print(net.close(listener))
    return 0
}
"#;
    let blocking_path = root.join("blocking.flux");
    fs::write(&blocking_path, blocking).expect("blocking accept source should be writable");
    let blocking_binary = root.join("blocking");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&blocking_path)
        .arg("-o")
        .arg(&blocking_binary)
        .output()
        .expect("blocking accept fixture should build");
    assert!(built.status.success());
    let run = Command::new(&blocking_binary)
        .output()
        .expect("blocking accept fixture should run");
    assert!(run.status.success());
    assert!(
        String::from_utf8_lossy(&run.stdout)
            .contains("acceptMany requires a nonblocking TCP listener")
    );

    let max_count_error = check_source(
        "fn accepted(_socket: i64) -> void {\n}\nfn main() -> i64 {\n    let (count, failure) = net.tcpAcceptMany(1, 0, accepted)\n    print(count)\n    print(failure)\n    return 0\n}\n",
    )
    .expect_err("zero maxCount must fail statically");
    assert!(
        max_count_error
            .message
            .contains("net.tcpAcceptMany maxCount must be between 1 and 2147483647")
    );
    let callback_error = check_source(
        "fn accepted(_socket: str) -> void {\n}\nfn main() -> i64 {\n    let (count, failure) = net.tcpAcceptMany(1, 8, accepted)\n    print(count)\n    print(failure)\n    return 0\n}\n",
    )
    .expect_err("batched accept callback type must be exact");
    assert!(
        callback_error
            .message
            .contains("net.tcpAcceptMany callback")
    );

    let unused = r#"
fn accepted(_socket: i64) -> void {
}
fn hidden(listener: i64) -> void {
    let (count, failure) = net.tcpAcceptMany(listener, 8, accepted)
    print(count)
    print(failure)
}
fn main() -> i64 {
    return 0
}
"#;
    let unused_generated = compile_to_c(unused).expect("dead batched accept should tree-shake");
    assert!(!unused_generated.contains("flux__net_tcp_accept_many("));
    assert!(!unused_generated.contains("SO_ACCEPTCONN"));
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn network_timeout_io_is_typed_native_tree_shaken_and_runnable() {
    let source = r#"
fn consume(_socket: i64, text: str) -> void {
    print(text)
}
fn consumeFrom(_socket: i64, text: str, _host: str, _port: i64) -> void {
    print(text)
}
fn closeAccepted(socket: i64) -> void {
    let failure: error = net.close(socket)
    if failure != nil:
        print(failure)
}
fn main() -> i64 {
    let (listener, listenError) = net.listen("127.0.0.1", 0, 8)
    if listenError != nil:
        return 1
    let (port, portError) = net.port(listener)
    if portError != nil:
        return 2
    let (_timedSocket, immediateAccept, immediateAcceptError) = net.acceptTimeout(listener, 0)
    if immediateAcceptError != nil:
        return 3
    print(immediateAccept)
    let (client, connectError) = net.connect("127.0.0.1", port)
    if connectError != nil:
        return 4
    let (server, accepted, acceptError) = net.acceptTimeout(listener, 1000)
    if acceptError != nil:
        return 5
    if accepted == false:
        return 6
    let listenerNonblockingError: error = net.nonblocking(listener, true)
    if listenerNonblockingError != nil:
        return 30
    let (_emptyAcceptedBatch, immediateAcceptBatch, immediateAcceptBatchError) = net.acceptManyTimeout(listener, 8, 0, closeAccepted)
    if immediateAcceptBatchError != nil:
        return 31
    print(immediateAcceptBatch)
    let (batchClient, batchConnectError) = net.connect("127.0.0.1", port)
    if batchConnectError != nil:
        return 32
    let (acceptedBatch, acceptBatchReady, acceptBatchError) = net.acceptManyTimeout(listener, 8, 1000, closeAccepted)
    if acceptBatchError != nil:
        return 33
    if acceptBatchReady == false:
        return 34
    if acceptedBatch != 1:
        return 35
    print(acceptedBatch)
    let (_emptyBytes, immediateRead, immediateReadError) = net.readTimeout(server, 64, 0, consume)
    if immediateReadError != nil:
        return 7
    print(immediateRead)
    let writeError: error = net.write(client, "ping")
    if writeError != nil:
        return 8
    let (bytes, readable, readError) = net.readTimeout(server, 64, 1000, consume)
    if readError != nil:
        return 9
    if readable == false:
        return 10
    print(bytes)
    let serverNonblockingError: error = net.nonblocking(server, true)
    if serverNonblockingError != nil:
        return 18
    let (_emptyBatchBytes, immediateBatch, immediateBatchError) = net.readManyTimeout(server, 64, 8, 0, consume)
    if immediateBatchError != nil:
        return 19
    print(immediateBatch)
    let batchWriteError: error = net.write(client, "batch")
    if batchWriteError != nil:
        return 20
    let (batchBytes, batchReady, batchError) = net.readManyTimeout(server, 64, 8, 1000, consume)
    if batchError != nil:
        return 21
    if batchReady == false:
        return 22
    if batchBytes <= 0:
        return 23
    print(batchBytes)
    let (udpServer, udpBindError) = net.bind("127.0.0.1", 0)
    if udpBindError != nil:
        return 11
    let (udpPort, udpPortError) = net.port(udpServer)
    if udpPortError != nil:
        return 12
    let (_emptyDatagramBytes, immediateDatagram, immediateDatagramError) = net.readFromTimeout(udpServer, 64, 0, consumeFrom)
    if immediateDatagramError != nil:
        return 13
    print(immediateDatagram)
    let (udpClient, udpConnectError) = net.udp("127.0.0.1", udpPort)
    if udpConnectError != nil:
        return 14
    let udpWriteError: error = net.write(udpClient, "pong")
    if udpWriteError != nil:
        return 15
    let (datagramBytes, datagramReady, datagramError) = net.readFromTimeout(udpServer, 64, 1000, consumeFrom)
    if datagramError != nil:
        return 16
    if datagramReady == false:
        return 17
    print(datagramBytes)
    let udpNonblockingError: error = net.nonblocking(udpServer, true)
    if udpNonblockingError != nil:
        return 24
    let (_emptyDatagramBatchBytes, immediateDatagramBatch, immediateDatagramBatchError) = net.readManyFromTimeout(udpServer, 64, 8, 0, consumeFrom)
    if immediateDatagramBatchError != nil:
        return 25
    print(immediateDatagramBatch)
    let udpBatchWriteError: error = net.write(udpClient, "batch")
    if udpBatchWriteError != nil:
        return 26
    let (datagramBatchBytes, datagramBatchReady, datagramBatchError) = net.readManyFromTimeout(udpServer, 64, 8, 1000, consumeFrom)
    if datagramBatchError != nil:
        return 27
    if datagramBatchReady == false:
        return 28
    if datagramBatchBytes != 5:
        return 29
    print(datagramBatchBytes)
    print(net.close(udpClient))
    print(net.close(udpServer))
    print(net.close(batchClient))
    print(net.close(server))
    print(net.close(client))
    print(net.close(listener))
    return 0
}
"#;
    check_source(source).expect("timeout I/O fixture should typecheck");
    let generated = compile_to_c(source).expect("timeout I/O should lower natively");
    assert!(generated.contains("flux__net_tcp_accept_with_timeout("));
    assert!(generated.contains("flux__net_tcp_accept_many_with_timeout("));
    assert!(generated.contains("flux__net_receive_text_with_timeout("));
    assert!(generated.contains("flux__net_receive_text_many_with_timeout("));
    assert!(generated.contains("flux__net_receive_text_from_with_timeout("));
    assert!(generated.contains("flux__net_receive_text_from_many_with_timeout("));
    assert!(generated.contains("flux__net_poll_cancellable("));
    assert!(generated.contains("acceptTimeout cancelled by worker scope"));
    assert!(generated.contains("acceptManyTimeout cancelled by worker scope"));
    assert!(generated.contains("readTimeout cancelled by worker scope"));
    assert!(generated.contains("readManyTimeout cancelled by worker scope"));
    assert!(generated.contains("readFromTimeout cancelled by worker scope"));
    assert!(generated.contains("readManyFromTimeout cancelled by worker scope"));
    assert!(generated.contains("MSG_DONTWAIT"));
    assert!(
        generated.contains("recv((int)socket_handle, buffer, (size_t)max_bytes, MSG_DONTWAIT)")
    );
    assert!(generated.contains("MSG_TRUNC | MSG_DONTWAIT"));

    let root = std::env::temp_dir().join(format!("flux-net-timeout-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("timeout I/O fixture should be writable");
    let source_path = root.join("timeout.flux");
    fs::write(&source_path, source).expect("timeout I/O source should be writable");
    let binary = root.join("timeout");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("timeout I/O binary should build");
    assert!(
        built.status.success(),
        "timeout I/O build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("timeout I/O binary should run");
    assert!(
        run.status.success(),
        "timeout I/O run failed: {}\n{}",
        String::from_utf8_lossy(&run.stdout),
        String::from_utf8_lossy(&run.stderr)
    );
    let output = String::from_utf8_lossy(&run.stdout);
    assert!(output.contains("false\nfalse\n1\nfalse\n"));
    assert!(output.contains("ping\n4\nfalse\nbatch\n5\n"));
    assert!(output.contains("pong\n4\nfalse\nbatch\n5\n"));

    let invalid_timeout = check_source(
        "fn main() -> i64 {\n    let (_socket, _ready, _failure) = net.acceptTimeout(1, -2)\n    return 0\n}\n",
    )
    .expect_err("timeouts below -1 must fail statically");
    assert!(invalid_timeout.message.contains("timeoutMillis must be -1"));
    let invalid_batch_timeout = check_source(
        "fn accepted(_socket: i64) -> void {\n}\nfn main() -> i64 {\n    let (_count, _ready, _failure) = net.acceptManyTimeout(1, 8, -2, accepted)\n    return 0\n}\n",
    )
    .expect_err("batched accept timeouts below -1 must fail statically");
    assert!(
        invalid_batch_timeout
            .message
            .contains("net.acceptManyTimeout timeoutMillis must be -1")
    );

    let dead = r#"
fn accepted(_socket: i64) -> void {
}
fn consume(_socket: i64, _text: str) -> void {
}
fn consumeFrom(_socket: i64, _text: str, _host: str, _port: i64) -> void {
}
fn hidden(socket: i64) -> void {
    let (_accepted, _acceptReady, _acceptFailure) = net.acceptManyTimeout(socket, 8, 10, accepted)
    let (_bytes, _ready, _failure) = net.readTimeout(socket, 64, 10, consume)
    let (_batchBytes, _batchReady, _batchFailure) = net.readManyTimeout(socket, 64, 8, 10, consume)
    let (_datagramBatchBytes, _datagramBatchReady, _datagramBatchFailure) = net.readManyFromTimeout(socket, 64, 8, 10, consumeFrom)
}
fn main() -> i64 {
    return 0
}
"#;
    let dead_generated = compile_to_c(dead).expect("dead timeout I/O should tree-shake");
    assert!(!dead_generated.contains("flux__net_tcp_accept_many_with_timeout("));
    assert!(!dead_generated.contains("flux__net_receive_text_with_timeout("));
    assert!(!dead_generated.contains("flux__net_receive_text_many_with_timeout("));
    assert!(!dead_generated.contains("flux__net_receive_text_from_many_with_timeout("));
    assert!(!dead_generated.contains("flux__net_poll_cancellable("));
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn tcp_half_close_is_typed_native_tree_shaken_and_runnable() {
    let listener = TcpListener::bind("127.0.0.1:0").expect("loopback listener should bind");
    let port = listener.local_addr().unwrap().port();
    let server = thread::spawn(move || {
        let (mut stream, _) = listener
            .accept()
            .expect("loopback connection should be accepted");
        let mut request = String::new();
        stream
            .read_to_string(&mut request)
            .expect("server should observe the client write-side EOF");
        assert_eq!(request, "ping");
        stream
            .write_all(b"pong")
            .expect("server response should be writable after client half-close");
    });

    let source = format!(
        r#"fn consume(_socket: i64, text: str) -> void {{
    print(text)
}}
fn main() -> i64 {{
    let (socket, connectError) = net.tcpConnect("127.0.0.1", {port})
    print(connectError)
    print(net.sendText(socket, "ping"))
    print(net.shutdownWrite(socket))
    let (received, receiveError) = net.receiveText(socket, 64, consume)
    print(received)
    print(receiveError)
    print(net.shutdownRead(socket))
    print(net.close(socket))
    return 0
}}
"#
    );
    check_source(&source).expect("TCP half-close calls should typecheck");
    let generated = compile_to_c(&source).expect("TCP half-close should lower on Linux");
    assert!(generated.contains("flux__net_shutdown_read("));
    assert!(generated.contains("flux__net_shutdown_write("));
    assert!(generated.contains("shutdown((int)socket_handle, how)"));
    assert!(generated.contains("SHUT_RD"));
    assert!(generated.contains("SHUT_WR"));

    let root = std::env::temp_dir().join(format!("flux-net-shutdown-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("TCP shutdown fixture should be writable");
    let source_path = root.join("shutdown.flux");
    fs::write(&source_path, &source).expect("TCP shutdown source should be writable");
    let binary = root.join("shutdown");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("TCP shutdown binary should build");
    assert!(
        built.status.success(),
        "TCP shutdown build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("TCP shutdown binary should run");
    assert!(run.status.success());
    assert_eq!(
        String::from_utf8_lossy(&run.stdout),
        "nil\nnil\nnil\npong\n4\nnil\nnil\nnil\n"
    );
    server.join().expect("loopback server should complete");

    let listener_source = r#"fn main() -> i64 {
    let (listener, listenError) = net.tcpListen("127.0.0.1", 0, 1)
    print(listenError)
    print(net.shutdownRead(listener))
    print(net.close(listener))
    return 0
}
"#;
    let listener_path = root.join("listener.flux");
    fs::write(&listener_path, listener_source)
        .expect("listener shutdown source should be writable");
    let listener_binary = root.join("listener");
    let listener_built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&listener_path)
        .arg("-o")
        .arg(&listener_binary)
        .output()
        .expect("listener shutdown binary should build");
    assert!(
        listener_built.status.success(),
        "listener shutdown build failed: {}",
        String::from_utf8_lossy(&listener_built.stderr)
    );
    let listener_run = Command::new(&listener_binary)
        .output()
        .expect("listener shutdown binary should run");
    assert!(listener_run.status.success());
    assert_eq!(
        String::from_utf8_lossy(&listener_run.stdout),
        "nil\nsocket shutdown requires a connected TCP socket\nnil\n"
    );

    let socket_error = check_source(
        "fn main() -> i64 {\n    print(net.shutdownWrite(\"bad\"))\n    return 0\n}\n",
    )
    .expect_err("TCP shutdown socket must be an i64 handle");
    assert!(
        socket_error.message.contains("net.shutdownWrite socket")
            && socket_error.message.contains("expected i64")
    );

    let unused = r#"
fn hidden(socket: i64) -> void {
    print(net.shutdownRead(socket))
    print(net.shutdownWrite(socket))
}
fn main() -> i64 {
    return 0
}
"#;
    let unused_generated =
        compile_to_c(unused).expect("dead TCP shutdown support should tree-shake");
    assert!(!unused_generated.contains("flux__net_shutdown_read("));
    assert!(!unused_generated.contains("flux__net_shutdown_write("));
    assert!(!unused_generated.contains("#include <sys/socket.h>"));
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn socket_addresses_are_typed_borrowed_tree_shaken_and_runnable() {
    let listener = TcpListener::bind("127.0.0.1:0").expect("loopback listener should bind");
    let port = listener.local_addr().unwrap().port();
    let source = format!(
        r#"fn inspect(host: str, port: i64) -> void {{
    print(host)
    print(port)
}}
fn main() -> i64 {{
    let (socket, connectError) = net.tcpConnect("127.0.0.1", {port})
    print(connectError)
    print(net.peerAddress(socket, inspect))
    print(net.localAddress(socket, inspect))
    print(net.close(socket))
    return 0
}}
"#
    );
    check_source(&source).expect("connected peer inspection should typecheck");
    let generated = compile_to_c(&source).expect("connected peer inspection should lower on Linux");
    assert!(generated.contains("flux__net_peer_address("));
    assert!(generated.contains("flux__net_local_address("));
    assert!(generated.contains("getpeername("));
    assert!(generated.contains("getsockname("));
    assert!(generated.contains("inet_ntop("));

    let root = std::env::temp_dir().join(format!("flux-net-peer-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("peer address fixture should be writable");
    let source_path = root.join("peer.flux");
    fs::write(&source_path, &source).expect("peer address source should be writable");
    let binary = root.join("peer");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("peer address binary should build");
    assert!(
        built.status.success(),
        "peer address build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("peer address binary should run");
    assert!(run.status.success());
    let lines = String::from_utf8_lossy(&run.stdout)
        .lines()
        .map(str::to_string)
        .collect::<Vec<_>>();
    assert_eq!(lines.len(), 8);
    assert_eq!(lines[0], "nil");
    assert_eq!(lines[1], "127.0.0.1");
    assert_eq!(lines[2], port.to_string());
    assert_eq!(lines[3], "nil");
    assert_eq!(lines[4], "127.0.0.1");
    assert!(lines[5].parse::<u16>().is_ok_and(|port| port > 0));
    assert_eq!(&lines[6..], &["nil", "nil"]);

    let callback_error = check_source(
        "fn inspect(_host: str) -> void {\n}\nfn main() -> i64 {\n    print(net.peerAddress(1, inspect))\n    return 0\n}\n",
    )
    .expect_err("peer address callback shape must be exact");
    assert!(callback_error.message.contains("net.peerAddress callback"));
    let socket_error = check_source(
        "fn inspect(_host: str, _port: i64) -> void {\n}\nfn main() -> i64 {\n    print(net.peerAddress(\"bad\", inspect))\n    return 0\n}\n",
    )
    .expect_err("peer address socket must be an i64 handle");
    assert!(
        socket_error.message.contains("net.peerAddress socket")
            && socket_error.message.contains("expected i64")
    );
    let local_callback_error = check_source(
        "fn inspect(_host: str) -> void {\n}\nfn main() -> i64 {\n    print(net.localAddress(1, inspect))\n    return 0\n}\n",
    )
    .expect_err("local address callback shape must be exact");
    assert!(
        local_callback_error
            .message
            .contains("net.localAddress callback")
    );
    let local_socket_error = check_source(
        "fn inspect(_host: str, _port: i64) -> void {\n}\nfn main() -> i64 {\n    print(net.localAddress(\"bad\", inspect))\n    return 0\n}\n",
    )
    .expect_err("local address socket must be an i64 handle");
    assert!(
        local_socket_error
            .message
            .contains("net.localAddress socket")
            && local_socket_error.message.contains("expected i64")
    );

    let unused = r#"
fn inspect(_host: str, _port: i64) -> void {
}
fn hidden(socket: i64) -> void {
    print(net.peerAddress(socket, inspect))
    print(net.localAddress(socket, inspect))
}
fn main() -> i64 {
    return 0
}
"#;
    let unused_generated =
        compile_to_c(unused).expect("dead peer-address support should tree-shake");
    assert!(!unused_generated.contains("flux__net_peer_address("));
    assert!(!unused_generated.contains("flux__net_local_address("));
    let _ = fs::remove_dir_all(&root);
    drop(listener);
}

#[test]
fn http_request_head_is_typed_borrowed_tree_shaken_and_runnable() {
    let source = r#"
fn handleRequest(socket: i64, method: str, target: str, version: str) -> void {
    print(socket >= 0)
    print(method)
    print(target)
    print(version)
}
fn main() -> i64 {
    let (received, receiveError) = http.receiveRequestHead(1, 4096, handleRequest)
    print(received)
    print(receiveError)
    return 0
}
"#;
    check_source(source).expect("HTTP request-head receive should typecheck");
    let generated = compile_to_c(source).expect("HTTP request-head receive should lower on Linux");
    assert!(generated.contains("flux__net_http_receive_request_head("));
    assert!(generated.contains("HTTP/1.1"));
    assert!(generated.contains("HTTP request head exceeds maxBytes"));
    assert!(generated.contains("#include <sys/socket.h>"));

    let invalid_limit = check_source(
        "fn handle(socket: i64, method: str, target: str, version: str) -> void {\n    print(socket)\n    print(method)\n    print(target)\n    print(version)\n}\nfn main() -> i64 {\n    let (_, receiveError) = http.receiveRequestHead(1, 0, handle)\n    print(receiveError)\n    return 0\n}\n",
    )
    .expect_err("constant HTTP request limit outside the valid range must fail");
    assert!(
        invalid_limit
            .message
            .contains("http.receiveRequestHead maxBytes must be between 1 and 65536")
    );

    let unused = r#"
fn handleRequest(socket: i64, method: str, target: str, version: str) -> void {
    print(socket)
    print(method)
    print(target)
    print(version)
}
fn hidden() -> void {
    let (received, receiveError) = http.receiveRequestHead(1, 4096, handleRequest)
    print(received)
    print(receiveError)
}
fn main() -> i64 {
    return 0
}
"#;
    let unused_generated =
        compile_to_c(unused).expect("dead HTTP request helper should tree-shake");
    assert!(!unused_generated.contains("flux__net_http_receive_request_head("));

    let listener = TcpListener::bind("127.0.0.1:0").expect("HTTP request listener should bind");
    let port = listener.local_addr().unwrap().port();
    let root = std::env::temp_dir().join(format!("flux-http-request-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("HTTP request fixture should be writable");
    let source_path = root.join("request.flux");
    fs::write(
        &source_path,
        format!(
            "fn handleRequest(socket: i64, method: str, target: str, version: str) -> void {{\n    print(socket >= 0)\n    print(method)\n    print(target)\n    print(version)\n}}\nfn main() -> i64 {{\n    let (socket, connectError) = net.tcpConnect(\"127.0.0.1\", {port})\n    print(connectError)\n    let (received, receiveError) = http.receiveRequestHead(socket, 4096, handleRequest)\n    print(received > 0)\n    print(receiveError)\n    print(net.close(socket))\n    return 0\n}}\n"
        ),
    )
    .expect("HTTP request Flux source should be writable");
    let binary = root.join("request");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("HTTP request Flux binary should build");
    assert!(
        built.status.success(),
        "HTTP request fixture build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let child = Command::new(&binary)
        .stdout(Stdio::piped())
        .spawn()
        .expect("HTTP request Flux binary should start");
    let (mut stream, _) = listener
        .accept()
        .expect("HTTP request connection should accept");
    stream
        .write_all(b"GET /hello?x=1 HTTP/1.1\r\nHost: example.test\r\n\r\nBODY")
        .expect("HTTP request should be writable");
    let output = child
        .wait_with_output()
        .expect("HTTP request Flux binary should finish");
    assert!(output.status.success());
    assert_eq!(
        String::from_utf8_lossy(&output.stdout),
        "nil\ntrue\nGET\n/hello?x=1\nHTTP/1.1\ntrue\nnil\nnil\n"
    );
    let _ = fs::remove_dir_all(&root);
}

