#[test]
fn http_text_request_body_is_bounded_borrowed_and_runnable() {
    let source = r#"
fn handleRequest(socket: i64, method: str, target: str, version: str) -> void {
    print(socket >= 0)
    print(method)
    print(target)
    print(version)
}
fn handleHeader(socket: i64, name: str, value: str) -> void {
    print(socket >= 0)
    print(name)
    print(value)
}
fn handleBody(socket: i64, body: str) -> void {
    print(socket >= 0)
    print(body)
}
fn main() -> i64 {
    let (received, receiveError) = http.receiveRequestWithTextBody(1, 4096, 1024, handleRequest, handleHeader, handleBody)
    print(received)
    print(receiveError)
    return 0
}
"#;
    check_source(source).expect("HTTP request text body should typecheck");
    let generated = compile_to_c(source).expect("HTTP request text body should lower on Linux");
    assert!(generated.contains("flux__net_http_receive_request_with_text_body_v2("));
    assert!(generated.contains("duplicate Content-Length is not supported"));
    assert!(generated.contains("unsupported HTTP Transfer-Encoding"));
    assert!(generated.contains("Content-Length with Transfer-Encoding is not supported"));
    assert!(generated.contains("HTTP request body exceeds maxBodyBytes"));
    assert!(generated.contains("body_length > ((size_t)max_body_bytes - digit_value) / 10u"));
    assert!(generated.contains("HTTP request body contains invalid UTF-8"));

    let invalid_limit = check_source(
        "fn request(socket: i64, method: str, target: str, version: str) -> void {\n    print(socket)\n    print(method)\n    print(target)\n    print(version)\n}\nfn header(socket: i64, name: str, value: str) -> void {\n    print(socket)\n    print(name)\n    print(value)\n}\nfn body(socket: i64, value: str) -> void {\n    print(socket)\n    print(value)\n}\nfn main() -> i64 {\n    let (_, failure) = http.receiveRequestWithTextBody(1, 4096, 65537, request, header, body)\n    print(failure)\n    return 0\n}\n",
    )
    .expect_err("constant HTTP request body limit outside the valid range must fail");
    assert!(
        invalid_limit
            .message
            .contains("http.receiveRequestWithTextBody maxBodyBytes must be between 0 and 65536")
    );

    let unused = source.replace("fn main() -> i64 {\n    let (received, receiveError) = http.receiveRequestWithTextBody(1, 4096, 1024, handleRequest, handleHeader, handleBody)\n    print(received)\n    print(receiveError)\n    return 0\n}", "fn hidden() -> void {\n    let (received, receiveError) = http.receiveRequestWithTextBody(1, 4096, 1024, handleRequest, handleHeader, handleBody)\n    print(received)\n    print(receiveError)\n}\nfn main() -> i64 {\n    return 0\n}");
    let unused_generated =
        compile_to_c(&unused).expect("dead HTTP request-body helper should tree-shake");
    assert!(!unused_generated.contains("flux__net_http_receive_request_with_text_body_v2("));

    let listener = TcpListener::bind("127.0.0.1:0").expect("HTTP body listener should bind");
    let port = listener.local_addr().unwrap().port();
    let root = std::env::temp_dir().join(format!("flux-http-body-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("HTTP body fixture should be writable");
    let source_path = root.join("body.flux");
    fs::write(
        &source_path,
        format!(
            "fn handleRequest(socket: i64, method: str, target: str, version: str) -> void {{\n    print(socket >= 0)\n    print(method)\n    print(target)\n    print(version)\n}}\nfn handleHeader(socket: i64, name: str, value: str) -> void {{\n    print(socket >= 0)\n    print(name)\n    print(value)\n}}\nfn handleBody(socket: i64, body: str) -> void {{\n    print(socket >= 0)\n    print(body)\n}}\nfn handleExtra(socket: i64, body: str) -> void {{\n    print(socket >= 0)\n    print(body)\n}}\nfn main() -> i64 {{\n    let (socket, connectError) = net.tcpConnect(\"127.0.0.1\", {port})\n    print(connectError)\n    let (received, receiveError) = http.receiveRequestWithTextBody(socket, 4096, 1024, handleRequest, handleHeader, handleBody)\n    print(received > 0)\n    print(receiveError)\n    let (extraReceived, extraError) = net.receiveText(socket, 5, handleExtra)\n    print(extraReceived == 5)\n    print(extraError)\n    print(net.close(socket))\n    return 0\n}}\n"
        ),
    )
    .expect("HTTP body Flux source should be writable");
    let binary = root.join("body");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("HTTP body Flux binary should build");
    assert!(
        built.status.success(),
        "HTTP body fixture build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let child = Command::new(&binary)
        .stdout(Stdio::piped())
        .spawn()
        .expect("HTTP body Flux binary should start");
    let (mut stream, _) = listener
        .accept()
        .expect("HTTP body connection should accept");
    stream
        .write_all(
            b"POST /submit HTTP/1.1\r\nHost: example.test\r\nContent-Length: 5\r\n\r\nhelloEXTRA",
        )
        .expect("HTTP body request should be writable");
    let output = child
        .wait_with_output()
        .expect("HTTP body Flux binary should finish");
    assert!(output.status.success());
    assert_eq!(
        String::from_utf8_lossy(&output.stdout),
        "nil\ntrue\nPOST\n/submit\nHTTP/1.1\ntrue\nHost\nexample.test\ntrue\nContent-Length\n5\ntrue\nhello\ntrue\nnil\ntrue\nEXTRA\ntrue\nnil\nnil\n"
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn http_binary_request_body_preserves_arbitrary_bytes_and_does_not_overread() {
    let source = r#"
fn request(_socket: i64, _method: str, _target: str, _version: str) -> void {
}
fn header(_socket: i64, _name: str, _value: str) -> void {
}
fn body(_socket: i64, bytes: i64[]) -> void {
    print(bytes.count)
}
fn main() -> i64 {
    let (received, failure) = http.readRequestBytes(1, 4096, 1024, request, header, body)
    print(received)
    print(failure)
    return 0
}
"#;
    check_source(source).expect("HTTP binary request body should typecheck");
    let generated = compile_to_c(source).expect("HTTP binary request body should lower on Linux");
    assert!(generated.contains("flux__net_http_receive_request_with_binary_body_v2("));
    assert!(generated.contains("body_callback(socket_handle, (struct flux__list)"));
    assert!(!generated.contains("HTTP request body contains a NUL byte"));
    assert!(!generated.contains("HTTP request body contains invalid UTF-8"));

    let invalid_callback = check_source(
        "fn request(_socket: i64, _method: str, _target: str, _version: str) -> void {\n}\nfn header(_socket: i64, _name: str, _value: str) -> void {\n}\nfn body(_socket: i64, _body: str) -> void {\n}\nfn main() -> i64 {\n    let (_received, _failure) = http.readRequestBytes(1, 4096, 1024, request, header, body)\n    return 0\n}\n",
    )
    .expect_err("HTTP binary request body callback must receive bytes");
    assert!(
        invalid_callback
            .message
            .contains("http.readRequestBytes bodyCallback")
    );

    let invalid_limit = check_source(
        "fn request(_socket: i64, _method: str, _target: str, _version: str) -> void {\n}\nfn header(_socket: i64, _name: str, _value: str) -> void {\n}\nfn body(_socket: i64, _body: i64[]) -> void {\n}\nfn main() -> i64 {\n    let (_received, _failure) = http.readRequestBytes(1, 4096, 65537, request, header, body)\n    return 0\n}\n",
    )
    .expect_err("HTTP binary request body limit must remain bounded");
    assert!(
        invalid_limit
            .message
            .contains("http.readRequestBytes maxBodyBytes must be between 0 and 65536")
    );

    let unused = source.replace(
        "fn main() -> i64 {\n    let (received, failure) = http.readRequestBytes(1, 4096, 1024, request, header, body)\n    print(received)\n    print(failure)\n    return 0\n}",
        "fn hidden() -> void {\n    let (received, failure) = http.readRequestBytes(1, 4096, 1024, request, header, body)\n    print(received)\n    print(failure)\n}\nfn main() -> i64 {\n    return 0\n}",
    );
    let unused_generated =
        compile_to_c(&unused).expect("dead HTTP binary request helper should tree-shake");
    assert!(!unused_generated.contains("flux__net_http_receive_request_with_binary_body_v2("));

    let listener =
        TcpListener::bind("127.0.0.1:0").expect("HTTP binary request listener should bind");
    let port = listener.local_addr().unwrap().port();
    let root =
        std::env::temp_dir().join(format!("flux-http-binary-request-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("HTTP binary request fixture should be writable");
    let source_path = root.join("request.flux");
    fs::write(
        &source_path,
        format!(
            "fn request(_socket: i64, _method: str, _target: str, _version: str) -> void {{\n}}\nfn header(_socket: i64, _name: str, _value: str) -> void {{\n}}\nfn body(_socket: i64, bytes: i64[]) -> void {{\n    print(bytes.count)\n    for index in 0..bytes.count:\n        print(bytes[index])\n}}\nfn tail(_socket: i64, value: str) -> void {{\n    print(value)\n}}\nfn main() -> i64 {{\n    let (socket, connectError) = net.connect(\"127.0.0.1\", {port})\n    print(connectError)\n    let (received, receiveError) = http.readRequestBytes(socket, 4096, 1024, request, header, body)\n    print(received > 0)\n    print(receiveError)\n    let (tailBytes, tailError) = net.read(socket, 4, tail)\n    print(tailBytes)\n    print(tailError)\n    print(net.close(socket))\n    return 0\n}}\n"
        ),
    )
    .expect("HTTP binary request Flux source should be writable");
    let binary = root.join("request");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("HTTP binary request Flux binary should build");
    assert!(
        built.status.success(),
        "HTTP binary request fixture build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );

    let child = Command::new(&binary)
        .stdout(Stdio::piped())
        .spawn()
        .expect("HTTP binary request Flux binary should start");
    let (mut stream, _) = listener
        .accept()
        .expect("HTTP binary request connection should accept");
    stream
        .write_all(b"POST /binary HTTP/1.1\r\nHost: example.test\r\nContent-Length: 4\r\n\r\n")
        .expect("HTTP binary request head should be writable");
    stream
        .write_all(&[0, 127, 128, 255])
        .expect("HTTP binary request body should be writable");
    stream
        .write_all(b"TAIL")
        .expect("HTTP binary request tail should be writable");
    let output = child
        .wait_with_output()
        .expect("HTTP binary request Flux binary should finish");
    assert!(
        output.status.success(),
        "HTTP binary request run failed: stdout={:?} stderr={:?}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(
        String::from_utf8_lossy(&output.stdout),
        "nil\n4\n0\n127\n128\n255\ntrue\nnil\nTAIL\n4\nnil\nnil\n"
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn http_serve_once_owns_one_connection_lifecycle_and_tree_shakes() {
    let source = r#"
fn request(_socket: i64, _method: str, _target: str, _version: str) -> void {
}
fn header(_socket: i64, _name: str, _value: str) -> void {
}
fn body(_socket: i64, _body: str) -> void {
}
fn main() -> i64 {
    print(http.serveOnce(1, 4096, 1024, request, header, body))
    return 0
}
"#;
    check_source(source).expect("single-request HTTP server helper should typecheck");
    let generated = compile_to_c(source).expect("single-request HTTP server helper should lower");
    assert!(generated.contains("flux__net_http_serve_once("));
    assert!(generated.contains("flux__net_http_receive_request_with_text_body_v2("));
    assert!(generated.contains("HTTP server requires a TCP listener"));

    let invalid_limit = check_source(
        "fn request(_socket: i64, _method: str, _target: str, _version: str) -> void {\n}\nfn header(_socket: i64, _name: str, _value: str) -> void {\n}\nfn body(_socket: i64, _body: str) -> void {\n}\nfn main() -> i64 {\n    print(http.serveOnce(1, 0, 1024, request, header, body))\n    return 0\n}\n",
    )
    .expect_err("serveOnce must reject an invalid constant head limit");
    assert!(
        invalid_limit
            .message
            .contains("http.serveOnce maxHeadBytes must be between 1 and 65536")
    );

    let unused = source.replace(
        "fn main() -> i64 {\n    print(http.serveOnce(1, 4096, 1024, request, header, body))\n    return 0\n}",
        "fn hidden() -> void {\n    print(http.serveOnce(1, 4096, 1024, request, header, body))\n}\nfn main() -> i64 {\n    return 0\n}",
    );
    let unused_generated = compile_to_c(&unused).expect("dead serveOnce helper should tree-shake");
    assert!(!unused_generated.contains("flux__net_http_serve_once("));

    let probe = TcpListener::bind("127.0.0.1:0").expect("HTTP serveOnce port should allocate");
    let port = probe.local_addr().unwrap().port();
    drop(probe);
    let root = std::env::temp_dir().join(format!("flux-http-serve-once-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("HTTP serveOnce fixture should be writable");
    let source_path = root.join("serve.flux");
    fs::write(
        &source_path,
        format!(
            "fn request(socket: i64, method: str, target: str, version: str) -> void {{\n    print(method)\n    print(target)\n    print(version)\n    print(http.sendTextResponse(socket, 200, \"text/plain\", \"served\"))\n}}\nfn header(_socket: i64, name: str, value: str) -> void {{\n    print(name)\n    print(value)\n}}\nfn body(_socket: i64, value: str) -> void {{\n    print(value)\n}}\nfn main() -> i64 {{\n    let (listener, listenError) = net.tcpListen(\"127.0.0.1\", {port}, 8)\n    print(listenError)\n    print(http.serveOnce(listener, 4096, 1024, request, header, body))\n    print(net.close(listener))\n    return 0\n}}\n"
        ),
    )
    .expect("HTTP serveOnce Flux source should be writable");
    let binary = root.join("serve");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("HTTP serveOnce Flux binary should build");
    assert!(
        built.status.success(),
        "HTTP serveOnce fixture build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let child = Command::new(&binary)
        .stdout(Stdio::piped())
        .spawn()
        .expect("HTTP serveOnce Flux binary should start");
    let mut stream = (0..100)
        .find_map(
            |_| match std::net::TcpStream::connect(("127.0.0.1", port)) {
                Ok(stream) => Some(stream),
                Err(_) => {
                    thread::sleep(Duration::from_millis(5));
                    None
                }
            },
        )
        .expect("HTTP serveOnce listener should become reachable");
    stream
        .write_all(b"POST /one HTTP/1.1\r\nHost: example.test\r\nContent-Length: 5\r\n\r\nhello")
        .expect("HTTP serveOnce request should be writable");
    let mut response = String::new();
    stream
        .read_to_string(&mut response)
        .expect("HTTP serveOnce response should be readable through close");
    let output = child
        .wait_with_output()
        .expect("HTTP serveOnce Flux binary should finish");
    assert!(output.status.success());
    assert!(response.contains("HTTP/1.1 200"));
    assert!(response.ends_with("served"));
    assert_eq!(
        String::from_utf8_lossy(&output.stdout),
        "nil\nPOST\n/one\nHTTP/1.1\nnil\nHost\nexample.test\nContent-Length\n5\nhello\nnil\nnil\n"
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn http_serve_is_the_continuous_default_and_handles_multiple_connections() {
    let source = r#"
fn request(_socket: i64, _method: str, _target: str, _version: str) -> void {
}
fn header(_socket: i64, _name: str, _value: str) -> void {
}
fn body(_socket: i64, _body: str) -> void {
}
fn main() -> i64 {
    print(http.serve(1, 4096, 1024, request, header, body))
    return 0
}
"#;
    check_source(source).expect("canonical HTTP server helper should typecheck");
    let generated = compile_to_c(source).expect("canonical HTTP server helper should lower");
    assert!(generated.contains("flux__net_http_serve("));
    assert!(generated.contains("for (;;)"));

    let probe = TcpListener::bind("127.0.0.1:0").expect("HTTP serve port should allocate");
    let port = probe.local_addr().unwrap().port();
    drop(probe);
    let root = std::env::temp_dir().join(format!("flux-http-serve-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("HTTP serve fixture should be writable");
    let source_path = root.join("serve.flux");
    fs::write(
        &source_path,
        format!(
            "fn request(socket: i64, _method: str, _target: str, _version: str) -> void {{\n    print(http.respond(socket, 200, \"text/plain\", \"served\"))\n}}\nfn header(_socket: i64, _name: str, _value: str) -> void {{\n}}\nfn body(_socket: i64, _value: str) -> void {{\n}}\nfn main() -> i64 {{\n    let (listener, listenError) = net.listen(\"127.0.0.1\", {port}, 8)\n    print(listenError)\n    print(http.serve(listener, 4096, 1024, request, header, body))\n    return 0\n}}\n"
        ),
    )
    .expect("HTTP serve Flux source should be writable");
    let binary = root.join("serve");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("HTTP serve Flux binary should build");
    assert!(
        built.status.success(),
        "HTTP serve fixture build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let mut child = Command::new(&binary)
        .stdout(Stdio::piped())
        .spawn()
        .expect("HTTP serve Flux binary should start");

    for target in ["/one", "/two"] {
        let mut stream = (0..100)
            .find_map(
                |_| match std::net::TcpStream::connect(("127.0.0.1", port)) {
                    Ok(stream) => Some(stream),
                    Err(_) => {
                        thread::sleep(Duration::from_millis(5));
                        None
                    }
                },
            )
            .expect("HTTP serve listener should remain reachable");
        stream
            .write_all(format!("GET {target} HTTP/1.1\r\nHost: example.test\r\n\r\n").as_bytes())
            .expect("HTTP serve request should be writable");
        let mut response = String::new();
        stream
            .read_to_string(&mut response)
            .expect("HTTP serve response should be readable through close");
        assert!(response.contains("HTTP/1.1 200"));
        assert!(response.ends_with("served"));
    }

    child
        .kill()
        .expect("continuous HTTP server should be stoppable by its owner process");
    let _ = child.wait();
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn http_serve_concurrent_uses_structured_request_workers() {
    let source = r#"
fn request(socket: i64, _method: str, _target: str, _version: str) -> void {
    time.sleep(250)
    let _responseError: error = http.respond(socket, 200, "text/plain", "served")
}
fn header(_socket: i64, _name: str, _value: str) -> void {
}
fn body(_socket: i64, _body: str) -> void {
}
fn serve(listener: i64) -> void {
    let _serveError: error = http.serveConcurrent(listener, 4096, 1024, request, header, body)
}
fn response(_socket: i64, _version: str, _status: i64, _reason: str) -> void {
}
fn responseHeader(_socket: i64, _name: str, _value: str) -> void {
}
fn responseBody(_socket: i64, value: str) -> void {
    print(value)
}
fn main() -> i64 {
    print(http.serveConcurrent(1, 4096, 1024, request, header, body))
    return 0
}
"#;
    check_source(source).expect("structured concurrent HTTP server should typecheck");
    let generated = compile_to_c(source).expect("structured concurrent HTTP server should lower");
    assert!(generated.contains("flux__net_http_serve_concurrent("));
    assert!(generated.contains("flux__worker_start_with_state(flux__net_http_concurrent_entry"));
    assert!(generated.contains("int64_t handles[64]"));
    assert!(generated.contains("size_t payload_slots[64]"));
    assert!(generated.contains("struct flux__http_concurrent_payload payloads[64]"));
    assert!(generated.contains("struct flux__worker_state worker_states[64]"));
    assert!(generated.contains("&worker_states[payload_index]"));
    assert!(generated.contains("state->heap_owned = heap_owned"));
    assert!(generated.contains("if (heap_owned) free(state)"));
    assert!(generated.contains(
        "flux__net_http_concurrent_payload_slot(payload_slots, pending, (size_t)max_concurrent)"
    ));
    assert!(generated.contains("payload_slots[pending] = payload_index"));
    assert!(!generated.contains("malloc(sizeof(*payload))"));
    assert!(!generated.contains("free(payload)"));
    assert!(
        generated.contains("static pthread_cond_t flux__worker_changed = PTHREAD_COND_INITIALIZER")
    );
    assert!(generated.contains("static bool flux__worker_done(int64_t handle)"));
    assert!(
        generated.contains(
            "static bool flux__worker_wait_any_done(const int64_t *handles, size_t count)"
        )
    );
    assert!(generated.contains("pthread_cond_wait(&flux__worker_changed, &flux__worker_mutex)"));
    assert!(generated.contains("current != NULL && current->cancel_requested"));
    assert!(
        generated
            .contains("flux__net_http_reap_concurrent_ready(handles, payload_slots, &pending)")
    );
    assert!(generated.contains("flux__net_http_cancel_join_concurrent_batch(handles, pending)"));
    assert!(generated.contains("if (!flux__worker_wait_any_done(handles, pending))"));
    assert!(!generated.contains("flux__worker_join(handles[0])"));
    assert!(generated.contains("http.serveConcurrent cancelled by worker scope"));
    assert!(generated.contains("flux__worker_fail_current(error)"));

    let invalid_limit = check_source(&source.replace(
        "http.serveConcurrent(listener, 4096, 1024, request, header, body)",
        "http.serveConcurrent(listener, 0, 1024, request, header, body)",
    ))
    .expect_err("serveConcurrent must reject an invalid constant head limit");
    assert!(
        invalid_limit
            .message
            .contains("http.serveConcurrent maxHeadBytes must be between 1 and 65536")
    );

    let probe =
        TcpListener::bind("127.0.0.1:0").expect("concurrent HTTP server port should allocate");
    let port = probe.local_addr().unwrap().port();
    drop(probe);
    let root =
        std::env::temp_dir().join(format!("flux-http-serve-concurrent-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("concurrent HTTP fixture should be writable");
    let source_path = root.join("serve.flux");
    fs::write(
        &source_path,
        format!(
            "fn request(socket: i64, _method: str, _target: str, _version: str) -> void {{\n    time.sleep(250)\n    let _responseError: error = http.respond(socket, 200, \"text/plain\", \"served\")\n}}\nfn header(_socket: i64, _name: str, _value: str) -> void {{\n}}\nfn body(_socket: i64, _body: str) -> void {{\n}}\nfn serve(listener: i64) -> void {{\n    let _serveError: error = http.serveConcurrent(listener, 4096, 1024, request, header, body)\n}}\nfn response(_socket: i64, _version: str, _status: i64, _reason: str) -> void {{\n}}\nfn responseHeader(_socket: i64, _name: str, _value: str) -> void {{\n}}\nfn responseBody(_socket: i64, value: str) -> void {{\n    print(value)\n}}\nfn main() -> i64 {{\n    let (listener, listenError) = net.listen(\"127.0.0.1\", {port}, 8)\n    if listenError != nil:\n        return 1\n    let (server, startError) = worker.startWith(serve, listener)\n    if startError != nil:\n        return 2\n    time.sleep(50)\n    let (first, firstError) = net.connect(\"127.0.0.1\", {port})\n    if firstError != nil:\n        return 3\n    let (second, secondError) = net.connect(\"127.0.0.1\", {port})\n    if secondError != nil:\n        return 4\n    let firstRequestError: error = http.request(first, \"GET\", \"/one\", \"example.test\", \"text/plain\", \"\")\n    if firstRequestError != nil:\n        return 5\n    let secondRequestError: error = http.request(second, \"GET\", \"/two\", \"example.test\", \"text/plain\", \"\")\n    if secondRequestError != nil:\n        return 6\n    let started = time.monotonic()\n    let (_firstBytes, firstReadError) = http.readResponseBody(first, 4096, 1024, response, responseHeader, responseBody)\n    if firstReadError != nil:\n        return 7\n    let (_secondBytes, secondReadError) = http.readResponseBody(second, 4096, 1024, response, responseHeader, responseBody)\n    if secondReadError != nil:\n        return 8\n    let elapsed = time.monotonic() - started\n    let firstCloseError: error = net.close(first)\n    if firstCloseError != nil:\n        return 9\n    let secondCloseError: error = net.close(second)\n    if secondCloseError != nil:\n        return 10\n    let cancelError: error = worker.cancel(server)\n    if cancelError != nil:\n        return 11\n    let joinError: error = worker.join(server)\n    if joinError != nil:\n        return 12\n    let listenerCloseError: error = net.close(listener)\n    if listenerCloseError != nil:\n        return 13\n    if elapsed >= 450:\n        return 14\n    return 0\n}}\n"
        ),
    )
    .expect("concurrent HTTP Flux source should be writable");
    let native_source = r#"
fn request(socket: i64, _method: str, _target: str, _version: str) -> void {
    time.sleep(250)
    let _responseError: error = http.respond(socket, 200, "text/plain", "served")
}
fn header(_socket: i64, _name: str, _value: str) -> void {
}
fn body(_socket: i64, _body: str) -> void {
}
fn serve(listener: i64) -> void {
    let _serveError: error = http.serveConcurrent(listener, 4096, 1024, request, header, body)
}
fn response(_socket: i64, _version: str, _status: i64, _reason: str) -> void {
}
fn responseHeader(_socket: i64, _name: str, _value: str) -> void {
}
fn responseBody(_socket: i64, value: str) -> void {
    print(value)
}
fn main() -> i64 {
    let (listener, listenError) = net.listen("127.0.0.1", 0, 8)
    if listenError != nil:
        return 1
    let (port, portError) = net.port(listener)
    if portError != nil:
        return 2
    let (server, startError) = worker.startWith(serve, listener)
    if startError != nil:
        return 3
    time.sleep(50)
    let (first, firstError) = net.connect("127.0.0.1", port)
    if firstError != nil:
        return 4
    let (second, secondError) = net.connect("127.0.0.1", port)
    if secondError != nil:
        return 5
    let firstRequestError: error = http.request(first, "GET", "/one", "example.test", "text/plain", "")
    if firstRequestError != nil:
        return 6
    let secondRequestError: error = http.request(second, "GET", "/two", "example.test", "text/plain", "")
    if secondRequestError != nil:
        return 7
    let started: i64 = time.monotonic()
    let (_firstBytes, firstReadError) = http.readResponseBody(first, 4096, 1024, response, responseHeader, responseBody)
    if firstReadError != nil:
        return 8
    let (_secondBytes, secondReadError) = http.readResponseBody(second, 4096, 1024, response, responseHeader, responseBody)
    if secondReadError != nil:
        return 9
    let elapsed: i64 = time.monotonic() - started
    let firstCloseError: error = net.close(first)
    if firstCloseError != nil:
        return 10
    let secondCloseError: error = net.close(second)
    if secondCloseError != nil:
        return 11
    let cancelError: error = worker.cancel(server)
    if cancelError != nil:
        return 12
    let joinError: error = worker.join(server)
    if joinError != nil:
        return 13
    let listenerCloseError: error = net.close(listener)
    if listenerCloseError != nil:
        return 14
    if elapsed >= 450:
        return 15
    return 0
}
"#;
    fs::write(&source_path, native_source)
        .expect("concurrent HTTP native fixture should be writable");
    let binary = root.join("serve-concurrent");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("concurrent HTTP Flux binary should build");
    assert!(
        built.status.success(),
        "concurrent HTTP fixture build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let started = Instant::now();
    let run = Command::new(&binary)
        .output()
        .expect("concurrent HTTP Flux binary should run");
    assert!(
        run.status.success(),
        "concurrent HTTP server failed with {:?}: stdout={} stderr={}",
        run.status.code(),
        String::from_utf8_lossy(&run.stdout),
        String::from_utf8_lossy(&run.stderr)
    );
    assert!(
        started.elapsed() < Duration::from_secs(2),
        "structured concurrent server should cancel and drain promptly"
    );
    assert_eq!(String::from_utf8_lossy(&run.stdout), "served\nserved\n");
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn http_serve_concurrent_drains_owned_requests_before_returning_errors() {
    let root = std::env::temp_dir().join(format!(
        "flux-http-serve-concurrent-error-drain-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("concurrent HTTP error-drain fixture should be writable");
    let source_path = root.join("serve-error-drain.flux");
    let source = r#"
fn request(socket: i64, _method: str, target: str, _version: str) -> void {
    if target == "/slow":
        time.sleep(1200)
        let _responseError: error = http.respond(socket, 200, "text/plain", "served")
}
fn header(_socket: i64, _name: str, _value: str) -> void {
}
fn body(_socket: i64, _body: str) -> void {
}
fn serve(listener: i64) -> void {
    let serveError: error = http.serveConcurrentLimit(listener, 4096, 1024, 2, request, header, body)
    if serveError == nil:
        print("missing-error")
    let joinError: error = worker.joinAll()
    if joinError != nil:
        print("join-error")
    print("drained")
}
fn main() -> i64 {
    let (listener, listenError) = net.listen("127.0.0.1", 0, 8)
    if listenError != nil:
        return 1
    let (port, portError) = net.port(listener)
    if portError != nil:
        return 2
    let (server, startError) = worker.startWith(serve, listener)
    if startError != nil:
        return 3
    time.sleep(50)
    let (slow, slowError) = net.connect("127.0.0.1", port)
    if slowError != nil:
        return 4
    let slowRequestError: error = http.request(slow, "GET", "/slow", "example.test", "text/plain", "")
    if slowRequestError != nil:
        return 5
    time.sleep(100)
    let (broken, brokenError) = net.connect("127.0.0.1", port)
    if brokenError != nil:
        return 6
    let brokenWriteError: error = net.write(broken, "BROKEN\r\n\r\n")
    if brokenWriteError != nil:
        return 7
    let joinError: error = worker.join(server)
    if joinError != nil:
        return 8
    let slowCloseError: error = net.close(slow)
    if slowCloseError != nil:
        return 9
    let brokenCloseError: error = net.close(broken)
    if brokenCloseError != nil:
        return 10
    let listenerCloseError: error = net.close(listener)
    if listenerCloseError != nil:
        return 11
    return 0
}
"#;
    fs::write(&source_path, source).expect("concurrent HTTP error-drain source should write");
    let binary = root.join("serve-error-drain");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("concurrent HTTP error-drain binary should build");
    assert!(
        built.status.success(),
        "concurrent HTTP error-drain build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let started = Instant::now();
    let run = Command::new(&binary)
        .output()
        .expect("concurrent HTTP error-drain binary should run");
    assert!(
        run.status.success(),
        "concurrent HTTP error-drain fixture failed with {:?}: stdout={} stderr={}",
        run.status.code(),
        String::from_utf8_lossy(&run.stdout),
        String::from_utf8_lossy(&run.stderr)
    );
    assert!(
        started.elapsed() < Duration::from_millis(800),
        "serveConcurrentLimit should cancel and join its owned requests before returning"
    );
    assert_eq!(String::from_utf8_lossy(&run.stdout), "drained\n");
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn http_serve_concurrent_limit_bounds_inflight_workers() {
    let source = r#"
fn request(_socket: i64, _method: str, _target: str, _version: str) -> void {
}
fn header(_socket: i64, _name: str, _value: str) -> void {
}
fn body(_socket: i64, _body: str) -> void {
}
fn main() -> i64 {
    let _serveError: error = http.serveConcurrentLimit(1, 4096, 1024, 8, request, header, body)
    return 0
}
"#;
    check_source(source).expect("bounded concurrent HTTP server should typecheck");
    let generated = compile_to_c(source).expect("bounded concurrent HTTP server should lower");
    assert!(generated.contains(
        "flux__net_http_serve_concurrent_limit(INT64_C(1), INT64_C(4096), INT64_C(1024), INT64_C(8)"
    ));
    assert!(generated.contains("if (pending == (size_t)max_concurrent)"));
    assert!(generated.contains("while (pending < (size_t)max_concurrent)"));
    assert!(generated.contains("struct flux__http_concurrent_payload payloads[64]"));
    assert!(generated.contains("struct flux__worker_state worker_states[64]"));
    assert!(generated.contains("payload_slots[pending] = payload_index"));
    assert!(generated.contains("&worker_states[payload_index]"));
    assert!(generated.contains("flux__net_poll_cancellable(&queued, 1, 0)"));
    assert!(generated.contains("http.serveConcurrentLimit maxConcurrent must be between 1 and 64"));

    let invalid = check_source(&source.replace(
        "http.serveConcurrentLimit(1, 4096, 1024, 8, request, header, body)",
        "http.serveConcurrentLimit(1, 4096, 1024, 0, request, header, body)",
    ))
    .expect_err("bounded concurrent HTTP server must reject a zero constant limit");
    assert!(
        invalid
            .message
            .contains("http.serveConcurrentLimit maxConcurrent must be between 1 and 64")
    );
}

