#[test]
fn worker_cancellation_interrupts_blocking_http_server_and_client_io() {
    let serve_source = r#"
fn request(_socket: i64, _method: str, _target: str, _version: str) -> void {
}
fn header(_socket: i64, _name: str, _value: str) -> void {
}
fn body(_socket: i64, _body: str) -> void {
}
fn serve(listener: i64) -> void {
    let serveError: error = http.serveOnce(listener, 4096, 1024, request, header, body)
    if serveError == nil:
        print(-1)
    else:
        print(1)
}
fn main() -> i64 {
    let (listener, listenError) = net.listen("127.0.0.1", 0, 8)
    if listenError != nil:
        return 1
    let (handle, startError) = worker.startWith(serve, listener)
    if startError != nil:
        return 2
    time.sleep(100)
    let cancelError: error = worker.cancel(handle)
    if cancelError != nil:
        return 3
    let joinError: error = worker.join(handle)
    if joinError != nil:
        return 4
    let closeError: error = net.close(listener)
    if closeError != nil:
        return 5
    return 0
}
"#;
    check_source(serve_source).expect("cancelled HTTP server should typecheck");
    let serve_generated =
        compile_to_c(serve_source).expect("cancelled HTTP server should lower natively");
    assert!(serve_generated.contains("http.serveOnce cancelled by worker scope"));
    assert!(serve_generated.contains("HTTP request receive cancelled by worker scope"));

    let root = std::env::temp_dir().join(format!("flux-worker-http-cancel-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("HTTP cancellation fixture should be writable");
    let serve_path = root.join("serve.flux");
    fs::write(&serve_path, serve_source).expect("HTTP cancellation server source should write");
    let serve_binary = root.join("serve-cancel");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&serve_path)
        .arg("-o")
        .arg(&serve_binary)
        .output()
        .expect("HTTP cancellation server binary should build");
    assert!(
        built.status.success(),
        "HTTP cancellation server build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let started = Instant::now();
    let run = Command::new(&serve_binary)
        .output()
        .expect("HTTP cancellation server binary should run");
    assert!(
        run.status.success(),
        "HTTP cancellation server failed with {:?}: {}",
        run.status.code(),
        String::from_utf8_lossy(&run.stderr)
    );
    assert!(
        started.elapsed() < Duration::from_secs(1),
        "cancelled serveOnce should not remain blocked in accept"
    );
    assert_eq!(String::from_utf8_lossy(&run.stdout), "1\n");

    let listener = TcpListener::bind("127.0.0.1:0").expect("HTTP cancellation port should bind");
    let port = listener.local_addr().unwrap().port();
    let (accepted_tx, accepted_rx) = std::sync::mpsc::channel();
    let (release_tx, release_rx) = std::sync::mpsc::channel();
    let server = thread::spawn(move || {
        let (_stream, _) = listener
            .accept()
            .expect("HTTP cancellation peer should accept");
        accepted_tx
            .send(())
            .expect("HTTP cancellation peer should signal accept");
        let _ = release_rx.recv();
    });
    let receive_source = format!(
        r#"fn response(_socket: i64, _version: str, _status: i64, _reason: str) -> void {{
}}
fn header(_socket: i64, _name: str, _value: str) -> void {{
}}
fn body(_socket: i64, _body: str) -> void {{
}}
fn receive(socket: i64) -> void {{
    let (_received, receiveError) = http.readResponseBody(socket, 4096, 1024, response, header, body)
    if receiveError == nil:
        print(-2)
    else:
        print(2)
}}
fn main() -> i64 {{
    let (socket, connectError) = net.connect("127.0.0.1", {port})
    if connectError != nil:
        return 1
    let (handle, startError) = worker.startWith(receive, socket)
    if startError != nil:
        return 2
    time.sleep(100)
    let cancelError: error = worker.cancel(handle)
    if cancelError != nil:
        return 3
    let joinError: error = worker.join(handle)
    if joinError != nil:
        return 4
    let closeError: error = net.close(socket)
    if closeError != nil:
        return 5
    return 0
}}
"#
    );
    check_source(&receive_source).expect("cancelled HTTP response receive should typecheck");
    let receive_generated = compile_to_c(&receive_source)
        .expect("cancelled HTTP response receive should lower natively");
    assert!(receive_generated.contains("HTTP response receive cancelled by worker scope"));
    let receive_path = root.join("receive.flux");
    fs::write(&receive_path, receive_source).expect("HTTP cancellation client source should write");
    let receive_binary = root.join("receive-cancel");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&receive_path)
        .arg("-o")
        .arg(&receive_binary)
        .output()
        .expect("HTTP cancellation client binary should build");
    assert!(
        built.status.success(),
        "HTTP cancellation client build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let child = Command::new(&receive_binary)
        .stdout(Stdio::piped())
        .spawn()
        .expect("HTTP cancellation client should start");
    accepted_rx
        .recv_timeout(Duration::from_secs(1))
        .expect("HTTP cancellation peer should be accepted");
    let started = Instant::now();
    let output = child
        .wait_with_output()
        .expect("HTTP cancellation client should finish");
    assert!(
        output.status.success(),
        "HTTP cancellation client failed with {:?}: {}",
        output.status.code(),
        String::from_utf8_lossy(&output.stderr)
    );
    assert!(
        started.elapsed() < Duration::from_secs(1),
        "cancelled HTTP response receive should not remain blocked"
    );
    assert_eq!(String::from_utf8_lossy(&output.stdout), "2\n");
    let _ = release_tx.send(());
    server.join().expect("HTTP cancellation peer should finish");
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn canonical_short_platform_api_names_typecheck_and_lower() {
    let headless = r#"
fn main() -> i64 {
    let (socket, connectError) = net.connect("127.0.0.1", 80)
    let (listener, listenError) = net.listen("127.0.0.1", 0, 8)
    let (accepted, acceptError) = net.accept(listener)
    time.sleep(0)
    print(http.request(socket, "GET", "/", "example.test", "text/plain", ""))
    print(http.respond(socket, 200, "text/plain", "ok"))
    print(socket)
    print(connectError)
    print(accepted)
    print(acceptError)
    print(listenError)
    return 0
}
"#;
    check_source(headless).expect("canonical short headless API names should typecheck");
    let generated =
        compile_to_c(headless).expect("canonical short headless API names should lower");
    for helper in [
        "flux__net_tcp_connect(",
        "flux__net_tcp_listen(",
        "flux__net_tcp_accept(",
        "flux__time_sleep_millis(",
        "flux__net_http_send_text_request_v2(",
        "flux__net_http_send_text_response(",
    ] {
        assert!(
            generated.contains(helper),
            "missing lowering helper {helper}"
        );
    }

    let application = r#"
fn text(_value: str) -> void {
}
fn selected(_path: str) -> void {
}
fn started() -> void {
    clipboard.write("hello")
    clipboard.read(text)
    fileDialog.open(selected)
    fileDialog.save(selected)
}
view Screen {
    grid columns: 1fr
    grid rows: auto
    Text title at 1,1
        text: "short API names"
}
app Screen(onStart: started)
"#;
    check_source(application).expect("canonical short application API names should typecheck");
    let generated =
        compile_to_c(application).expect("canonical short application API names should lower");
    for helper in [
        "flux__clipboard_set_text(",
        "flux__clipboard_read_text(",
        "flux__file_dialog_open_file(",
        "flux__file_dialog_save_file(",
    ] {
        assert!(
            generated.contains(helper),
            "missing lowering helper {helper}"
        );
    }
}

#[test]
fn http_chunked_text_request_body_is_decoded_bounded_and_does_not_overread() {
    let listener =
        TcpListener::bind("127.0.0.1:0").expect("HTTP chunked request listener should bind");
    let port = listener.local_addr().unwrap().port();
    let server = thread::spawn(move || {
        let (mut stream, _) = listener
            .accept()
            .expect("HTTP chunked request receiver should connect");
        stream
            .write_all(
                b"POST /upload HTTP/1.1\r\nHost: example.test\r\nTransfer-Encoding: chunked\r\n\r\n5\r\nhello\r\n6;demo=yes\r\n world\r\n0\r\nX-Checksum: request-ok\r\nX-Mode:\t trailer \t\r\n\r\nTAIL",
            )
            .expect("chunked HTTP request should be writable");
    });

    let root =
        std::env::temp_dir().join(format!("flux-http-chunked-server-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("HTTP chunked request fixture should be writable");
    let source_path = root.join("server.flux");
    fs::write(
        &source_path,
        format!(
            "fn request(_socket: i64, method: str, target: str, version: str) -> void {{\n    print(method)\n    print(target)\n    print(version)\n}}\nfn header(_socket: i64, name: str, value: str) -> void {{\n    print(name)\n    print(value)\n}}\nfn body(_socket: i64, value: str) -> void {{\n    print(value)\n}}\nfn tail(_socket: i64, value: str) -> void {{\n    print(value)\n}}\nfn main() -> i64 {{\n    let (socket, connectError) = net.tcpConnect(\"127.0.0.1\", {port})\n    print(connectError)\n    let (received, receiveError) = http.receiveRequestWithTextBody(socket, 4096, 1024, request, header, body)\n    print(received > 0)\n    print(receiveError)\n    let (tailBytes, tailError) = net.receiveText(socket, 4, tail)\n    print(tailBytes)\n    print(tailError)\n    print(net.close(socket))\n    return 0\n}}\n"
        ),
    )
    .expect("HTTP chunked request source should be writable");
    let binary = root.join("server");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("HTTP chunked request Flux binary should build");
    assert!(
        built.status.success(),
        "HTTP chunked request fixture build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("HTTP chunked request Flux binary should run");
    server
        .join()
        .expect("HTTP chunked request writer should finish");
    assert!(run.status.success());
    assert_eq!(
        String::from_utf8_lossy(&run.stdout),
        "nil\nPOST\n/upload\nHTTP/1.1\nHost\nexample.test\nTransfer-Encoding\nchunked\nhello world\ntrue\nnil\nTAIL\n4\nnil\nnil\n"
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn http_response_head_with_headers_is_typed_borrowed_tree_shaken_and_runnable() {
    let source = r#"
fn handleResponse(socket: i64, version: str, status: i64, reason: str) -> void {
    print(socket >= 0)
    print(version)
    print(status)
    print(reason)
}
fn handleHeader(socket: i64, name: str, value: str) -> void {
    print(socket >= 0)
    print(name)
    print(value)
}
fn main() -> i64 {
    let (received, receiveError) = http.receiveResponseHeadWithHeaders(1, 4096, handleResponse, handleHeader)
    print(received)
    print(receiveError)
    return 0
}
"#;
    check_source(source).expect("HTTP response-head receive should typecheck");
    let generated = compile_to_c(source).expect("HTTP response head should lower on Linux");
    assert!(generated.contains("flux__net_http_receive_response_head_with_headers("));
    assert!(generated.contains("invalid HTTP status code"));
    assert!(generated.contains("invalid HTTP header name"));

    let invalid_limit = check_source(
        "fn response(socket: i64, version: str, status: i64, reason: str) -> void {\n    print(socket)\n    print(version)\n    print(status)\n    print(reason)\n}\nfn header(socket: i64, name: str, value: str) -> void {\n    print(socket)\n    print(name)\n    print(value)\n}\nfn main() -> i64 {\n    let (_, failure) = http.receiveResponseHeadWithHeaders(1, 0, response, header)\n    print(failure)\n    return 0\n}\n",
    )
    .expect_err("constant HTTP response-head limit outside the valid range must fail");
    assert!(
        invalid_limit
            .message
            .contains("http.receiveResponseHeadWithHeaders maxBytes must be between 1 and 65536")
    );

    let unused = source.replace(
        "fn main() -> i64 {\n    let (received, receiveError) = http.receiveResponseHeadWithHeaders(1, 4096, handleResponse, handleHeader)\n    print(received)\n    print(receiveError)\n    return 0\n}",
        "fn hidden() -> void {\n    let (received, receiveError) = http.receiveResponseHeadWithHeaders(1, 4096, handleResponse, handleHeader)\n    print(received)\n    print(receiveError)\n}\nfn main() -> i64 {\n    return 0\n}",
    );
    let unused_generated =
        compile_to_c(&unused).expect("dead HTTP response-head helper should tree-shake");
    assert!(!unused_generated.contains("flux__net_http_receive_response_head_with_headers("));

    let listener =
        TcpListener::bind("127.0.0.1:0").expect("HTTP response-head listener should bind");
    let port = listener.local_addr().unwrap().port();
    let root = std::env::temp_dir().join(format!("flux-http-response-head-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("HTTP response-head fixture should be writable");
    let source_path = root.join("response-head.flux");
    fs::write(
        &source_path,
        format!(
            "fn handleResponse(socket: i64, version: str, status: i64, reason: str) -> void {{\n    print(socket >= 0)\n    print(version)\n    print(status)\n    print(reason)\n}}\nfn handleHeader(socket: i64, name: str, value: str) -> void {{\n    print(socket >= 0)\n    print(name)\n    print(value)\n}}\nfn handleExtra(socket: i64, body: str) -> void {{\n    print(socket >= 0)\n    print(body)\n}}\nfn main() -> i64 {{\n    let (socket, connectError) = net.tcpConnect(\"127.0.0.1\", {port})\n    print(connectError)\n    let (received, receiveError) = http.receiveResponseHeadWithHeaders(socket, 4096, handleResponse, handleHeader)\n    print(received > 0)\n    print(receiveError)\n    let (extraReceived, extraError) = net.receiveText(socket, 4, handleExtra)\n    print(extraReceived == 4)\n    print(extraError)\n    print(net.close(socket))\n    return 0\n}}\n"
        ),
    )
    .expect("HTTP response-head Flux source should be writable");
    let binary = root.join("response-head");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("HTTP response-head Flux binary should build");
    assert!(
        built.status.success(),
        "HTTP response-head fixture build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let child = Command::new(&binary)
        .stdout(Stdio::piped())
        .spawn()
        .expect("HTTP response-head Flux binary should start");
    let (mut stream, _) = listener
        .accept()
        .expect("HTTP response-head connection should accept");
    stream
        .write_all(
            b"HTTP/1.1 204 No Content\r\nContent-Length: 4\r\nX-Trace:\t abc-123 \t\r\n\r\nBODY",
        )
        .expect("HTTP response head should be writable");
    let output = child
        .wait_with_output()
        .expect("HTTP response-head Flux binary should finish");
    assert!(output.status.success());
    assert_eq!(
        String::from_utf8_lossy(&output.stdout),
        "nil\ntrue\nHTTP/1.1\n204\nNo Content\ntrue\nContent-Length\n4\ntrue\nX-Trace\nabc-123\ntrue\nnil\ntrue\nBODY\ntrue\nnil\nnil\n"
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn http_text_request_is_typed_tree_shaken_and_runnable() {
    let source = r#"
fn main() -> i64 {
    print(http.sendTextRequest(1, "POST", "/items", "example.test", "text/plain", "hello"))
    return 0
}
"#;
    check_source(source).expect("HTTP text request should typecheck");
    let generated = compile_to_c(source).expect("HTTP text request should lower on Linux");
    assert!(generated.contains("flux__net_http_send_text_request_v2("));
    assert!(generated.contains("flux__net_http_bounded_length(const char *value"));
    assert!(generated.contains("HTTP request body exceeds 65536 bytes"));
    assert!(generated.contains("HTTP request argument exceeds 65536 bytes"));
    assert!(generated.contains(
        "!flux__net_http_bounded_length(method, &method_length) || !flux__net_http_bounded_length(target, &target_length) || !flux__net_http_bounded_length(host, &host_length) || !flux__net_http_bounded_length(content_type, &content_type_length) || body == NULL"
    ));
    assert!(generated.contains("Host: %s"));
    assert!(generated.contains("Content-Length: %zu"));
    assert!(generated.contains("Connection: %s"));
    assert!(generated.contains("keep_alive ? \"keep-alive\" : \"close\""));
    assert!(generated.contains("#include <sys/socket.h>"));

    let invalid_type = check_source(
        "fn main() -> i64 {\n    print(http.sendTextRequest(1, \"POST\", \"/\", false, \"text/plain\", \"nope\"))\n    return 0\n}\n",
    )
    .expect_err("HTTP host must be text");
    assert!(invalid_type.message.contains("http.sendTextRequest host"));

    let invalid_keep_alive = check_source(
        "fn main() -> i64 {\n    print(http.sendTextRequest(1, \"POST\", \"/\", \"example.test\", \"text/plain\", \"nope\", \"yes\"))\n    return 0\n}\n",
    )
    .expect_err("HTTP keepAlive must be boolean");
    assert!(
        invalid_keep_alive
            .message
            .contains("http.sendTextRequest keepAlive")
    );

    let unused = r#"
fn hidden() -> void {
    print(http.sendTextRequest(1, "GET", "/", "example.test", "text/plain", ""))
}
fn main() -> i64 {
    return 0
}
"#;
    let unused_generated =
        compile_to_c(unused).expect("dead HTTP request helper should tree-shake");
    assert!(!unused_generated.contains("flux__net_http_send_text_request_v2("));
    assert!(!unused_generated.contains("#include <sys/socket.h>"));

    let listener = TcpListener::bind("127.0.0.1:0").expect("HTTP loopback listener should bind");
    let port = listener.local_addr().unwrap().port();
    let root = std::env::temp_dir().join(format!("flux-http-send-request-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("HTTP fixture should be writable");
    let source_path = root.join("request.flux");
    fs::write(
        &source_path,
        format!(
            "fn main() -> i64 {{\n    let (socket, connectError) = net.tcpConnect(\"127.0.0.1\", {port})\n    print(connectError)\n    print(http.sendTextRequest(socket, \"POST\", \"/items?q=1\", \"127.0.0.1:{port}\", \"text/plain; charset=utf-8\", \"hello\", true))\n    print(net.close(socket))\n    return 0\n}}\n"
        ),
    )
    .expect("HTTP Flux source should be writable");
    let binary = root.join("request");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("HTTP Flux binary should build");
    assert!(
        built.status.success(),
        "HTTP fixture build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("HTTP Flux binary should run");
    assert!(run.status.success());
    assert_eq!(String::from_utf8_lossy(&run.stdout), "nil\nnil\nnil\n");

    let (mut stream, _) = listener
        .accept()
        .expect("HTTP loopback connection should accept");
    let mut request = String::new();
    stream
        .read_to_string(&mut request)
        .expect("HTTP request should be readable");
    assert_eq!(
        request,
        format!(
            "POST /items?q=1 HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nContent-Length: 5\r\nContent-Type: text/plain; charset=utf-8\r\nConnection: keep-alive\r\n\r\nhello"
        )
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn http_binary_request_sender_is_typed_strided_tree_shaken_and_runnable() {
    let source = r#"
fn main() -> i64 {
    let body: i64[] = [0, 128, 255]
    print(http.requestBytes(1, "POST", "/items", "example.test", "application/octet-stream", body))
    return 0
}
"#;
    check_source(source).expect("HTTP binary request should typecheck");
    let generated = compile_to_c(source).expect("HTTP binary request should lower on Linux");
    assert!(generated.contains("flux__net_http_send_bytes_request("));
    assert!(generated.contains("flux__net_http_copy_binary_body("));
    assert!(generated.contains("HTTP binary body byte values must be between 0 and 255"));
    assert!(generated.contains("Content-Length: %zu"));
    assert!(generated.contains("Connection: %s"));

    let invalid_type = check_source(
        "fn main() -> i64 {\n    print(http.requestBytes(1, \"POST\", \"/\", \"example.test\", \"application/octet-stream\", \"nope\"))\n    return 0\n}\n",
    )
    .expect_err("HTTP binary request body must be bytes");
    assert!(invalid_type.message.contains("http.requestBytes body"));

    let invalid_byte = check_source(
        "fn main() -> i64 {\n    print(http.requestBytes(1, \"POST\", \"/\", \"example.test\", \"application/octet-stream\", [0, 256]))\n    return 0\n}\n",
    )
    .expect_err("HTTP binary request literal bytes must stay in byte range");
    assert!(
        invalid_byte
            .message
            .contains("http.requestBytes byte values must be between 0 and 255")
    );

    let unused = r#"
fn hidden(body: i64[]) -> void {
    print(http.requestBytes(1, "POST", "/", "example.test", "application/octet-stream", body))
}
fn main() -> i64 {
    return 0
}
"#;
    let unused_generated =
        compile_to_c(unused).expect("dead HTTP binary request helper should tree-shake");
    assert!(!unused_generated.contains("flux__net_http_send_bytes_request("));

    let listener =
        TcpListener::bind("127.0.0.1:0").expect("HTTP binary request listener should bind");
    let port = listener.local_addr().unwrap().port();
    let root = std::env::temp_dir().join(format!(
        "flux-http-send-binary-request-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("HTTP binary request fixture should be writable");
    let source_path = root.join("request.flux");
    fs::write(
        &source_path,
        format!(
            "fn main() -> i64 {{\n    let values: i64[] = [0, 99, 128, 99, 255]\n    let body: i64[] = values[::2]\n    let (socket, connectError) = net.connect(\"127.0.0.1\", {port})\n    print(connectError)\n    print(http.requestBytes(socket, \"POST\", \"/binary\", \"127.0.0.1:{port}\", \"application/octet-stream\", body, true))\n    print(net.close(socket))\n    return 0\n}}\n"
        ),
    )
    .expect("HTTP binary request Flux source should be writable");
    let binary = root.join("request");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("HTTP binary request Flux binary should build");
    assert!(
        built.status.success(),
        "HTTP binary request fixture build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("HTTP binary request Flux binary should run");
    assert!(
        run.status.success(),
        "HTTP binary request run failed: stdout={:?} stderr={:?}",
        String::from_utf8_lossy(&run.stdout),
        String::from_utf8_lossy(&run.stderr)
    );
    assert_eq!(String::from_utf8_lossy(&run.stdout), "nil\nnil\nnil\n");

    let (mut stream, _) = listener
        .accept()
        .expect("HTTP binary request connection should accept");
    let mut request = Vec::new();
    stream
        .read_to_end(&mut request)
        .expect("HTTP binary request should be readable");
    let mut expected = format!(
        "POST /binary HTTP/1.1\r\nHost: 127.0.0.1:{port}\r\nContent-Length: 3\r\nContent-Type: application/octet-stream\r\nConnection: keep-alive\r\n\r\n"
    )
    .into_bytes();
    expected.extend_from_slice(&[0, 128, 255]);
    assert_eq!(request, expected);
    let _ = fs::remove_dir_all(&root);
}

