#[test]
fn socket_resumable_timed_writes_preserve_global_offsets() {
    let listener =
        TcpListener::bind("127.0.0.1:0").expect("resumable timed-write listener should bind");
    let port = listener.local_addr().unwrap().port();
    let source = format!(
        r#"fn runtimeOffset(value: i64) -> i64 {{
    return value
}}
fn main() -> i64 {{
    let (socket, connectError) = net.connect("127.0.0.1", {port})
    print(connectError)
    let (blockedNext, blockedDone, blockedError) = net.writeFromTimeout(socket, "hello", 2, 100)
    print(blockedNext)
    print(blockedDone)
    print(blockedError)
    print(net.nonblocking(socket, true))
    let (textNext, textDone, textError) = net.writeFromTimeout(socket, "hello", 2, 1000)
    print(textNext)
    print(textDone)
    print(textError)
    let (partsNext, partsDone, partsError) = net.writePartsFromTimeout(socket, ["hello", "", " ", "world"], 6, 1000)
    print(partsNext)
    print(partsDone)
    print(partsError)
    let (badNext, badDone, badError) = net.writePartsFromTimeout(socket, ["a", "b"], runtimeOffset(3), 1000)
    print(badNext)
    print(badDone)
    print(badError)
    print(net.close(socket))
    return 0
}}
"#
    );
    check_source(&source).expect("resumable timed writes should typecheck");
    let generated = compile_to_c(&source).expect("resumable timed writes should lower");
    assert!(generated.contains("flux__net_send_text_progress_with_timeout("));
    assert!(generated.contains("flux__net_send_text_parts_progress_with_timeout("));
    assert!(generated.contains("flux__net_poll_cancellable(&descriptor, 1, wait_millis)"));
    assert!(generated.contains("sendTextProgressWithTimeout cancelled by worker scope"));
    assert!(generated.contains("sendTextPartsProgressWithTimeout cancelled by worker scope"));

    let root =
        std::env::temp_dir().join(format!("flux-net-resumable-timeout-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("resumable timed-write fixture should be writable");
    let source_path = root.join("resumable_timeout.flux");
    fs::write(&source_path, &source).expect("resumable timed-write source should be writable");
    let binary = root.join("resumable_timeout");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("resumable timed-write binary should build");
    assert!(
        built.status.success(),
        "resumable timed-write build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );

    let server = thread::spawn(move || {
        let (mut stream, _) = listener
            .accept()
            .expect("Flux resumable timed-write client should connect");
        let mut request = [0u8; 8];
        stream
            .read_exact(&mut request)
            .expect("resumable timed writes should deliver only unsent suffixes");
        assert_eq!(&request, b"lloworld");
    });
    let run = Command::new(&binary)
        .output()
        .expect("resumable timed-write binary should run");
    server
        .join()
        .expect("resumable timed-write server should finish");
    assert!(run.status.success());
    assert_eq!(
        String::from_utf8_lossy(&run.stdout),
        "nil\n2\nfalse\nsendTextProgressWithTimeout requires a nonblocking TCP socket\nnil\n5\ntrue\nnil\n11\ntrue\nnil\n3\nfalse\nsendTextPartsProgressWithTimeout offset exceeds text length\nnil\n"
    );

    let negative_offset = check_source(
        "fn main() -> i64 {\n    let (next, done, failure) = net.writeFromTimeout(1, \"hello\", -1, 10)\n    print(next)\n    print(done)\n    print(failure)\n    return 0\n}\n",
    )
    .expect_err("resumable timed text write should reject negative offsets");
    assert!(
        negative_offset
            .message
            .contains("offset must be non-negative")
    );
    let invalid_timeout = check_source(
        "fn main() -> i64 {\n    let (next, done, failure) = net.writePartsFromTimeout(1, [\"x\"], 0, -2)\n    print(next)\n    print(done)\n    print(failure)\n    return 0\n}\n",
    )
    .expect_err("resumable timed scatter/gather write should reject invalid timeout");
    assert!(invalid_timeout.message.contains("timeoutMillis must be -1"));

    let unused = r#"
fn hidden(socket: i64) -> void {
    let (textNext, textDone, textError) = net.writeFromTimeout(socket, "hidden", 0, 10)
    print(textNext)
    print(textDone)
    print(textError)
    let (partsNext, partsDone, partsError) = net.writePartsFromTimeout(socket, ["hidden", "payload"], 0, 10)
    print(partsNext)
    print(partsDone)
    print(partsError)
}
fn main() -> i64 {
    return 0
}
"#;
    let unused_generated =
        compile_to_c(unused).expect("dead resumable timed writes should tree-shake");
    assert!(!unused_generated.contains("flux__net_send_text_progress_with_timeout("));
    assert!(!unused_generated.contains("flux__net_send_text_parts_progress_with_timeout("));
    assert!(!unused_generated.contains("#include <sys/uio.h>"));
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn udp_scatter_gather_text_send_is_typed_tree_shaken_and_runnable() {
    let peer = UdpSocket::bind("127.0.0.1:0").expect("UDP scatter/gather peer should bind");
    let peer_port = peer.local_addr().unwrap().port();
    let source = format!(
        r#"fn main() -> i64 {{
    let (socket, bindError) = net.udpBind("127.0.0.1", 0)
    print(bindError)
    print(net.sendTextToParts(socket, "127.0.0.1", {peer_port}, ["hello", "", " ", "world"]))
    print(net.close(socket))
    return 0
}}
"#
    );
    check_source(&source).expect("UDP scatter/gather text send should typecheck");
    let generated = compile_to_c(&source).expect("UDP scatter/gather text send should lower");
    assert!(generated.contains("#include <sys/uio.h>"));
    assert!(generated.contains("flux__net_send_text_to_parts("));
    assert!(generated.contains("UDP peer host exceeds 65536 bytes"));
    assert!(generated.contains("message.msg_name = address->ai_addr"));
    assert!(generated.contains("sendmsg("));

    let root = std::env::temp_dir().join(format!("flux-udp-scatter-gather-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("UDP scatter/gather fixture should be writable");
    let source_path = root.join("udp_scatter.flux");
    fs::write(&source_path, &source).expect("UDP scatter/gather source should be writable");
    let binary = root.join("udp_scatter");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("UDP scatter/gather binary should build");
    assert!(
        built.status.success(),
        "UDP scatter/gather build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );

    let server = thread::spawn(move || {
        let mut request = [0u8; 32];
        let (length, _) = peer
            .recv_from(&mut request)
            .expect("Flux UDP scatter/gather datagram should arrive");
        assert_eq!(length, 11);
        assert_eq!(&request[..length], b"hello world");
    });
    let run = Command::new(&binary)
        .output()
        .expect("UDP scatter/gather binary should run");
    server
        .join()
        .expect("UDP scatter/gather peer should finish");
    assert!(run.status.success());
    assert_eq!(String::from_utf8_lossy(&run.stdout), "nil\nnil\nnil\n");

    let port_error = check_source(
        "fn main() -> i64 {\n    print(net.sendTextToParts(1, \"127.0.0.1\", 0, [\"nope\"]))\n    return 0\n}\n",
    )
    .expect_err("constant UDP scatter/gather peer port zero must fail statically");
    assert!(
        port_error
            .message
            .contains("net.sendTextToParts port must be between 1 and 65535")
    );
    let wrong_parts = check_source(
        "fn main() -> i64 {\n    print(net.sendTextToParts(1, \"127.0.0.1\", 9999, [1, 2]))\n    return 0\n}\n",
    )
    .expect_err("UDP scatter/gather parts must be strings");
    assert!(wrong_parts.message.contains("net.sendTextToParts parts"));

    let unused = r#"
fn hidden(socket: i64) -> void {
    print(net.sendTextToParts(socket, "127.0.0.1", 9999, ["hidden", "payload"]))
}

fn main() -> i64 {
    return 0
}
"#;
    let unused_generated =
        compile_to_c(unused).expect("dead UDP scatter/gather send should tree-shake");
    assert!(!unused_generated.contains("flux__net_send_text_to_parts("));
    assert!(!unused_generated.contains("#include <sys/uio.h>"));
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn udp_peer_binary_send_is_typed_native_and_runnable() {
    let peer = UdpSocket::bind("127.0.0.1:0").expect("UDP binary peer should bind");
    let peer_port = peer.local_addr().unwrap().port();
    let source = format!(
        r#"fn main() -> i64 {{
    let (socket, bindError) = net.udpBind("127.0.0.1", 0)
    print(bindError)
    let (sent, sendError) = net.writeBytesTo(socket, "127.0.0.1", {peer_port}, [0, 1, 10, 127, 255])
    print(sent)
    print(sendError)
    print(net.close(socket))
    return 0
}}
"#
    );
    check_source(&source).expect("peer-addressed UDP binary send should typecheck");
    let generated = compile_to_c(&source).expect("peer-addressed UDP binary send should lower");
    assert!(generated.contains("flux__net_send_bytes_to("));
    assert!(generated.contains("sendto("));
    assert!(generated.contains("UDP binary datagram exceeds 65507 bytes"));
    assert!(generated.contains("sendBytesTo byte list has missing storage"));
    assert!(generated.contains("sendBytesTo byte list has an invalid element stride"));
    assert!(generated.contains("sendBytesTo peer host exceeds 65536 bytes"));
    assert!(generated.contains("PTRDIFF_MAX / stride_magnitude"));

    let root = std::env::temp_dir().join(format!("flux-udp-binary-peer-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("UDP binary fixture should be writable");
    let source_path = root.join("peer_binary.flux");
    fs::write(&source_path, &source).expect("UDP binary source should be writable");
    let binary = root.join("peer_binary");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .args(["build"])
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("UDP binary executable should build");
    assert!(
        built.status.success(),
        "UDP binary build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );

    let server = thread::spawn(move || {
        let mut request = [0u8; 8];
        let (length, _) = peer
            .recv_from(&mut request)
            .expect("binary UDP datagram should arrive");
        assert_eq!(&request[..length], &[0, 1, 10, 127, 255]);
    });
    let run = Command::new(&binary)
        .output()
        .expect("UDP binary executable should run");
    server.join().expect("UDP binary peer should finish");
    assert!(run.status.success());
    assert_eq!(String::from_utf8_lossy(&run.stdout), "nil\n5\nnil\nnil\n");

    let bad_byte = check_source(
        "fn main() -> i64 {\n    let (sent, failure) = net.writeBytesTo(1, \"127.0.0.1\", 1, [256])\n    print(sent)\n    print(failure)\n    return 0\n}\n",
    )
    .expect_err("peer-addressed UDP binary send should reject out-of-range literals");
    assert!(
        bad_byte
            .message
            .contains("net.writeBytesTo byte values must be between 0 and 255")
    );

    let unused = "fn hidden(socket: i64) -> void {\n    let (sent, failure) = net.writeBytesTo(socket, \"127.0.0.1\", 1, [1, 2])\n    print(sent)\n    print(failure)\n}\nfn main() -> i64 {\n    return 0\n}\n";
    let unused_generated = compile_to_c(unused).expect("dead UDP binary send should tree-shake");
    assert!(!unused_generated.contains("flux__net_send_bytes_to("));
    let _ = fs::remove_dir_all(&root);
}

