#[test]
fn larger_duration_unit_constructors_reject_constant_overflow() {
    for (name, value) in [("days", "106751991168"), ("weeks", "15250284453")] {
        let source = format!("fn main() -> i64 {{\n    return time.{name}({value})\n}}\n");
        let error = check_source(&source)
            .expect_err("large duration conversion overflow must be diagnosed statically");
        assert!(
            error
                .message
                .contains("duration overflows i64 milliseconds")
        );
    }
}

#[test]
fn structured_timers_run_repeat_cancel_and_tree_shake() {
    let source = r#"
fn once() -> void {
    print(7)
}
fn tick() -> void {
    print(8)
}
fn main() -> i64 {
    let (onceHandle, onceError) = time.after(10, once)
    if onceError != nil:
        return 1
    let onceJoin: error = worker.join(onceHandle)
    if onceJoin != nil:
        return 2
    let (repeatHandle, repeatError) = time.every(10, tick)
    if repeatError != nil:
        return 3
    time.sleep(35)
    let cancelError: error = worker.cancel(repeatHandle)
    if cancelError != nil:
        return 4
    let repeatJoin: error = worker.join(repeatHandle)
    if repeatJoin != nil:
        return 5
    return 0
}
"#;
    check_source(source).expect("structured timer fixture should typecheck");
    let generated = compile_to_c(source).expect("structured timers should lower natively");
    assert!(generated.contains("static struct flux__worker_i64_error flux__time_start_timer"));
    assert!(generated.contains("static void flux__time_timer_entry"));
    assert!(generated.contains("flux__worker_start_with(flux__time_timer_entry"));
    assert!(generated.contains("#include <pthread.h>"));
    assert!(generated.contains("#include <time.h>"));

    let root = std::env::temp_dir().join(format!("flux-structured-timer-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("structured timer fixture should be writable");
    let source_path = root.join("main.flux");
    fs::write(&source_path, source).expect("structured timer source should be writable");
    let binary = root.join("structured-timer");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("structured timer binary should build");
    assert!(
        built.status.success(),
        "structured timer build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("structured timer binary should run");
    assert!(
        run.status.success(),
        "{}",
        String::from_utf8_lossy(&run.stderr)
    );
    let output = String::from_utf8_lossy(&run.stdout);
    let lines = output.lines().collect::<Vec<_>>();
    assert_eq!(lines.first().copied(), Some("7"));
    assert!(
        lines.len() >= 3,
        "repeating timer should fire at least twice: {output}"
    );
    assert!(lines[1..].iter().all(|line| *line == "8"));

    let invalid_after = r#"
fn callback() -> void {
}
fn main() -> i64 {
    let (_handle, _failure) = time.after(-1, callback)
    return 0
}
"#;
    let error = check_source(invalid_after).expect_err("negative one-shot delay must fail");
    assert!(
        error
            .message
            .contains("time.after durationMs must be non-negative")
    );

    let invalid_every = r#"
fn callback() -> void {
}
fn main() -> i64 {
    let (_handle, _failure) = time.every(0, callback)
    return 0
}
"#;
    let error = check_source(invalid_every).expect_err("zero repeating interval must fail");
    assert!(
        error
            .message
            .contains("time.every durationMs must be positive")
    );

    let invalid_callback = r#"
fn callback(_value: i64) -> void {
}
fn main() -> i64 {
    let (_handle, _failure) = time.after(1, callback)
    return 0
}
"#;
    let error = check_source(invalid_callback).expect_err("timer callback shape must be exact");
    assert!(error.message.contains("time.after callback"));

    let dead = r#"
fn callback() -> void {
}
fn hidden() -> void {
    let (_handle, _failure) = time.every(10, callback)
}
fn main() -> i64 {
    return 0
}
"#;
    let dead_generated = compile_to_c(dead).expect("dead timer calls should lower safely");
    assert!(!dead_generated.contains("flux__time_start_timer("));
    assert!(!dead_generated.contains("#include <pthread.h>"));

    let _ = fs::remove_dir_all(&root);
}

#[test]
fn sqlite_interface_is_typed_borrowed_tree_shaken_and_runnable() {
    let root = std::env::temp_dir().join(format!("flux-sqlite-api-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("SQLite API fixture should be writable");
    let database = root.join("state.db");
    let database_path = database
        .to_string_lossy()
        .replace('\\', "\\\\")
        .replace('"', "\\\"");
    let source = format!(
        r#"
fn cell(row: i64, column: i64, name: str, value: str, isNull: bool) -> void {{
    print(row)
    print(column)
    print(name)
    print(value)
    print(isNull)
}}

fn main() -> i64 {{
    let (database, openError) = sqlite.open("{database_path}")
    print(openError)
    print(sqlite.execute(database, "CREATE TABLE items (id INTEGER PRIMARY KEY, name TEXT)"))
    print(sqlite.execute(database, "INSERT INTO items (name) VALUES ('Ada'), (NULL)"))
    let (rows, queryError) = sqlite.query(database, "SELECT id, name FROM items ORDER BY id", cell)
    print(rows)
    print(queryError)
    print(sqlite.close(database))
    print(sqlite.close(database))
    return 0
}}
"#
    );

    check_source(&source).expect("SQLite capabilities should typecheck");
    let generated = compile_to_c(&source).expect("SQLite capabilities should lower natively");
    assert!(generated.contains("#include <sqlite3.h>"));
    assert!(generated.contains("flux__sqlite_open("));
    assert!(generated.contains("flux__sqlite_execute("));
    assert!(generated.contains("flux__sqlite_query("));
    assert!(generated.contains("flux__sqlite_close("));
    assert!(generated.contains("flux__sqlite_slot_for"));
    assert!(generated.contains("flux__sqlite_register_cleanup"));
    assert!(generated.contains("atexit(flux__sqlite_cleanup)"));

    let unused = r#"
fn cell(_row: i64, _column: i64, _name: str, _value: str, _isNull: bool) -> void {
}
fn hidden() -> void {
    let (database, _openError) = sqlite.open("hidden.db")
    print(sqlite.execute(database, "SELECT 1"))
    let (_rows, _queryError) = sqlite.query(database, "SELECT 1", cell)
    print(sqlite.close(database))
}
fn main() -> i64 {
    return 0
}
"#;
    let unused_generated = compile_to_c(unused).expect("unreachable SQLite calls should compile");
    assert!(!unused_generated.contains("#include <sqlite3.h>"));
    assert!(!unused_generated.contains("flux__sqlite_open("));

    let callback_error = check_source(
        "fn cell(_value: str) -> void {\n}\nfn main() -> i64 {\n    let (database, _failure) = sqlite.open(\"state.db\")\n    let (_rows, queryFailure) = sqlite.query(database, \"SELECT 1\", cell)\n    print(queryFailure)\n    return 0\n}\n",
    )
    .expect_err("SQLite query callback shape should be checked");
    assert!(callback_error.message.contains("sqlite.query callback"));

    let source_path = root.join("main.flux");
    fs::write(&source_path, &source).expect("SQLite API source should be writable");
    let binary = root.join("sqlite-api");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("SQLite API binary should build");
    assert!(
        built.status.success(),
        "SQLite API build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("SQLite API binary should run");
    assert!(run.status.success());
    let lines = String::from_utf8_lossy(&run.stdout)
        .lines()
        .map(str::to_string)
        .collect::<Vec<_>>();
    assert_eq!(
        lines,
        [
            "nil",
            "nil",
            "nil",
            "0",
            "0",
            "id",
            "1",
            "false",
            "0",
            "1",
            "name",
            "Ada",
            "false",
            "1",
            "0",
            "id",
            "2",
            "false",
            "1",
            "1",
            "name",
            "",
            "true",
            "2",
            "nil",
            "nil",
            "invalid or closed SQLite database handle"
        ]
    );
    assert!(database.is_file());
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn sqlite_open_handles_are_closed_at_process_exit_without_explicit_close() {
    let root = std::env::temp_dir().join(format!("flux-sqlite-cleanup-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("SQLite cleanup fixture should be writable");
    let database = root.join("state.db");
    let source_path = root.join("main.flux");
    let database_path = database
        .to_string_lossy()
        .replace('\\', "\\\\")
        .replace('"', "\\\"");
    let source = format!(
        "fn main() -> i64 {{\n    let (database, failure) = sqlite.open(\"{database_path}\")\n    print(failure)\n    print(sqlite.execute(database, \"CREATE TABLE item (value INTEGER)\"))\n    return 0\n}}\n"
    );
    fs::write(&source_path, source).expect("SQLite cleanup source should be writable");
    let binary = root.join("sqlite-cleanup");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("SQLite cleanup binary should build");
    assert!(
        built.status.success(),
        "SQLite cleanup build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("SQLite cleanup binary should run");
    assert!(run.status.success());
    assert_eq!(String::from_utf8_lossy(&run.stdout).trim(), "nil\nnil");
    assert!(database.is_file());
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn filesystem_capabilities_are_typed_native_and_tree_shaken() {
    let root = std::env::temp_dir().join(format!("flux-fs-api-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("filesystem API fixture should be writable");
    let created = root.join("created");
    let content = root.join("content.txt");
    let delete = root.join("delete.txt");
    let copy_source = root.join("copy-source.txt");
    let copy_destination = root.join("copy-destination.txt");
    let renamed = root.join("renamed.txt");
    let missing = root.join("missing.txt");
    let deep = root.join("deep/a/b");
    let recursive_root = root.join("recursive");
    let recursive_nested = recursive_root.join("nested");
    fs::create_dir_all(&recursive_nested).expect("recursive fixture should be writable");
    fs::write(recursive_nested.join("file.txt"), "nested")
        .expect("recursive fixture file should be writable");
    fs::write(&delete, "delete me").expect("delete fixture should be writable");
    fs::write(&copy_source, "copy me").expect("copy fixture should be writable");
    let path = |value: &std::path::Path| {
        value
            .to_string_lossy()
            .replace('\\', "\\\\")
            .replace('"', "\\\"")
    };
    let source = format!(
        r#"
fn main() -> i64 {{
    print(fs.exists("{}"))
    print(fs.isDirectory("{}"))
    print(fs.exists("{}"))
    print(fs.isFile("{}"))
    print(fs.createDirectories("{}"))
    print(fs.isDirectory("{}"))
    print(fs.createDirectory("{}"))
    print(fs.isDirectory("{}"))
    print(fs.writeText("{}", "one"))
    print(fs.appendText("{}", "two"))
    print(fs.isFile("{}"))
    print(fs.copyFile("{}", "{}"))
    print(fs.isFile("{}"))
    print(fs.rename("{}", "{}"))
    print(fs.exists("{}"))
    print(fs.isFile("{}"))
    print(fs.removeFile("{}"))
    print(fs.exists("{}"))
    print(fs.removeDirectory("{}"))
    print(fs.exists("{}"))
    print(fs.removeDirectories("{}"))
    print(fs.exists("{}"))
    return 0
}}
"#,
        path(&root),
        path(&root),
        path(&missing),
        path(&delete),
        path(&deep),
        path(&deep),
        path(&created),
        path(&created),
        path(&content),
        path(&content),
        path(&content),
        path(&copy_source),
        path(&copy_destination),
        path(&copy_destination),
        path(&copy_destination),
        path(&renamed),
        path(&copy_destination),
        path(&renamed),
        path(&delete),
        path(&delete),
        path(&created),
        path(&created),
        path(&recursive_root),
        path(&recursive_root),
    );

    check_source(&source).expect("filesystem capabilities should typecheck");
    let generated = compile_to_c(&source).expect("filesystem capabilities should lower natively");
    assert!(generated.contains("#include <sys/stat.h>"));
    assert!(generated.contains("#include <dirent.h>"));
    assert!(generated.contains("static inline bool flux__fs_exists(const char *path)"));
    assert!(
        generated.contains(
            "static inline bool flux__fs_bounded_length(const char *value, size_t *length)"
        )
    );
    assert!(generated.contains("flux__fs_bounded_length(path, &length)"));
    assert!(generated.contains("static inline bool flux__fs_is_file(const char *path)"));
    assert!(generated.contains("static inline bool flux__fs_is_directory(const char *path)"));
    assert!(
        generated.contains("static inline const char *flux__fs_create_directory(const char *path)")
    );
    assert!(
        generated
            .contains("static inline const char *flux__fs_create_directories(const char *path)")
    );
    assert!(generated.contains("static inline const char *flux__fs_remove_file(const char *path)"));
    assert!(
        generated.contains("static inline const char *flux__fs_remove_directory(const char *path)")
    );
    assert!(generated.contains("static const char *flux__fs_remove_directories(const char *path)"));
    assert!(generated.contains("static inline const char *flux__fs_write_text_mode"));
    assert!(generated.contains("fwrite(text, 1, text_length, file)"));
    assert!(generated.contains(
        "static inline const char *flux__fs_rename(const char *source, const char *destination)"
    ));
    assert!(generated.contains(
        "static inline const char *flux__fs_copy_file(const char *source, const char *destination)"
    ));

    let source_path = root.join("main.flux");
    fs::write(&source_path, &source).expect("filesystem API source should be writable");
    let binary = root.join("fs-api");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("filesystem API binary should build");
    assert!(
        built.status.success(),
        "filesystem API build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("filesystem API binary should run");
    assert!(run.status.success());
    let lines = String::from_utf8_lossy(&run.stdout)
        .lines()
        .map(str::to_string)
        .collect::<Vec<_>>();
    assert_eq!(
        lines,
        [
            "true", "true", "false", "true", "nil", "true", "nil", "true", "nil", "nil", "true",
            "nil", "true", "nil", "false", "true", "nil", "false", "nil", "false", "nil", "false"
        ]
    );
    assert_eq!(
        fs::read_to_string(&content).expect("written Flux file should be readable"),
        "onetwo"
    );
    assert_eq!(
        fs::read_to_string(&renamed).expect("copied and renamed Flux file should be readable"),
        "copy me"
    );
    assert!(!copy_destination.exists());
    assert!(!delete.exists());
    assert!(!created.exists());
    assert!(!recursive_root.exists());

    let unused = r#"
fn hidden() -> void {
    print(fs.exists("/tmp"))
    print(fs.createDirectories("/tmp/unused-flux-directory/nested"))
    print(fs.removeDirectories("/tmp/unused-flux-directory"))
    print(fs.writeText("/tmp/unused-flux-file", "unused"))
    print(fs.copyFile("/tmp/a", "/tmp/b"))
}
fn main() -> i64 {
    return 0
}
"#;
    let unused_generated = compile_to_c(unused).expect("dead filesystem calls should lower");
    assert!(!unused_generated.contains("#include <sys/stat.h>"));
    assert!(!unused_generated.contains("flux__fs_exists"));
    assert!(!unused_generated.contains("flux__fs_create_directories"));
    assert!(!unused_generated.contains("flux__fs_remove_directories"));
    assert!(!unused_generated.contains("flux__fs_write_text"));
    assert!(!unused_generated.contains("flux__fs_copy_file"));

    let invalid = r#"
fn main() -> i64 {
    fs.exists(1)
    fs.isFile(false)
    fs.isDirectory(1)
    fs.createDirectory(42)
    fs.createDirectories(false)
    fs.removeFile(false)
    fs.removeDirectory(1)
    fs.removeDirectories(false)
    fs.writeText("x", 1)
    fs.appendText(1, "x")
    fs.rename(false, "x")
    fs.copyFile("x", 1)
    fs.unknown("x")
    return 0
}
"#;
    let errors = check_source_all(invalid).expect_err("invalid filesystem calls should fail");
    for call in [
        "exists",
        "isFile",
        "isDirectory",
        "createDirectory",
        "createDirectories",
        "removeFile",
        "removeDirectory",
        "removeDirectories",
    ] {
        assert!(
            errors
                .iter()
                .any(|error| error.message.contains(&format!("fs.{call} path"))
                    && error.message.contains("expected str"))
        );
    }
    assert!(
        errors
            .iter()
            .any(|error| error.message.contains("fs.writeText text")
                && error.message.contains("expected str"))
    );
    assert!(
        errors
            .iter()
            .any(|error| error.message.contains("fs.appendText path")
                && error.message.contains("expected str"))
    );
    assert!(
        errors
            .iter()
            .any(|error| error.message.contains("fs.rename source")
                && error.message.contains("expected str"))
    );
    assert!(
        errors
            .iter()
            .any(|error| error.message.contains("fs.copyFile destination")
                && error.message.contains("expected str"))
    );
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("fs module has no function 'unknown'")
    }));
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn canonical_file_and_directory_capabilities_are_typed_native_and_tree_shaken() {
    let root = std::env::temp_dir().join(format!("flux-canonical-file-api-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("canonical file API fixture should be writable");
    let nested = root.join("nested/a");
    let content = nested.join("content.txt");
    let copy = nested.join("copy.txt");
    let renamed = nested.join("renamed.txt");
    let path = |value: &std::path::Path| {
        value
            .to_string_lossy()
            .replace('\\', "\\\\")
            .replace('"', "\\\"")
    };
    let source = format!(
        r#"
fn main() -> i64 {{
    print(directory.createAll("{}"))
    print(directory.exists("{}"))
    print(file.exists("{}"))
    print(file.write("{}", "one"))
    print(file.append("{}", "two"))
    let (size, sizeError) = file.size("{}")
    print(size)
    print(sizeError)
    let (fileModified, fileModifiedError) = file.modifiedUnixMillis("{}")
    print(fileModified > 0)
    print(fileModifiedError)
    let (directoryModified, directoryModifiedError) = directory.modifiedUnixMillis("{}")
    print(directoryModified > 0)
    print(directoryModifiedError)
    print(file.exists("{}"))
    print(directory.exists("{}"))
    print(file.copy("{}", "{}"))
    print(file.rename("{}", "{}"))
    print(file.exists("{}"))
    print(file.exists("{}"))
    print(file.remove("{}"))
    print(file.exists("{}"))
    print(directory.removeAll("{}"))
    print(directory.exists("{}"))
    return 0
}}
"#,
        path(&nested),
        path(&nested),
        path(&nested),
        path(&content),
        path(&content),
        path(&content),
        path(&content),
        path(&nested),
        path(&content),
        path(&content),
        path(&content),
        path(&copy),
        path(&copy),
        path(&renamed),
        path(&copy),
        path(&renamed),
        path(&renamed),
        path(&renamed),
        path(&nested),
        path(&nested),
    );

    check_source(&source).expect("canonical file and directory APIs should typecheck");
    let generated = compile_to_c(&source).expect("canonical file and directory APIs should lower");
    assert!(generated.contains("flux__fs_is_file"));
    assert!(generated.contains("flux__fs_is_directory"));
    assert!(generated.contains("flux__fs_create_directories"));
    assert!(generated.contains("flux__fs_write_text"));
    assert!(generated.contains("flux__fs_append_text"));
    assert!(generated.contains("flux__fs_file_size"));
    assert!(generated.contains("flux__fs_file_modified_unix_millis"));
    assert!(generated.contains("flux__fs_directory_modified_unix_millis"));
    assert!(generated.contains("flux__fs_copy_file"));
    assert!(generated.contains("flux__fs_rename"));
    assert!(generated.contains("flux__fs_remove_file"));
    assert!(generated.contains("flux__fs_remove_directories"));

    let source_path = root.join("main.flux");
    fs::write(&source_path, &source).expect("canonical file API source should be writable");
    let binary = root.join("canonical-file-api");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("canonical file API binary should build");
    assert!(
        built.status.success(),
        "canonical file API build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("canonical file API binary should run");
    assert!(run.status.success());
    let lines = String::from_utf8_lossy(&run.stdout)
        .lines()
        .map(str::to_string)
        .collect::<Vec<_>>();
    assert_eq!(
        lines,
        [
            "nil", "true", "false", "nil", "nil", "6", "nil", "true", "nil", "true", "nil", "true",
            "false", "nil", "nil", "false", "true", "nil", "false", "nil", "false"
        ]
    );
    assert!(!nested.exists());

    let unused = r#"
fn hidden() -> void {
    print(file.exists("/tmp/unused-flux-file"))
    let (_size, _failure) = file.size("/tmp/unused-flux-file")
    let (_modified, _modifiedFailure) = file.modifiedUnixMillis("/tmp/unused-flux-file")
    let (_directoryModified, _directoryModifiedFailure) = directory.modifiedUnixMillis("/tmp/unused-flux-directory")
    print(file.write("/tmp/unused-flux-file", "unused"))
    print(directory.createAll("/tmp/unused-flux-directory/nested"))
}

fn main() -> i64 {
    return 0
}
"#;
    let unused_generated =
        compile_to_c(unused).expect("dead canonical filesystem calls should lower");
    assert!(!unused_generated.contains("flux__fs_is_file"));
    assert!(!unused_generated.contains("flux__fs_file_size"));
    assert!(!unused_generated.contains("flux__fs_file_modified_unix_millis"));
    assert!(!unused_generated.contains("flux__fs_directory_modified_unix_millis"));
    assert!(!unused_generated.contains("flux__fs_write_text"));
    assert!(!unused_generated.contains("flux__fs_create_directories"));

    let invalid = r#"
fn main() -> i64 {
    file.exists(1)
    let (_size, _failure) = file.size(false)
    let (_modified, _modifiedFailure) = file.modifiedUnixMillis(1)
    let (_directoryModified, _directoryModifiedFailure) = directory.modifiedUnixMillis(false)
    file.write("x", 1)
    file.copy(false, "x")
    directory.exists(1)
    directory.create(false)
    directory.removeAll(42)
    return 0
}
"#;
    let errors =
        check_source_all(invalid).expect_err("invalid canonical filesystem calls should fail");
    for label in [
        "file.exists path",
        "file.size path",
        "file.modifiedUnixMillis path",
        "directory.modifiedUnixMillis path",
        "file.write text",
        "file.copy source",
        "directory.exists path",
        "directory.create path",
        "directory.removeAll path",
    ] {
        assert!(
            errors.iter().any(
                |error| error.message.contains(label) && error.message.contains("expected str")
            ),
            "missing canonical filesystem diagnostic for {label}: {errors:?}"
        );
    }

    let _ = fs::remove_dir_all(&root);
}

#[test]
fn file_read_lends_bounded_text_to_a_callback() {
    let root = std::env::temp_dir().join(format!("flux-file-read-api-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("file read fixture should be writable");
    let content = root.join("content.txt");
    fs::write(&content, "hello").expect("file read fixture content should be writable");
    let escaped = content
        .to_string_lossy()
        .replace('\\', "\\\\")
        .replace('"', "\\\"");
    let source = format!(
        r#"
fn show(text: str) -> void {{
    print(text)
}}
fn main() -> i64 {{
    let readError: error = file.read("{}", 32, show)
    print(readError)
    return 0
}}
"#,
        escaped
    );
    check_source(&source).expect("file.read should typecheck");
    let generated = compile_to_c(&source).expect("file.read should lower natively");
    assert!(generated.contains("flux__fs_read_text"));
    assert!(generated.contains("int extra = fgetc(file)"));
    assert!(generated.contains(
        "if (ferror(file)) { free(buffer); fclose(file); return \"failed to read file\"; }"
    ));

    let source_path = root.join("main.flux");
    fs::write(&source_path, &source).expect("file read source should be writable");
    let binary = root.join("file-read-api");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("file read binary should build");
    assert!(
        built.status.success(),
        "file read build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("file read binary should run");
    assert!(run.status.success());
    assert_eq!(String::from_utf8_lossy(&run.stdout), "hello\nnil\n");

    let invalid_content = root.join("invalid-utf8.bin");
    fs::write(&invalid_content, [0xf0, 0x80, 0x80, 0x80])
        .expect("invalid UTF-8 fixture should be writable");
    let invalid_path = invalid_content
        .to_string_lossy()
        .replace('\\', "\\\\")
        .replace('"', "\\\"");
    let invalid_source = format!(
        r#"
fn show(_text: str) -> void {{
}}
fn main() -> i64 {{
    let readError: error = file.read("{}", 32, show)
    print(readError)
    return 0
}}
"#,
        invalid_path
    );
    let invalid_source_path = root.join("invalid-utf8.flux");
    fs::write(&invalid_source_path, &invalid_source)
        .expect("invalid UTF-8 source should be writable");
    let invalid_binary = root.join("invalid-utf8");
    let invalid_built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&invalid_source_path)
        .arg("-o")
        .arg(&invalid_binary)
        .output()
        .expect("invalid UTF-8 file-read binary should build");
    assert!(invalid_built.status.success());
    let invalid_run = Command::new(&invalid_binary)
        .output()
        .expect("invalid UTF-8 file-read binary should run");
    assert!(invalid_run.status.success());
    assert_eq!(
        String::from_utf8_lossy(&invalid_run.stdout),
        "file contains invalid UTF-8\n"
    );

    let invalid = r#"
fn show(_text: str) -> void {
}
fn main() -> i64 {
    let _failure: error = file.read("content.txt", 0, show)
    return 0
}
"#;
    let error = check_source(invalid).expect_err("zero file.read limit should fail");
    assert!(
        error
            .message
            .contains("file.read maxBytes must be in 1..=65536")
    );

    let dead = r#"
fn show(_text: str) -> void {
}
fn hidden() -> void {
    print(file.read("unused.txt", 16, show))
}
fn main() -> i64 {
    return 0
}
"#;
    let dead_generated = compile_to_c(dead).expect("dead file.read should lower");
    assert!(!dead_generated.contains("flux__fs_read_text"));
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn directory_list_lends_entry_names_to_a_callback() {
    let root = std::env::temp_dir().join(format!("flux-directory-list-api-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("directory list fixture should be writable");
    fs::write(root.join("alpha.txt"), "a").expect("directory list first entry should be writable");
    fs::write(root.join("beta.txt"), "b").expect("directory list second entry should be writable");
    let escaped = root
        .to_string_lossy()
        .replace('\\', "\\\\")
        .replace('"', "\\\"");
    let source = format!(
        r#"
fn show(name: str) -> void {{
    print(name)
}}
fn main() -> i64 {{
    let listError: error = directory.list("{}", show)
    print(listError)
    return 0
}}
"#,
        escaped
    );
    check_source(&source).expect("directory.list should typecheck");
    let generated = compile_to_c(&source).expect("directory.list should lower natively");
    assert!(generated.contains("flux__fs_list_directory"));
    assert!(generated.contains("flux__fs_entry_name_length"));
    assert!(!generated.contains("strlen(entry->d_name)"));

    let source_path = root.join("main.flux");
    fs::write(&source_path, &source).expect("directory list source should be writable");
    let binary = root.join("directory-list-api");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("directory list binary should build");
    assert!(
        built.status.success(),
        "directory list build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("directory list binary should run");
    assert!(run.status.success());
    let output = String::from_utf8_lossy(&run.stdout);
    assert!(output.contains("alpha.txt\n"));
    assert!(output.contains("beta.txt\n"));
    assert!(output.ends_with("nil\n"));

    let invalid = r#"
fn main() -> i64 {
    let _failure: error = directory.list(".", false)
    return 0
}
"#;
    let error = check_source(invalid).expect_err("directory.list callback type should be checked");
    assert!(
        error
            .message
            .contains("directory.list callback: expected fn(str) -> void")
    );
    let _ = fs::remove_dir_all(&root);
}

