#[test]
fn list_optional_pattern_guards_bind_present_values_and_lower_natively() {
    let source = r#"
fn maybe(flag: bool) -> i64? {
    if flag:
        return 7
    return none
}

fn main() -> i64 {
    let values: i64[] = [1, if let value = maybe(true): value, if let missing = maybe(false): missing else: 9]
    print values.length
    print values[1]
    print values[2]
    return 0
}
"#;

    check_source(source).expect("list optional pattern guards should typecheck");
    let formatted = fluxc::formatter::format_source(source)
        .expect("list optional pattern guards should format canonically");
    assert!(formatted.contains("if let value = maybe(true): value"));
    assert!(formatted.contains("if let missing = maybe(false): missing else: 9"));
    assert_eq!(
        fluxc::formatter::format_source(&formatted)
            .expect("formatted list optional guards should reparse"),
        formatted
    );

    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1419))
        .expect("list optional guards should retain typed semantic IR");
    let graph = database
        .control_flow_graph("main")
        .expect("main should have a control-flow graph");
    let guarded_value = graph
        .values()
        .iter()
        .find_map(|value| match value.kind {
            ControlFlowValueKind::ListIf { value, .. } => graph.value(value),
            _ => None,
        })
        .expect("list optional guard should retain its selected value in typed IR");
    assert!(matches!(
        &guarded_value.kind,
        ControlFlowValueKind::NameRead { name, definitions }
            if name == "value" && !definitions.is_empty()
    ));

    let generated =
        compile_to_c(source).expect("list optional pattern guards should lower natively");
    assert!(generated.contains("flux__list_guard_optional_"));
    assert!(generated.contains(".has_value"));
    assert!(generated.contains(".value"));

    let root = std::env::temp_dir().join(format!(
        "flux-list-optional-guards-{}-{}",
        std::process::id(),
        std::thread::current().name().unwrap_or("test")
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary list optional guard directory should be writable");
    let c_path = root.join("list_optional_guards.c");
    let exe_path = root.join("list_optional_guards");
    fs::write(&c_path, generated).expect("generated list optional guard C should be writable");
    let compile = Command::new("clang")
        .args(["-std=c11", "-O2"])
        .arg(&c_path)
        .arg("-o")
        .arg(&exe_path)
        .output()
        .expect("clang should compile list optional guards");
    assert!(
        compile.status.success(),
        "list optional guard C should compile: {}",
        String::from_utf8_lossy(&compile.stderr)
    );
    let output = Command::new(&exe_path)
        .output()
        .expect("list optional guard program should run");
    assert!(output.status.success());
    assert_eq!(String::from_utf8_lossy(&output.stdout), "3\n7\n9\n");
    let _ = fs::remove_dir_all(&root);

    let non_optional = r#"
fn main() -> i64 {
    let values: i64[] = [if let value = 1: value]
    return values.length
}
"#;
    let error = check_source(non_optional).expect_err("list optional guards require optionals");
    assert!(
        error
            .message
            .contains("list optional guard requires an optional value, got i64"),
        "unexpected diagnostic: {}",
        error.message
    );

    let shadow = r#"
fn maybe() -> i64? {
    return 1
}
fn main() -> i64 {
    let value: i64 = 3
    let values: i64[] = [if let value = maybe(): value]
    return values.length
}
"#;
    let error = check_source(shadow).expect_err("list optional guards must not shadow bindings");
    assert!(
        error
            .message
            .contains("list optional guard binding 'value' shadows an existing binding"),
        "unexpected diagnostic: {}",
        error.message
    );
}

#[test]
fn list_destructuring_patterns_infer_types_and_lower_strided_views() {
    let source = r#"
fn main() -> i64 {
    let values: i64[] = [10, 20, 30]
    let reversed: i64[] = values[::-1]
    let [first, _, last] = reversed
    print first
    print last
    return 0
}
"#;

    check_source(source).expect("exact list destructuring should typecheck");
    let generated = compile_to_c(source).expect("list destructuring should lower natively");
    assert!(generated.contains("flux__list_pattern_"));
    assert!(generated.contains(".len != 3"));
    assert!(generated.contains("Flux runtime error: list pattern requires exactly 3 elements"));
    assert!(generated.contains("flux_list_at_unchecked(flux__list_pattern_"));
    assert!(generated.contains(", 0, sizeof(int64_t)"));
    assert!(generated.contains(", 2, sizeof(int64_t)"));

    let formatted = fluxc::formatter::format_source(source).expect("list pattern should format");
    assert!(formatted.contains("let [first, _, last] = reversed"));
    let formatted_again =
        fluxc::formatter::format_source(&formatted).expect("formatted list pattern should reparse");
    assert_eq!(formatted_again, formatted);

    let database = fluxc::semantic::SemanticDatabase::analyze(&formatted, SourceId::new(741))
        .expect("list pattern should analyze semantically");
    for name in ["first", "last"] {
        let symbol = database
            .symbols_named(name)
            .find(|symbol| symbol.kind == fluxc::semantic::SymbolKind::Binding)
            .expect("list pattern binding should be indexed");
        assert_eq!(symbol.ty, Some(fluxc::ast::Type::I64));
    }
    assert!(database.symbols_named("_").next().is_none());
}

#[test]
fn list_rest_patterns_bind_zero_copy_middle_views() {
    let source = r#"
fn main() -> i64 {
    let values: i64[] = [10, 20, 30, 40, 50]
    let reversed: i64[] = values[::-1]
    let [first, ...middle, last] = reversed
    print first
    print middle.length
    print middle.first
    print middle.last
    print last
    return 0
}
"#;

    check_source(source).expect("list rest destructuring should typecheck");
    let generated = compile_to_c(source).expect("list rest destructuring should lower natively");
    assert!(generated.contains(".len < 2"));
    assert!(generated.contains("Flux runtime error: list pattern requires at least 2 elements"));
    assert!(generated.contains(".len - 1, sizeof(int64_t)"));
    assert!(generated.contains(".len = flux__list_pattern_"));
    assert!(generated.contains("flux_list_stride(flux__list_pattern_"));

    let formatted =
        fluxc::formatter::format_source(source).expect("list rest pattern should format");
    assert!(formatted.contains("let [first, ...middle, last] = reversed"));
    let formatted_again = fluxc::formatter::format_source(&formatted)
        .expect("formatted list rest pattern should reparse");
    assert_eq!(formatted_again, formatted);

    let database = fluxc::semantic::SemanticDatabase::analyze(&formatted, SourceId::new(742))
        .expect("list rest pattern should analyze semantically");
    let middle = database
        .symbols_named("middle")
        .find(|symbol| symbol.kind == fluxc::semantic::SymbolKind::Binding)
        .expect("rest binding should be indexed");
    assert_eq!(
        middle.ty,
        Some(fluxc::ast::Type::List(Box::new(fluxc::ast::Type::I64)))
    );
}

#[test]
fn rejects_invalid_list_destructuring_patterns() {
    let non_list = r#"
fn main() -> i64 {
    let [value] = 7
    print value
    return 0
}
"#;
    let error = check_source(non_list).expect_err("list pattern source should require a list");
    assert!(
        error
            .message
            .contains("list destructuring requires a list value, got i64")
    );

    let duplicate = r#"
fn main() -> i64 {
    let values: i64[] = [1, 2]
    let [value, value] = values
    print value
    return 0
}
"#;
    let error = check_source(duplicate).expect_err("duplicate list pattern bindings should fail");
    assert!(
        error
            .message
            .contains("duplicate list pattern binding 'value'")
    );

    let empty = r#"
fn main() -> i64 {
    let values: i64[] = [1, 2]
    let [] = values
    return 0
}
"#;
    let error = check_source(empty).expect_err("empty list patterns should fail");
    assert!(
        error
            .message
            .contains("list destructuring requires at least one binding")
    );

    let multiple_rest = r#"
fn main() -> i64 {
    let values: i64[] = [1, 2]
    let [...left, ...right] = values
    print left.length
    print right.length
    return 0
}
"#;
    let error = check_source(multiple_rest).expect_err("multiple list rest patterns should fail");
    assert!(
        error
            .message
            .contains("list destructuring allows only one rest pattern")
    );

    let bare_rest = r#"
fn main() -> i64 {
    let values: i64[] = [1, 2]
    let [first, ...] = values
    print first
    return 0
}
"#;
    let error = check_source(bare_rest).expect_err("bare list rest patterns should fail");
    assert!(
        error
            .message
            .contains("list rest patterns require a binding after '...'")
    );
}

