#[test]
fn ownership_copy_classification_is_structural_and_alias_aware() {
    let source = r#"
struct Pair {
    count: i64
    label: str
}

enum Choice {
    PairValue(Pair)
    Missing
}

type PairAlias = Pair

interface Readable {
    fn read(value: i64) -> i64
}

fn readPair(pair: Pair, value: i64) -> i64 {
    print(pair.label)
    return value
}

impl Readable for Pair {
    read: readPair
}

fn main() -> i64 {
    return 0
}
"#;

    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1204))
        .expect("copyable value declarations should analyze");
    let signatures = database.signatures();
    assert!(signatures.is_copy_type(&fluxc::ast::Type::I64));
    assert!(signatures.is_copy_type(&fluxc::ast::Type::Bool));
    assert!(signatures.is_copy_type(&fluxc::ast::Type::Str));
    assert!(signatures.is_copy_type(&fluxc::ast::Type::Error));
    assert!(signatures.is_copy_type(&fluxc::ast::Type::Named("Pair".to_string())));
    assert!(signatures.is_copy_type(&fluxc::ast::Type::Named("PairAlias".to_string())));
    assert!(signatures.is_copy_type(&fluxc::ast::Type::Named("Choice".to_string())));
    assert!(signatures.is_copy_type(&fluxc::ast::Type::Named("Readable".to_string())));
    assert!(signatures.is_copy_type(&fluxc::ast::Type::Function {
        params: vec![fluxc::ast::Type::I64],
        returns: vec![fluxc::ast::Type::Bool],
    }));
    assert!(!signatures.is_copy_type(&fluxc::ast::Type::Void));
    assert!(!signatures.is_copy_type(&fluxc::ast::Type::List(Box::new(fluxc::ast::Type::I64,))));

    assert!(signatures.is_send_type(&fluxc::ast::Type::I64));
    assert!(signatures.is_send_type(&fluxc::ast::Type::Bool));
    assert!(signatures.is_send_type(&fluxc::ast::Type::Error));
    assert!(!signatures.is_send_type(&fluxc::ast::Type::Str));
    assert!(!signatures.is_send_type(&fluxc::ast::Type::Named("Pair".to_string())));
    assert!(!signatures.is_send_type(&fluxc::ast::Type::Named("PairAlias".to_string())));
    assert!(!signatures.is_send_type(&fluxc::ast::Type::Named("Choice".to_string())));
    assert!(!signatures.is_send_type(&fluxc::ast::Type::Named("Readable".to_string())));
    assert!(signatures.is_send_type(&fluxc::ast::Type::Optional(
        Box::new(fluxc::ast::Type::I64,)
    )));
    assert!(!signatures.is_send_type(&fluxc::ast::Type::Optional(
        Box::new(fluxc::ast::Type::Str,)
    )));
    assert!(signatures.is_send_type(&fluxc::ast::Type::Function {
        params: vec![fluxc::ast::Type::Str],
        returns: vec![fluxc::ast::Type::Str],
    }));
}

#[test]
fn direct_non_copy_transfers_move_locals_and_reject_use_after_move() {
    let moved = r#"
fn main() -> i64 {
    let source: i64[] = [10, 20]
    let destination: i64[] = source
    print(destination[0])
    return 0
}
"#;
    check_source(moved).expect("a direct non-copy local transfer should move the source");
    compile_to_c(moved).expect("a valid non-copy local move should lower natively");

    let use_after_move = r#"
fn main() -> i64 {
    let source: i64[] = [10, 20]
    let destination: i64[] = source
    print(destination[0])
    print(source[1])
    return 0
}
"#;
    let errors = check_source_all(use_after_move).expect_err("using a moved list must fail");
    let moved_error = errors
        .iter()
        .find(|error| {
            error
                .message
                .contains("use of moved non-copy binding 'source'")
        })
        .expect("use-after-move should identify the consumed binding");
    assert!(
        moved_error
            .labels
            .iter()
            .any(|label| label.message.contains("'source' moved here"))
    );

    let copy_values = r#"
fn main() -> i64 {
    let source: i64 = 7
    let destination: i64 = source
    print(source)
    print(destination)
    return 0
}
"#;
    check_source(copy_values).expect("copy values must remain reusable after assignment");
}

#[test]
fn explicit_drop_is_a_consuming_call_boundary_for_non_copy_values() {
    let valid = r#"
fn main() -> i64 {
    let values: i64[] = [1, 2, 3]
    drop(values)
    return 0
}
"#;
    check_source(valid).expect("drop should consume a non-copy list");
    let generated = compile_to_c(valid).expect("drop should lower through native codegen");
    assert!(generated.contains("(void)("));

    let use_after_drop = r#"
fn main() -> i64 {
    let values: i64[] = [1, 2, 3]
    drop(values)
    print(values.count)
    return 0
}
"#;
    let errors = check_source_all(use_after_drop).expect_err("dropped values must not be reusable");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("use of moved non-copy binding 'values'")
    }));

    let set_value = r#"
fn main() -> i64 {
    let values: set<i64> = {1, 2, 3}
    drop(values)
    return 0
}
"#;
    check_source(set_value).expect("drop should consume a non-copy set");
    let set_use_after_drop = r#"
fn main() -> i64 {
    let values: set<i64> = {1, 2, 3}
    drop(values)
    print(values.count)
    return 0
}
"#;
    let errors =
        check_source_all(set_use_after_drop).expect_err("dropped sets must not be reusable");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("use of moved non-copy binding 'values'")
    }));

    let optional_list = r#"
fn main() -> i64 {
    let values: i64[]? = [1, 2, 3]
    drop(values)
    return 0
}
"#;
    check_source(optional_list).expect("drop should consume an ownership-tracked optional list");
    compile_to_c(optional_list).expect("an optional-list drop should lower natively");

    let optional_list_use_after_drop = r#"
fn main() -> i64 {
    let values: i64[]? = [1, 2, 3]
    drop(values)
    let destination: i64[]? = values
    if let value = borrow destination:
        print(value[0])
    return 0
}
"#;
    let errors = check_source_all(optional_list_use_after_drop)
        .expect_err("an optional list must not be reusable after drop");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("use of moved non-copy binding 'values'")
    }));

    let map_value = r#"
fn main() -> i64 {
    let values: map<i64, i64> = map{1: 2}
    drop(values)
    return 0
}
"#;
    check_source(map_value).expect("drop should consume a non-copy map");

    let optional_map = r#"
fn main() -> i64 {
    let values: map<i64, i64>? = map{1: 2}
    drop(values)
    return 0
}
"#;
    check_source(optional_map).expect("drop should consume an optional non-copy map");
    compile_to_c(optional_map).expect("an optional-map drop should lower natively");

    let optional_map_use_after_drop = r#"
fn main() -> i64 {
    let values: map<i64, i64>? = map{1: 2}
    drop(values)
    let destination: map<i64, i64>? = values
    return 0
}
"#;
    let errors = check_source_all(optional_map_use_after_drop)
        .expect_err("an optional map must not be reusable after drop");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("use of moved non-copy binding 'values'")
    }));

    let copy_value = r#"
fn main() -> i64 {
    let value: i64 = 1
    drop(value)
    return 0
}
"#;
    let errors = check_source_all(copy_value).expect_err("drop must reject Copy values");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("drop expects a non-copy collection value")
    }));
}

