#[test]
fn ownership_ir_records_typed_return_boundaries() {
    let source = r#"
fn choose(flag: bool) -> i64 {
    if flag:
        return 7
    return 9
}
fn main() -> i64 {
    return choose(true)
}
"#;
    let database = SemanticDatabase::analyze(source, SourceId::new(1423))
        .expect("return source should analyze");
    let graph = database
        .control_flow_graph("choose")
        .expect("choose should expose a CFG");
    let returns = graph.ownership_returns().collect::<Vec<_>>();
    assert_eq!(returns.len(), 2);
    for (node, value) in &returns {
        assert_eq!(
            graph.ownership_returns_at(*node),
            std::slice::from_ref(*value)
        );
    }
    assert!(returns.iter().all(|(_, value)| {
        value.kind == OwnershipCallArgumentKind::Copy
            && value.definitions.is_empty()
            && value.borrowed_definitions.is_empty()
    }));
    assert!(returns.iter().all(|(_, value)| {
        graph
            .values()
            .get(value.value.0)
            .is_some_and(|ir_value| ir_value.ty == Type::I64 && ir_value.span == value.span)
    }));
}

#[test]
fn ownership_ir_move_events_retain_exact_reaching_source_definitions() {
    let source = r#"
fn choose(flag: bool) -> i64 {
    if flag:
        let values: i64[] = [1]
        let moved: i64[] = values
        print(moved.count)
    else:
        let values: i64[] = [2]
        let moved: i64[] = values
        print(moved.count)
    return 0
}
fn main() -> i64 {
    return choose(true)
}
"#;
    let database = SemanticDatabase::analyze(source, SourceId::new(1422))
        .expect("shadowed move source should analyze");
    let graph = database
        .control_flow_graph("choose")
        .expect("choose should expose a CFG");
    let moves = graph
        .nodes()
        .iter()
        .flat_map(|node| node.ownership.moves.iter())
        .filter(|movement| movement.destination == "moved")
        .collect::<Vec<_>>();
    assert_eq!(moves.len(), 2);
    assert!(
        moves.iter().all(|movement| {
            movement.source_definitions.len() == 1
                && graph.definition_name(movement.source_definitions[0]) == Some("values")
        }),
        "unexpected move provenance: {moves:?}"
    );
    assert_ne!(
        moves[0].source_definitions[0], moves[1].source_definitions[0],
        "shadowed move events must retain distinct source definitions"
    );
}

#[test]
fn rejects_moving_list_owner_while_control_flow_selected_view_is_live() {
    let enum_match = r#"
enum Choice {
    Tail
    LastTwo
}

fn main() -> i64 {
    let values: i64[] = [10, 20, 30, 40]
    let choice: Choice = Choice.Tail()
    let view: i64[] = match choice:
        Choice.Tail(): values[1:]
        Choice.LastTwo(): values[2:]
    let destination: i64[] = values
    print(view[0])
    print(destination[0])
    return 0
}
"#;

    let errors = check_source_all(enum_match)
        .expect_err("a live view selected by enum match must keep its owner borrowed");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("while borrowed view 'view' is still live")
    }));

    let list_match = r#"
fn main() -> i64 {
    let values: i64[] = [10, 20, 30, 40]
    let view: i64[] = match values:
        []: values[:]
        [_]: values[:1]
        [_, ..._]: values[1:]
    let destination: i64[] = values
    print(view[0])
    print(destination[0])
    return 0
}
"#;

    let errors = check_source_all(list_match)
        .expect_err("a live view selected by list match must keep its owner borrowed");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("while borrowed view 'view' is still live")
    }));

    let dead_view = r#"
enum Choice {
    Tail
    LastTwo
}

fn main() -> i64 {
    let values: i64[] = [10, 20, 30, 40]
    let choice: Choice = Choice.Tail()
    let view: i64[] = match choice:
        Choice.Tail(): values[1:]
        Choice.LastTwo(): values[2:]
    print(view[0])
    let destination: i64[] = values
    print(destination[0])
    return 0
}
"#;

    check_source(dead_view).expect("a dead match-selected view must not block a later move");
    compile_to_c(dead_view).expect("moving after a match-selected view's last use should lower");
}

