#[test]
fn explicit_borrow_rejects_temporaries_copy_values_and_moved_owners() {
    let temporary = r#"
fn main() -> i64 {
    let view: i64[] = borrow [10, 20]
    print(view[0])
    return 0
}
"#;
    let error = check_source(temporary).expect_err("temporary storage must not be borrowed");
    assert!(
        error.message.contains(
            "borrow currently requires named list storage or a zero-copy view rooted in it"
        )
    );

    let copy = r#"
fn main() -> i64 {
    let value: i64 = 10
    let alias: i64 = borrow value
    return alias
}
"#;
    let error = check_source(copy).expect_err("copy values do not need an ownership borrow");
    assert!(
        error
            .message
            .contains(
                "borrow currently supports concrete list, set, or map bindings and optional collection views"
            )
    );

    let optional = r#"
fn main() -> i64 {
    let values: i64[]? = [10, 20]
    if let present = borrow values:
        print(present[0])
    return 0
}
"#;
    check_source(optional).expect("borrowed optional list bindings should typecheck");
    compile_to_c(optional).expect("borrowed optional list bindings should lower natively");

    let live_optional_binding = r#"
fn main() -> i64 {
    let values: i64[] = [10, 20]
    let optional: i64[]? = borrow values
    if let present = borrow optional:
        let destination: i64[] = values
        print(destination[0])
        print(present[0])
    return 0
}
"#;
    let errors = check_source_all(live_optional_binding)
        .expect_err("an optional list pattern binding must keep its owner borrowed");
    assert!(
        errors.iter().any(|error| {
            error.message.contains(
                "cannot move non-copy binding 'values' while borrowed view 'present' is still live",
            )
        }),
        "optional binding errors: {errors:?}"
    );

    let moved = r#"
fn main() -> i64 {
    let values: i64[] = [10, 20]
    let destination: i64[] = values
    let view: i64[] = borrow values
    print(destination[0])
    print(view[0])
    return 0
}
"#;
    let errors = check_source_all(moved).expect_err("a moved owner cannot be borrowed later");
    assert!(
        errors.iter().any(|error| error
            .message
            .contains("use of moved non-copy binding 'values'")),
        "borrowing a moved owner should report its moved-state read: {errors:?}"
    );
}

