#[test]
fn rejects_moving_list_owner_while_zero_copy_view_is_live() {
    let live_slice = r#"
fn main() -> i64 {
    let source: i64[] = [10, 20, 30]
    let tail: i64[] = source[1:]
    let destination: i64[] = source
    print(tail[0])
    print(destination[0])
    return 0
}
"#;
    let errors = check_source_all(live_slice)
        .expect_err("moving a list owner while a slice borrow is live must fail");
    let borrow_error = errors
        .iter()
        .find(|error| {
            error
                .message
                .contains("while borrowed view 'tail' is still live")
        })
        .expect("the live borrowed view should be identified");
    assert!(
        borrow_error
            .labels
            .iter()
            .any(|label| label.message.contains("'tail' borrows from 'source'"))
    );

    let dead_slice = r#"
fn main() -> i64 {
    let source: i64[] = [10, 20, 30]
    let tail: i64[] = source[1:]
    print(tail[0])
    let destination: i64[] = source
    print(destination[0])
    return 0
}
"#;
    check_source(dead_slice).expect("a dead slice borrow must not prevent a later owner move");
    compile_to_c(dead_slice).expect("a move after the slice's last use should lower natively");
    let database = fluxc::semantic::SemanticDatabase::analyze(dead_slice, SourceId::new(1208))
        .expect("borrow provenance should remain available through semantic CFG analysis");
    let graph = database
        .control_flow_graph("main")
        .expect("main should expose a CFG");
    assert!(
        graph.borrowed_definition_span("tail", "source").is_some(),
        "normalized ownership IR should expose the zero-copy borrow source"
    );
    let tail_read = graph
        .nodes()
        .iter()
        .find(|node| node.ownership.reads.iter().any(|read| read == "tail"))
        .expect("the live tail read should be represented in the CFG");
    let tail_borrows = graph
        .borrow_state_before(tail_read.id)
        .expect("every CFG node should expose a borrow-state slot");
    assert!(
        tail_borrows.contains("tail", "source"),
        "the zero-copy tail lifetime should remain active through its final read"
    );
    let tail_start = graph
        .borrow_starts()
        .iter()
        .find(|start| start.borrower == "tail" && start.source == "source")
        .expect("normalized ownership IR should expose the edge where the tail borrow starts");
    let start_boundaries = graph
        .borrow_boundaries_on_edge(tail_start.from, tail_start.to)
        .collect::<Vec<_>>();
    assert_eq!(start_boundaries.len(), 1);
    assert!(matches!(
        start_boundaries[0],
        ControlFlowBorrowBoundary::Start(start)
            if start.borrower == "tail" && start.source == "source"
    ));
    assert!(
        graph
            .borrow_state_before(tail_start.from)
            .is_some_and(|state| !state.contains("tail", "source")),
        "the explicit start edge must leave a state where the borrow is not yet live"
    );
    assert!(
        graph
            .borrow_state_before(tail_start.to)
            .is_some_and(|state| state.contains("tail", "source")),
        "the explicit start edge must enter a state where the borrow is live"
    );
    let destination_read = graph
        .nodes()
        .iter()
        .find(|node| {
            node.ownership
                .reads
                .iter()
                .any(|read| read == "destination")
        })
        .expect("the moved destination should have a later read");
    let destination_borrows = graph
        .borrow_state_before(destination_read.id)
        .expect("every CFG node should expose a borrow-state slot");
    assert!(
        !destination_borrows.contains("tail", "source"),
        "the tail borrow lifetime should end after its final reachable use"
    );
    let tail_end = graph
        .borrow_ends()
        .iter()
        .find(|end| end.borrower == "tail" && end.source == "source")
        .expect("normalized ownership IR should expose the edge where the tail borrow ends");
    let end_boundaries = graph
        .borrow_boundaries_on_edge(tail_end.from, tail_end.to)
        .collect::<Vec<_>>();
    assert_eq!(end_boundaries.len(), 1);
    assert!(matches!(
        end_boundaries[0],
        ControlFlowBorrowBoundary::End(end)
            if end.borrower == "tail" && end.source == "source"
    ));
    assert!(
        graph
            .borrow_state_before(tail_end.from)
            .is_some_and(|state| state.contains("tail", "source")),
        "the explicit end edge must leave a state where the borrow is still live"
    );
    assert!(
        graph
            .borrow_state_before(tail_end.to)
            .is_some_and(|state| !state.contains("tail", "source")),
        "the explicit end edge must enter a state where the borrow is dead"
    );

    let chained_view = r#"
fn main() -> i64 {
    let source: i64[] = [10, 20, 30, 40]
    let tail: i64[] = source[1:]
    let lastTwo: i64[] = tail | take 2
    let destination: i64[] = source
    print(lastTwo[0])
    print(destination[0])
    return 0
}
"#;
    let errors = check_source_all(chained_view)
        .expect_err("transitive zero-copy view borrows must keep the owner live");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("while borrowed view 'lastTwo' is still live")
    }));

    let live_rest = r#"
fn main() -> i64 {
    let source: i64[] = [10, 20, 30, 40]
    let [_, ...middle, _] = source
    let destination: i64[] = source
    print(middle[0])
    print(destination[0])
    return 0
}
"#;
    let errors = check_source_all(live_rest)
        .expect_err("a live list-rest view must keep its owner borrowed");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("while borrowed view 'middle' is still live")
    }));

    let live_nested_element = r#"
fn main() -> i64 {
    let source: i64[][] = [[10, 20], [30, 40]]
    let [first, ..._] = source
    let destination: i64[][] = source
    print(first[0])
    print(destination[0][0])
    return 0
}
"#;
    let errors = check_source_all(live_nested_element)
        .expect_err("a destructured nested-list element is a borrowed view");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("while borrowed view 'first' is still live")
    }));

    let live_match_rest = r#"
fn main() -> i64 {
    let source: i64[] = [10, 20, 30]
    match source:
        []:
            print 0
        [_, ...middle]:
            let destination: i64[] = source
            print(middle[0])
            print(destination[0])
    return 0
}
"#;
    let errors = check_source_all(live_match_rest)
        .expect_err("a live list-match rest binding must keep its owner borrowed");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("while borrowed view 'middle' is still live")
    }));

    for property in ["first", "last", "single"] {
        let live_property = format!(
            "fn main() -> i64 {{\n    let source: i64[][] = [[10, 20], [30, 40]]\n    let view: i64[] = source.{property}\n    let destination: i64[][] = source\n    print(view[0])\n    print(destination[0][0])\n    return 0\n}}\n"
        );
        let errors = check_source_all(&live_property)
            .expect_err("a live nested-list property view must keep its owner borrowed");
        assert!(errors.iter().any(|error| {
            error
                .message
                .contains("while borrowed view 'view' is still live")
        }));
    }

    let dead_property = r#"
fn main() -> i64 {
    let source: i64[][] = [[10, 20], [30, 40]]
    let view: i64[] = source.first
    print(view[0])
    let destination: i64[][] = source
    print(destination[0][0])
    return 0
}
"#;
    check_source(dead_property)
        .expect("a dead nested-list property borrow must not prevent a later owner move");
    compile_to_c(dead_property)
        .expect("a move after a nested-list property view's last use should lower natively");

    let chained_view = r#"
fn main() -> i64 {
    let source: i64[][] = [[10, 20], [30, 40]]
    let view: i64[] = source[0][1:]
    let destination: i64[][] = source
    print(view[0])
    print(destination[0][0])
    return 0
}
"#;
    let errors = check_source_all(chained_view)
        .expect_err("a chained zero-copy view must retain the original owner borrow");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("while borrowed view 'view' is still live")
    }));

    let dead_rest = r#"
fn main() -> i64 {
    let source: i64[] = [10, 20, 30]
    let [_, ...middle] = source
    print(middle[0])
    let destination: i64[] = source
    print(destination[0])
    return 0
}
"#;
    check_source(dead_rest).expect("a dead list-rest borrow must not prevent a later owner move");
}

#[test]
fn foreach_nested_list_bindings_preserve_borrow_provenance() {
    let live_binding = r#"
fn main() -> i64 {
    let rows: i64[][] = [[10, 20], [30, 40]]
    for row in rows:
        let destination: i64[][] = rows
        print(row[0])
        print(destination[0][0])
        break
    return 0
}
"#;

    let errors = check_source_all(live_binding)
        .expect_err("a live nested-list foreach binding must keep its iterable owner borrowed");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("while borrowed view 'row' is still live")
    }));

    let dead_binding = r#"
fn main() -> i64 {
    let rows: i64[][] = [[10, 20], [30, 40]]
    for row in rows:
        print(row[0])
        let destination: i64[][] = rows
        print(destination[0][0])
        break
    return 0
}
"#;

    check_source(dead_binding)
        .expect("a foreach element borrow must end after its final reachable use");
    compile_to_c(dead_binding)
        .expect("moving after the foreach element's last use on a breaking path should lower");
    let database = fluxc::semantic::SemanticDatabase::analyze(dead_binding, SourceId::new(1210))
        .expect("foreach borrow provenance should remain available through semantic CFG analysis");
    let graph = database
        .control_flow_graph("main")
        .expect("main should expose a CFG");
    assert!(
        graph.borrowed_definition_span("row", "rows").is_some(),
        "normalized ownership IR should expose the foreach element borrow source"
    );
}

#[test]
fn borrowed_list_views_reborrow_without_moving_the_view_binding() {
    let foreach_alias = r#"
fn main() -> i64 {
    let rows: i64[][] = [[10, 20], [30, 40]]
    for row in rows:
        let alias: i64[] = row
        print(row[0])
        print(alias[1])
        break
    return 0
}
"#;
    check_source(foreach_alias)
        .expect("aliasing a borrowed foreach element should be an immutable reborrow");
    compile_to_c(foreach_alias).expect("borrowed foreach aliases should lower natively");

    let destructured_alias = r#"
fn main() -> i64 {
    let values: i64[] = [10, 20, 30, 40]
    let [_, ...middle, _] = values
    let alias: i64[] = middle
    print(middle[0])
    print(alias[0])
    return 0
}
"#;
    check_source(destructured_alias)
        .expect("aliasing a borrowed list-rest view should not move the original view binding");
    compile_to_c(destructured_alias).expect("borrowed list-rest aliases should lower natively");

    let match_alias = r#"
fn main() -> i64 {
    let values: i64[] = [10, 20, 30]
    match values:
        []:
            print 0
        [_, ...tail]:
            let alias: i64[] = tail
            print(tail[0])
            print(alias[0])
    return 0
}
"#;
    check_source(match_alias)
        .expect("aliasing a borrowed list-match view should not move the pattern binding");
    compile_to_c(match_alias).expect("borrowed list-match aliases should lower natively");

    let live_owner_borrow = r#"
fn main() -> i64 {
    let values: i64[] = [10, 20, 30]
    let [_, ...middle] = values
    let alias: i64[] = middle
    let destination: i64[] = values
    print(alias[0])
    print(destination[0])
    return 0
}
"#;
    let errors = check_source_all(live_owner_borrow)
        .expect_err("reborrowing a view must still keep the original owner borrowed");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("while borrowed view 'alias' is still live")
    }));
}

#[test]
fn sibling_branch_alias_names_do_not_cross_contaminate_borrow_provenance() {
    let source = r#"
fn positive(value: i64) -> bool {
    return value > 0
}

fn main() -> i64 {
    let source: i64[] = [10, 20, 30]
    if positive(1):
        let view: i64[] = source[1:]
        let projected: i64[] = take(view, 1)
        print(projected[0])
    else:
        let view: i64[] = [90, 100]
        let projected: i64[] = take(view, 1)
        let destination: i64[] = source
        print(projected[0])
        print(destination[0])
    return 0
}
"#;

    check_source(source).expect(
        "a borrowed view chain in one branch must not poison unrelated same-named bindings in a sibling branch",
    );
    compile_to_c(source).expect("branch-local borrow provenance should lower natively");
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1209))
        .expect("branch-local borrow lifetimes should analyze");
    let graph = database
        .control_flow_graph("main")
        .expect("main should expose a CFG");
    let projected_states = graph
        .nodes()
        .iter()
        .filter(|node| node.ownership.reads.iter().any(|read| read == "projected"))
        .map(|node| {
            graph
                .borrow_state_before(node.id)
                .expect("every CFG node should expose a borrow-state slot")
        })
        .collect::<Vec<_>>();
    assert_eq!(projected_states.len(), 2);
    assert!(
        projected_states
            .iter()
            .any(|state| state.contains("projected", "source")),
        "the borrowed branch should retain projected -> source lifetime provenance"
    );
    assert!(
        projected_states
            .iter()
            .any(|state| !state.contains("projected", "source")),
        "the sibling owned branch must not inherit the borrowed branch lifetime"
    );
    let branch_start = graph
        .borrow_starts()
        .iter()
        .find(|start| start.borrower == "projected" && start.source == "source")
        .expect("the borrowed branch should expose an explicit projected -> source start edge");
    assert!(
        graph
            .borrow_state_before(branch_start.from)
            .is_some_and(|state| !state.contains("projected", "source")),
        "the branch-local borrow must be absent before its explicit start edge"
    );
    assert!(
        graph
            .borrow_state_before(branch_start.to)
            .is_some_and(|state| state.contains("projected", "source")),
        "the branch-local borrow must be live immediately after its explicit start edge"
    );
    let branch_end = graph
        .borrow_ends()
        .iter()
        .find(|end| end.borrower == "projected" && end.source == "source")
        .expect("the borrowed branch should expose an explicit projected -> source end edge");
    assert!(
        graph
            .borrow_state_before(branch_end.to)
            .is_some_and(|state| !state.contains("projected", "source")),
        "the branch-local borrow must be dead immediately after its explicit end edge"
    );
}

#[test]
fn sibling_borrow_lifetimes_keep_definition_identity() {
    let source = r#"
fn positive(value: i64) -> bool {
    return value > 0
}

fn main() -> i64 {
    let source: i64[] = [10, 20, 30, 40]
    if positive(1):
        let view: i64[] = source[1:]
        print(view[0])
    else:
        let view: i64[] = source[2:]
        print(view[0])
    return 0
}
"#;

    check_source(source).expect("sibling borrowed views should typecheck");
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1211))
        .expect("sibling borrowed-view lifetimes should analyze");
    let graph = database
        .control_flow_graph("main")
        .expect("main should expose a CFG");
    let lifetimes = graph
        .borrow_lifetimes()
        .iter()
        .filter(|lifetime| lifetime.borrower == "view" && lifetime.source == "source")
        .collect::<Vec<_>>();
    assert_eq!(
        lifetimes.len(),
        2,
        "same-named sibling bindings must retain two definition-scoped inferred lifetimes"
    );
    assert_ne!(
        lifetimes[0].definition, lifetimes[1].definition,
        "each inferred lifetime must retain the concrete borrower definition identity"
    );
    assert_ne!(
        lifetimes[0].origin, lifetimes[1].origin,
        "same-named sibling lifetimes must retain distinct source origins"
    );
    assert!(
        lifetimes.iter().all(|lifetime| {
            !lifetime.active_before.is_empty()
                && !lifetime.starts.is_empty()
                && !lifetime.ends.is_empty()
        }),
        "every sibling lifetime should expose its active CFG region and deterministic boundaries"
    );
    for lifetime in lifetimes {
        let active_node = lifetime.active_before[0];
        assert!(
            graph
                .borrow_lifetimes_before_source_definition(active_node, lifetime.source_definition,)
                .any(|candidate| candidate.definition == lifetime.definition),
            "the identity-based lifetime query must find only the matching source definition"
        );
        assert!(lifetime.starts.iter().all(|start| {
            start.definition == lifetime.definition
                && start.borrower == lifetime.borrower
                && start.source == lifetime.source
        }));
        assert!(lifetime.ends.iter().all(|end| {
            end.definition == lifetime.definition
                && end.borrower == lifetime.borrower
                && end.source == lifetime.source
        }));
    }
}

#[test]
fn ownership_ir_records_typed_call_boundaries() {
    let source = r#"
fn consume(values: i64[]) -> i64 {
    return values.count
}

fn main() -> i64 {
    let values: i64[] = [1, 2, 3]
    return consume(values)
}
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1417))
        .expect("call-boundary source should analyze");
    let graph = database
        .control_flow_graph("main")
        .expect("main should expose a CFG");
    let call = graph
        .nodes()
        .iter()
        .flat_map(|node| node.ownership.calls.iter().map(move |call| (node, call)))
        .find(|(_, call)| call.callee == "consume")
        .expect("typed call boundary should be attached to the evaluation node");
    assert_eq!(call.1.arguments.len(), 1);
    assert_eq!(
        call.1.argument_kinds,
        vec![OwnershipCallArgumentKind::ImmutableBorrow]
    );
    let argument = graph
        .value(call.1.arguments[0])
        .expect("call ownership fact should retain its typed argument value");
    assert!(
        matches!(argument.kind, ControlFlowValueKind::NameRead { ref name, .. } if name == "values")
    );
    assert_eq!(call.1.span.line, argument.span.line);
    assert!(call.1.span.column < argument.span.column);
    assert!(call.1.span.length > argument.span.length);
}

#[test]
fn ownership_ir_classifies_non_copy_set_and_map_calls_as_borrows() {
    let source = r#"
fn inspectSet(values: set<i64>) -> bool {
    return contains(values, 2)
}

fn inspectMap(values: map<str, i64>) -> bool {
    return contains(values, "answer")
}

fn main() -> i64 {
    if inspectSet({1, 2}) && inspectMap(map{"answer": 42}):
        return 0
    return 1
}
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1218))
        .expect("set and map call ownership facts should analyze");
    let main_graph = database
        .control_flow_graph("main")
        .expect("main should expose collection literal ownership");
    let owned_collections = main_graph
        .values()
        .iter()
        .filter(|value| {
            matches!(
                value.kind,
                ControlFlowValueKind::Set { .. } | ControlFlowValueKind::Map { .. }
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(owned_collections.len(), 2);
    assert!(
        owned_collections
            .iter()
            .all(|value| value.ownership == ControlFlowValueOwnership::Owned)
    );

    for (function, expected) in [
        ("inspectSet", Type::Set(Box::new(Type::I64))),
        (
            "inspectMap",
            Type::Map(Box::new(Type::Str), Box::new(Type::I64)),
        ),
    ] {
        let graph = database
            .control_flow_graph(function)
            .expect("collection function should expose a CFG");
        let call = graph
            .nodes()
            .iter()
            .flat_map(|node| node.ownership.calls.iter())
            .find(|call| call.callee == "contains")
            .expect("contains call should be recorded");
        assert_eq!(
            call.argument_kinds[0],
            OwnershipCallArgumentKind::ImmutableBorrow
        );
        assert_eq!(
            graph
                .value(call.arguments[0])
                .expect("collection argument value")
                .ty,
            expected
        );
        assert_eq!(call.borrowed_argument_definitions[0].len(), 1);
    }
}

