#[test]
fn sibling_move_states_keep_definition_identity() {
    let source = r#"
fn inspect(flag: bool) -> i64 {
    if flag:
        let source: i64[] = [10, 20]
        let destination: i64[] = source
        print(destination.first)
    else:
        let source: i64[] = [30, 40]
        print(source.first)
    return 0
}

fn main() -> i64 {
    return inspect(false)
}
"#;

    check_source(source).expect("sibling same-named ownership definitions should typecheck");
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1215))
        .expect("sibling move-state identities should analyze");
    let graph = database
        .control_flow_graph("inspect")
        .expect("inspect should expose ownership facts");
    let move_node = graph
        .nodes()
        .iter()
        .find(|node| {
            node.ownership
                .moves
                .iter()
                .any(|movement| movement.source == "source")
        })
        .expect("then branch should contain the ownership transfer");
    let moved_definition = *graph
        .definitions_reaching_before(move_node.id, "source")
        .expect("then source should reach the move")
        .iter()
        .next()
        .expect("then source should have one concrete definition");
    let then_read = graph
        .nodes()
        .iter()
        .find(|node| {
            node.ownership
                .borrows
                .iter()
                .any(|borrow| borrow.source == "destination" && borrow.span.line == 6)
        })
        .expect("then destination read should follow the ownership transfer");
    let then_state = graph
        .move_state_before(then_read.id)
        .expect("then read should expose move state");
    assert!(then_state.is_definition_moved(moved_definition));
    assert_eq!(
        then_state.origin_for_definition(moved_definition),
        Some(move_node.ownership.moves[0].span)
    );

    let else_read = graph
        .nodes()
        .iter()
        .find(|node| {
            node.ownership
                .borrows
                .iter()
                .any(|borrow| borrow.source == "source" && borrow.span.line == 9)
        })
        .expect("else source read should be represented as an immutable borrow");
    let else_definition = *graph
        .definitions_reaching_before(else_read.id, "source")
        .expect("else source should reach its read")
        .iter()
        .next()
        .expect("else source should have one concrete definition");
    assert_ne!(moved_definition, else_definition);
    let else_state = graph
        .move_state_before(else_read.id)
        .expect("else read should expose move state");
    assert!(
        !else_state.is_definition_moved(else_definition),
        "a move in the sibling branch must not mark the else definition as moved"
    );
}

#[test]
fn semantic_cfg_records_call_argument_definition_identity() {
    let source = r#"
fn inspect(values: i64[]) -> bool {
    return contains(values, 2)
}

fn main() -> i64 {
    if inspect([1, 2]):
        return 0
    return 1
}
"#;
    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::new(1216))
        .expect("call argument ownership facts should analyze");
    let graph = database
        .control_flow_graph("inspect")
        .expect("inspect should expose ownership facts");
    let call = graph
        .nodes()
        .iter()
        .flat_map(|node| node.ownership.calls.iter())
        .find(|call| call.callee == "contains")
        .expect("contains call should be recorded");
    assert_eq!(call.argument_definitions.len(), 2);
    assert_eq!(
        call.argument_kinds,
        vec![
            OwnershipCallArgumentKind::ImmutableBorrow,
            OwnershipCallArgumentKind::Copy
        ]
    );
    assert_eq!(call.argument_definitions[0].len(), 1);
    assert_eq!(call.borrowed_argument_definitions.len(), 2);
    assert_eq!(call.borrowed_argument_definitions[0].len(), 1);
    assert!(call.borrowed_argument_definitions[1].is_empty());
    assert!(matches!(
        call.argument_definitions[0][0],
        ControlFlowDefinitionId::Parameter(0)
    ));
    assert!(call.argument_definitions[1].is_empty());
    let (projection, definitions, value) = call
        .borrowed_argument_at(0)
        .expect("immutable-borrow argument view should preserve normalized facts");
    assert!(projection.is_empty());
    assert_eq!(
        definitions,
        call.borrowed_argument_definitions[0].as_slice()
    );
    assert_eq!(value, call.arguments.first().copied());
    assert!(call.borrowed_argument_at(1).is_none());
}

