    let compile = Command::new("clang")
        .args(["-std=c11", "-O2"])
        .arg(&c_path)
        .arg("-o")
        .arg(&exe_path)
        .output()
        .expect("clang should compile invalid JSON native code");
    assert!(
        compile.status.success(),
        "invalid JSON C should compile: {}",
        String::from_utf8_lossy(&compile.stderr)
    );
    let output = Command::new(&exe_path)
        .output()
        .expect("invalid JSON program should run");
