#[test]
fn crypto_sha256_uses_a_bounded_audited_native_digest() {
    let source = r#"
fn show(value: str) -> void {
    print(value)
}

fn main() -> i64 {
    let failure: error = crypto.sha256("abc", show)
    print(failure)
    let sha512_failure: error = crypto.sha512("abc", show)
    print(sha512_failure)
    let sha384_failure: error = crypto.sha384("abc", show)
    print(sha384_failure)
    let hmac_failure: error = crypto.hmacSha256("key", "The quick brown fox jumps over the lazy dog", show)
    print(hmac_failure)
    let hmac512_failure: error = crypto.hmacSha512("key", "The quick brown fox jumps over the lazy dog", show)
    print(hmac512_failure)
    return 0
}
"#;
    check_source(source).expect("crypto.sha256 should typecheck");
    let generated = compile_to_c(source).expect("crypto.sha256 should lower natively");
    assert!(generated.contains("#include <openssl/sha.h>"));
    assert!(generated.contains("flux__crypto_bounded_length"));
    assert!(generated.contains("if (!flux__crypto_bounded_length(value, &length))"));
    assert!(generated.contains("if (!flux__crypto_bounded_length(key, &key_length) || !flux__crypto_bounded_length(value, &value_length))"));
    assert!(generated.contains("SHA256((const unsigned char *)value"));
    assert!(generated.contains("crypto.sha256 input exceeds 65536 bytes"));
    assert!(generated.contains("flux__crypto_sha512("));
    assert!(generated.contains("crypto.sha512 input exceeds 65536 bytes"));
    assert!(generated.contains("flux__crypto_sha384("));
    assert!(generated.contains("flux__crypto_hmac_sha512("));
    assert!(generated.contains("flux__crypto_hmac_sha256("));
    assert!(generated.contains("HMAC-SHA-256"));

    let root = std::env::temp_dir().join(format!("flux-crypto-sha256-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("crypto fixture should be writable");
    let source_path = root.join("main.flux");
    fs::write(&source_path, source).expect("crypto source should be writable");
    let binary = root.join("crypto-sha256");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .args(["build", source_path.to_str().unwrap(), "-o"])
        .arg(&binary)
        .output()
        .expect("crypto binary should build");
    assert!(
        built.status.success(),
        "crypto build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("crypto binary should run");
    assert!(run.status.success());
    assert_eq!(
        String::from_utf8_lossy(&run.stdout),
        "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad\nnil\nddaf35a193617abacc417349ae20413112e6fa4e89a97ea20a9eeee64b55d39a2192992a274fc1a836ba3c23a3feebbd454d4423643ce80e2a9ac94fa54ca49f\nnil\ncb00753f45a35e8bb5a03d699ac65007272c32ab0eded1631a8b605a43ff5bed8086072ba1e7cc2358baeca134c825a7\nnil\nf7bc83f430538424b13298e6aa6fb143ef4d59a14946175997479dbc2d1a3cd8\nnil\nb42af09057bac1e2d41708e48a902e09b5ff7f12ab428a4fe86653c73dd248fb82f948a549f7b791a5b41915ee4d1ec3935357e4e2317250d0372afa2ebeeb3a\nnil\n"
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn tls_contract_wraps_verified_native_socket_handles() {
    let source = r#"
fn show(value: str) -> void {
    print(value)
}

fn main() -> i64 {
    let (socket, connect_error) = net.connect("example.com", 443)
    let (session, tls_error) = tls.wrap(socket, "example.com", "")
    let (server_session, server_error) = tls.listen(socket, "server.crt", "server.key")
    let write_error: error = tls.write(session, "GET / HTTP/1.1\r\nHost: example.com\r\nConnection: close\r\n\r\n")
    let (timed_written, timed_complete, timed_write_error) = tls.writeTimeout(session, "GET / HTTP/1.1\r\nHost: example.com\r\nConnection: close\r\n\r\n", 0)
    let (received, read_error) = tls.read(session, 1024, show)
    let (timed_received, timed_ready, timed_error) = tls.readTimeout(session, 1024, 0, show)
    let close_error: error = tls.close(session)
    let server_close_error: error = tls.close(server_session)
    print(connect_error)
    print(tls_error)
    print(write_error)
    print(timed_written)
    print(timed_complete)
    print(timed_write_error)
    print(received)
    print(read_error)
    print(timed_received)
    print(timed_ready)
    print(timed_error)
    print(close_error)
    print(server_error)
    print(server_close_error)
    return 0
}
"#;
    check_source(source).expect("TLS calls should typecheck");
    let generated = compile_to_c(source).expect("TLS calls should lower natively");
    assert!(generated.contains("#include <openssl/ssl.h>"));
    assert!(generated.contains("SSL_CTX_set_verify"));
    assert!(generated.contains("SSL_CTX_set_session_cache_mode(context, SSL_SESS_CACHE_CLIENT)"));
    assert!(generated.contains("SSL_set_session(session, resumption->session)"));
    assert!(generated.contains("SSL_get1_session(session)"));
    assert!(generated.contains("flux__tls_resumption_slots"));
    assert!(generated.contains("SSL_get_verify_result"));
    assert!(generated.contains("TLS wrap string exceeds 65536 bytes"));
    assert!(generated.contains("TLS server path exceeds 65536 bytes"));
    assert!(generated.contains("flux__tls_read("));
    assert!(generated.contains("flux__tls_read_timeout("));
    assert!(generated.contains("flux__tls_write_timeout("));
    assert!(generated.contains("flux__tls_cleanup_registered"));
    assert!(generated.contains("atexit(flux__tls_cleanup)"));
    assert!(generated.contains("SSL_free(slot->session); SSL_CTX_free(slot->context); flux__net_unregister_socket(slot->socket); close(slot->socket); slot->used = false"));
    assert!(generated.contains("SSL_pending(slot->session)"));
    assert!(generated.contains("flux__net_poll_cancellable(&descriptor, 1, wait_millis)"));
    assert!(generated.contains("SSL_ERROR_WANT_WRITE"));
    assert!(generated.contains("flux__tls_handshake"));
    assert!(generated.contains("flux__net_poll_cancellable(&descriptor, 1, -1)"));
    assert!(generated.contains("TLS requires a TCP stream socket"));
    assert!(generated.contains("TLS requires a connected TCP socket"));
    assert!(generated.contains("TLS readTimeout cancelled by worker scope"));
    assert!(generated.contains("TLS writeTimeout cancelled by worker scope"));
    assert!(
        generated.contains("TLS writeTimeout timeoutMillis must be -1 or between 0 and 2147483647")
    );
    assert!(
        generated.contains("TLS readTimeout timeoutMillis must be -1 or between 0 and 2147483647")
    );
    assert!(generated.contains("flux__tls_bounded_length(value, 65536"));
    assert!(generated.contains("TLS read contained NUL in text payload"));
    assert!(generated.contains("invalid or closed TLS session"));

    let root = std::env::temp_dir().join(format!("flux-tls-contract-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("TLS fixture should be writable");
    let source_path = root.join("main.flux");
    fs::write(&source_path, source).expect("TLS source should be writable");
    let binary = root.join("tls-contract");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .args(["build", source_path.to_str().unwrap(), "-o"])
        .arg(&binary)
        .output()
        .expect("TLS binary should build");
    assert!(
        built.status.success(),
        "TLS native link failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn tls_binary_io_is_typed_bounded_and_tree_shaken() {
    let source = r#"
fn consume(_bytes: i64[]) -> void {
}
fn main() -> i64 {
    let write_error: error = tls.writeBytes(1, [0, 128, 255])
    let (received, read_error) = tls.readBytes(1, 1024, consume)
    let (timed_written, timed_complete, timed_write_error) = tls.writeBytesTimeout(1, [0, 128, 255], 0)
    let (timed_received, timed_ready, timed_read_error) = tls.readBytesTimeout(1, 1024, 0, consume)
    print(write_error)
    print(received)
    print(read_error)
    print(timed_written)
    print(timed_complete)
    print(timed_write_error)
    print(timed_received)
    print(timed_ready)
    print(timed_read_error)
    return 0
}
"#;
    check_source(source).expect("TLS binary I/O should typecheck");
    let generated = compile_to_c(source).expect("TLS binary I/O should lower natively");
    assert!(generated.contains("flux__tls_write_bytes("));
    assert!(generated.contains("flux__tls_read_bytes("));
    assert!(generated.contains("flux__tls_write_bytes_timeout("));
    assert!(generated.contains("flux__tls_read_bytes_timeout("));
    assert!(generated.contains("TLS writeBytesTimeout cancelled by worker scope"));
    assert!(generated.contains("TLS readBytesTimeout cancelled by worker scope"));
    assert!(generated.contains("TLS writeBytes byte values must be between 0 and 255"));
    assert!(generated.contains("TLS writeBytes byte list has an invalid element stride"));
    assert!(generated.contains("invalid TLS readBytes arguments"));
    assert!(generated.contains("callback((struct flux__list)"));
    assert!(generated.contains("unsigned char buffer[4096]"));

    let invalid_byte = check_source(
        "fn main() -> i64 {\n    print(tls.writeBytes(1, [0, 256]))\n    return 0\n}\n",
    )
    .expect_err("TLS byte literals outside 0..255 should be rejected");
    assert!(
        invalid_byte
            .message
            .contains("tls.writeBytes byte values must be between 0 and 255")
    );

    let invalid_limit = check_source(
        "fn consume(_bytes: i64[]) -> void {\n}\nfn main() -> i64 {\n    let (_received, _failure) = tls.readBytes(1, 65537, consume)\n    return 0\n}\n",
    )
    .expect_err("TLS binary reads must remain bounded");
    assert!(
        invalid_limit
            .message
            .contains("tls.readBytes maxBytes must be between 1 and 65536")
    );

    let invalid_callback = check_source(
        "fn consume(_value: str) -> void {\n}\nfn main() -> i64 {\n    let (_received, _failure) = tls.readBytes(1, 64, consume)\n    return 0\n}\n",
    )
    .expect_err("TLS binary reads require a byte callback");
    assert!(invalid_callback.message.contains("tls.readBytes callback"));

    let invalid_read_timeout = check_source(
        "fn consume(_bytes: i64[]) -> void {
}
fn main() -> i64 {
    let (_received, _ready, _failure) = tls.readBytesTimeout(1, 64, 2147483648, consume)
    return 0
}
",
    )
    .expect_err("TLS timed binary reads must bound timeoutMillis");
    assert!(
        invalid_read_timeout
            .message
            .contains("tls.readBytesTimeout timeoutMillis must be -1 or between 0 and 2147483647")
    );

    let invalid_write_timeout = check_source(
        "fn main() -> i64 {
    let (_written, _complete, _failure) = tls.writeBytesTimeout(1, [0, 255], 2147483648)
    return 0
}
",
    )
    .expect_err("TLS timed binary writes must bound timeoutMillis");
    assert!(
        invalid_write_timeout
            .message
            .contains("tls.writeBytesTimeout timeoutMillis must be -1 or between 0 and 2147483647")
    );

    let unused = r#"
fn consume(_bytes: i64[]) -> void {
}
fn hidden(session: i64, bytes: i64[]) -> void {
    print(tls.writeBytes(session, bytes))
    let (received, failure) = tls.readBytes(session, 64, consume)
    let (timedWritten, timedComplete, timedWriteFailure) = tls.writeBytesTimeout(session, bytes, 10)
    let (timedReceived, timedReady, timedReadFailure) = tls.readBytesTimeout(session, 64, 10, consume)
    print(received)
    print(failure)
    print(timedWritten)
    print(timedComplete)
    print(timedWriteFailure)
    print(timedReceived)
    print(timedReady)
    print(timedReadFailure)
}
fn main() -> i64 {
    return 0
}
"#;
    let unused_generated = compile_to_c(unused).expect("dead TLS binary helpers should tree-shake");
    assert!(!unused_generated.contains("flux__tls_write_bytes("));
    assert!(!unused_generated.contains("flux__tls_read_bytes("));
    assert!(!unused_generated.contains("flux__tls_write_bytes_timeout("));
    assert!(!unused_generated.contains("flux__tls_read_bytes_timeout("));
}

#[test]
fn tls_rejects_non_tcp_socket_before_handshake() {
    let source = r#"
fn main() -> i64 {
    let (socket, bind_error) = net.udpBind("127.0.0.1", 0)
    print(bind_error)
    let (session, tls_error) = tls.wrap(socket, "example.com", "")
    print(session)
    print(tls_error)
    print(net.close(socket))
    return 0
}
"#;
    check_source(source).expect("TLS socket validation source should typecheck");
    let root =
        std::env::temp_dir().join(format!("flux-tls-socket-validation-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("TLS socket validation fixture should be writable");
    let source_path = root.join("main.flux");
    fs::write(&source_path, source).expect("TLS socket validation source should be writable");
    let binary = root.join("tls-socket-validation");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .args(["build", source_path.to_str().unwrap(), "-o"])
        .arg(&binary)
        .output()
        .expect("TLS socket validation binary should build");
    assert!(
        built.status.success(),
        "TLS socket validation build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("TLS socket validation binary should run");
    assert!(run.status.success());
    assert_eq!(
        String::from_utf8_lossy(&run.stdout),
        "nil\n-1\nTLS requires a TCP stream socket\nnil\n"
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn tls_verified_client_round_trips_against_local_openssl_server() {
    if Command::new("openssl").arg("version").output().is_err() {
        return;
    }
    let root = std::env::temp_dir().join(format!("flux-tls-e2e-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("TLS E2E fixture should be writable");
    let key = root.join("server.key");
    let certificate = root.join("server.crt");
    let generated = Command::new("openssl")
        .args([
            "req",
            "-x509",
            "-newkey",
            "rsa:2048",
            "-nodes",
            "-days",
            "1",
            "-subj",
            "/CN=127.0.0.1",
            "-keyout",
        ])
        .arg(&key)
        .args(["-out"])
        .arg(&certificate)
        .output()
        .expect("OpenSSL should generate the TLS fixture certificate");
    assert!(
        generated.status.success(),
        "certificate generation failed: {}",
        String::from_utf8_lossy(&generated.stderr)
    );

    let listener = TcpListener::bind(("127.0.0.1", 0)).expect("TLS fixture port should bind");
    let port = listener.local_addr().unwrap().port();
    drop(listener);
    let mut server = Command::new("openssl")
        .args(["s_server", "-quiet", "-www", "-accept"])
        .arg(port.to_string())
        .args(["-cert"])
        .arg(&certificate)
        .args(["-key"])
        .arg(&key)
        .spawn()
        .expect("OpenSSL TLS fixture server should start");
    for _ in 0..50 {
        if std::net::TcpStream::connect(("127.0.0.1", port)).is_ok() {
            break;
        }
        thread::sleep(Duration::from_millis(20));
    }

    let source = format!(
        r#"
fn show(value: str) -> void {{
    print(value)
}}

fn main() -> i64 {{
    let (socket, connect_error) = net.connect("127.0.0.1", {port})
    let nonblocking_error: error = net.nonblocking(socket, true)
    let (session, tls_error) = tls.wrap(socket, "127.0.0.1", "{}")
    let write_error: error = tls.write(session, "GET / HTTP/1.0\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n")
    let (received, ready, read_error) = tls.readTimeout(session, 4096, 5000, show)
    let close_error: error = tls.close(session)
    let (socket2, connect_error2) = net.connect("127.0.0.1", {port})
    let nonblocking_error2: error = net.nonblocking(socket2, true)
    let (session2, tls_error2) = tls.wrap(socket2, "127.0.0.1", "{}")
    let write_error2: error = tls.write(session2, "GET / HTTP/1.0\r\nHost: 127.0.0.1\r\nConnection: close\r\n\r\n")
    let (received2, ready2, read_error2) = tls.readTimeout(session2, 4096, 5000, show)
    let close_error2: error = tls.close(session2)
    print(connect_error)
    print(nonblocking_error)
    print(tls_error)
    print(write_error)
    print(received)
    print(ready)
    print(read_error)
    print(close_error)
    print(connect_error2)
    print(nonblocking_error2)
    print(tls_error2)
    print(write_error2)
    print(received2)
    print(ready2)
    print(read_error2)
    print(close_error2)
    return 0
}}
"#,
        certificate.display(),
        certificate.display()
    );
    let source_path = root.join("main.flux");
    fs::write(&source_path, source).expect("TLS E2E source should be writable");
    let binary = root.join("tls-e2e");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .args(["build", source_path.to_str().unwrap(), "-o"])
        .arg(&binary)
        .output()
        .expect("TLS E2E Flux binary should build");
    assert!(
        built.status.success(),
        "TLS E2E build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let run = Command::new(&binary)
        .output()
        .expect("TLS E2E Flux binary should run");
    let _ = server.kill();
    let _ = server.wait();
    assert!(
        run.status.success(),
        "TLS E2E run failed: {}",
        String::from_utf8_lossy(&run.stderr)
    );
    let stdout = String::from_utf8_lossy(&run.stdout);
    assert!(
        stdout.matches("HTTP/1.0 200").count() >= 2,
        "TLS responses missing: {stdout}"
    );
    assert!(
        stdout.contains("nil\n"),
        "TLS error result missing: {stdout}"
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn tls_binary_io_round_trips_arbitrary_bytes_against_openssl_client() {
    if Command::new("openssl").arg("version").output().is_err() {
        return;
    }
    let root = std::env::temp_dir().join(format!("flux-tls-binary-e2e-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("TLS binary fixture should be writable");
    let key = root.join("server.key");
    let certificate = root.join("server.crt");
    let generated = Command::new("openssl")
        .args([
            "req",
            "-x509",
            "-newkey",
            "rsa:2048",
            "-nodes",
            "-days",
            "1",
            "-subj",
            "/CN=127.0.0.1",
            "-keyout",
        ])
        .arg(&key)
        .args(["-out"])
        .arg(&certificate)
        .output()
        .expect("OpenSSL should generate the TLS binary certificate");
    assert!(
        generated.status.success(),
        "TLS binary certificate generation failed: {}",
        String::from_utf8_lossy(&generated.stderr)
    );

    let listener =
        TcpListener::bind(("127.0.0.1", 0)).expect("TLS binary fixture port should bind");
    let port = listener.local_addr().unwrap().port();
    drop(listener);
    let source = format!(
        r#"
fn handle(bytes: i64[]) -> void {{
    print(bytes.count)
    for index in 0..bytes.count:
        print(bytes[index])
}}

fn main() -> i64 {{
    let (listener, listen_error) = net.listen("127.0.0.1", {port}, 4)
    if listen_error != nil:
        return 1
    let (socket, accept_error) = net.accept(listener)
    if accept_error != nil:
        return 2
    let (session, tls_error) = tls.listen(socket, "{}", "{}")
    if tls_error != nil:
        return 3
    let (received, read_error) = tls.readBytes(session, 4, handle)
    if read_error != nil:
        return 4
    print(received)
    let (timed_received, timed_ready, timed_read_error) = tls.readBytesTimeout(session, 4, 5000, handle)
    if timed_read_error != nil:
        return 5
    if timed_ready == false:
        return 6
    print(timed_received)
    print(timed_ready)
    let values: i64[] = [0, 77, 128, 77, 255]
    let response: i64[] = values[::2]
    let write_error: error = tls.writeBytes(session, response)
    if write_error != nil:
        return 7
    let (timed_written, timed_complete, timed_write_error) = tls.writeBytesTimeout(session, [1, 254], 5000)
    if timed_write_error != nil:
        return 8
    if timed_complete == false:
        return 9
    print(timed_written)
    print(timed_complete)
    let close_error: error = tls.close(session)
    if close_error != nil:
        return 10
    print(net.close(listener))
    return 0
}}
"#,
        certificate.display(),
        key.display()
    );
    let source_path = root.join("main.flux");
    fs::write(&source_path, source).expect("TLS binary server source should be writable");
    let binary = root.join("tls-binary-e2e");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .args(["build", source_path.to_str().unwrap(), "-o"])
        .arg(&binary)
        .output()
        .expect("TLS binary Flux server should build");
    assert!(
        built.status.success(),
        "TLS binary Flux server build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );

    let flux = Command::new(&binary)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("TLS binary Flux server should start");
    thread::sleep(Duration::from_millis(80));
    let mut client = Command::new("openssl")
        .args(["s_client", "-quiet", "-connect"])
        .arg(format!("127.0.0.1:{port}"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("OpenSSL TLS binary client should start");
    client
        .stdin
        .take()
        .unwrap()
        .write_all(&[0, 127, 128, 255, 1, 2, 254, 255])
        .expect("TLS binary client payload should write");
    let client_output = client
        .wait_with_output()
        .expect("OpenSSL TLS binary client should finish");
    let server_output = flux
        .wait_with_output()
        .expect("TLS binary Flux server should finish");
    assert!(
        client_output.status.success(),
        "TLS binary client failed: {}",
        String::from_utf8_lossy(&client_output.stderr)
    );
    assert!(
        server_output.status.success(),
        "TLS binary server failed: stdout={:?} stderr={:?}",
        String::from_utf8_lossy(&server_output.stdout),
        String::from_utf8_lossy(&server_output.stderr)
    );
    assert_eq!(client_output.stdout, vec![0, 128, 255, 1, 254]);
    assert_eq!(
        String::from_utf8_lossy(&server_output.stdout),
        "4\n0\n127\n128\n255\n4\n4\n1\n2\n254\n255\n4\ntrue\n2\ntrue\nnil\n"
    );
    let _ = fs::remove_dir_all(&root);
}

