#[test]
fn accepts_closed_enums_with_typed_payloads_and_native_tags() {
    let source = r#"
enum Outcome {
    Ok(i64)
    Error(str, i64)
    Pending
}

fn pass(value: Outcome) -> Outcome {
    return value
}

fn main() -> i64 {
    let first: Outcome = Outcome.Ok(42)
    let _second: Outcome = Outcome.Error("nope", 7)
    let _third: Outcome = Outcome.Pending()
    let _carried: Outcome = pass(first)
    print(1)
    return 0
}
"#;

    check_source(source).expect("enum constructors should typecheck");
    let generated = compile_to_c(source).expect("enum constructors should lower natively");
    assert!(generated.contains("enum flux__tag_Outcome"));
    assert!(generated.contains("struct flux__type_Outcome"));
    assert!(generated.contains("union {"));
    assert!(generated.contains("flux__tag_Outcome_Ok"));
    assert!(generated.contains("flux__variant_Outcome_Ok(INT64_C(42))"));
    assert!(generated.contains("flux__variant_Outcome_Error(\"nope\", INT64_C(7))"));
    assert!(generated.contains("flux__variant_Outcome_Pending()"));
}

#[test]
fn supports_forward_dependencies_between_structs_and_enums() {
    let source = r#"
struct Envelope {
    outcome: Outcome
}

enum Outcome {
    Ok(User)
    Empty
}

struct User {
    name: str
}

fn main() -> i64 {
    let user: User = User { name: "Ada" }
    let outcome: Outcome = Outcome.Ok(user)
    let _envelope: Envelope = Envelope { outcome: outcome }
    print(1)
    return 0
}
"#;

    check_source(source).expect("cross value-type references should typecheck");
    let generated = compile_to_c(source).expect("cross value-type references should lower");
    let user = generated.find("struct flux__type_User {").unwrap();
    let outcome = generated.find("struct flux__type_Outcome {").unwrap();
    let envelope = generated.find("struct flux__type_Envelope {").unwrap();
    assert!(user < outcome && outcome < envelope);
}

#[test]
fn rejects_invalid_enum_construction_and_recursive_value_cycles() {
    let bad_variant = r#"
enum Outcome {
    Ok(i64)
}
fn main() -> i64 {
    let value: Outcome = Outcome.Nope(1)
    return 0
}
"#;
    let error = check_source(bad_variant).expect_err("unknown enum variant should fail");
    assert!(error.message.contains("has no variant 'Nope'"));

    let bad_arity = r#"
enum Outcome {
    Ok(i64)
}
fn main() -> i64 {
    let value: Outcome = Outcome.Ok()
    return 0
}
"#;
    let error = check_source(bad_arity).expect_err("wrong payload arity should fail");
    assert!(error.message.contains("expects 1 payload value, got 0"));

    let bad_type = r#"
enum Outcome {
    Ok(i64)
}
fn main() -> i64 {
    let value: Outcome = Outcome.Ok(false)
    return 0
}
"#;
    let error = check_source(bad_type).expect_err("wrong payload type should fail");
    assert!(error.message.contains("expected i64, got bool"));

    let cycle = r#"
struct Boxed {
    value: Loop
}

enum Loop {
    Again(Boxed)
}

fn main() -> i64 {
    return 0
}
"#;
    let error = compile_to_c(cycle).expect_err("enum/struct recursive value cycle should fail");
    assert_eq!(error.stage, DiagnosticStage::Codegen);
    assert!(error.message.contains("recursive by-value cycle"));
}

#[test]
fn formatter_and_semantic_database_preserve_enums() {
    let source = "enum Outcome {\n Ok(i64)\n Pending\n}\nfn main()->i64 {\n let _value:Outcome=Outcome.Ok(42)\n return 0\n}\n";
    let expected = "enum Outcome {\n    Ok(i64)\n    Pending\n}\nfn main() -> i64 {\n    let _value: Outcome = Outcome.Ok(42)\n    return 0\n}\n";
    let formatted = fluxc::formatter::format_source(source).expect("enum source should format");
    assert_eq!(formatted, expected);

    let database = fluxc::semantic::SemanticDatabase::analyze(&formatted, SourceId::new(601))
        .expect("enum source should analyze");
    let definition = database
        .symbols_named("Outcome")
        .find(|symbol| symbol.kind == fluxc::semantic::SymbolKind::Enum)
        .expect("enum should be indexed");
    assert_eq!(span_text(&formatted, definition.span), "Outcome");
    let variant = database
        .symbols_named("Ok")
        .find(|symbol| symbol.kind == fluxc::semantic::SymbolKind::EnumVariant)
        .expect("enum variant should be indexed");
    assert_eq!(
        variant.ty,
        Some(fluxc::ast::Type::Named("Outcome".to_string()))
    );
}

#[test]
fn tree_shakes_unreachable_private_functions_but_keeps_public_and_transitive_roots() {
    let source = r#"
interface Operation {
    fn apply(value: i64) -> i64
}

struct Offset {
    amount: i64
}

fn mappedApply(offset: Offset, value: i64) -> i64 {
    return offset.amount + value
}

impl Operation for Offset {
    apply: mappedApply
}

pub fn exported(value: i64) -> i64 {
    return value + 10
}

fn leaf(value: i64) -> i64 {
    return value + 1
}

fn helper(value: i64) -> i64 {
    return leaf(value)
}

fn unreachable(value: i64) -> i64 {
    return value + 1000
}

fn main() -> i64 {
    return helper(41)
}
"#;

    check_source(source).expect("tree-shaking fixture should typecheck");
    let generated = compile_to_c(source).expect("tree-shaking fixture should lower natively");
    assert!(
        generated.contains("static inline int64_t flux__fn_helper(int64_t flux__local_value);")
    );
    assert!(generated.contains("static inline int64_t flux__fn_leaf(int64_t flux__local_value);"));
    assert!(generated.contains("int64_t flux__fn_exported(int64_t flux__local_value);"));
    assert!(!generated.contains("static int64_t flux__fn_exported"));
    assert!(generated.contains("int main(void);"));
    assert!(!generated.contains("static int main(void)"));
    assert!(!generated.contains("flux__fn_mappedApply"));
    assert!(!generated.contains("flux__interface_Operation"));
    assert!(!generated.contains("flux__type_Offset"));
    assert!(!generated.contains("flux__fn_unreachable"));
}

#[test]
fn emits_c_header_for_public_scalar_abi_and_multi_returns() {
    let source = r#"
pub type CountAlias = Count
pub type Count = i64
pub const DEFAULT_COUNT: CountAlias = 3
pub const FEATURE_NAME: str = "flux ffi"
const HIDDEN_COUNT: i64 = 9

pub fn scale(value: CountAlias, enabled: bool, label: str) -> (CountAlias, error) {
    if enabled:
        return value * 2, nil
    return value, error(label)
}

fn hidden(value: i64) -> i64 {
    return value + 1
}

fn main() -> i64 {
    return hidden(0)
}
"#;

    let header = compile_to_c_header(source).expect("public scalar ABI should emit a C header");
    assert!(header.contains("#define FLUX_C_ABI_VERSION 1"));
    assert!(header.contains("#include <stdbool.h>"));
    assert!(header.contains("#include <stdint.h>"));
    let count_alias = header
        .find("typedef int64_t flux__alias_Count;")
        .expect("base alias should be emitted");
    let chained_alias = header
        .find("typedef flux__alias_Count flux__alias_CountAlias;")
        .expect("forward chained alias should preserve its public name");
    assert!(
        count_alias < chained_alias,
        "C typedef dependencies must be emitted before users"
    );
    assert!(
        header.contains("#define flux__const_DEFAULT_COUNT ((flux__alias_CountAlias)INT64_C(3))")
    );
    assert!(header.contains("#define flux__const_FEATURE_NAME ((const char *)\"flux ffi\")"));
    assert!(!header.contains("HIDDEN_COUNT"));
    assert!(header.contains("extern \"C\""));
    assert!(header.contains("struct flux__ret_scale"));
    assert!(header.contains("flux__alias_CountAlias v0;"));
    assert!(header.contains("const char * v1;"));
    assert!(header.contains(
        "struct flux__ret_scale flux__fn_scale(flux__alias_CountAlias flux__local_value, bool flux__local_enabled, const char * flux__local_label);"
    ));
    assert!(!header.contains("flux__fn_hidden"));
    assert!(!header.contains("main("));

    let root = std::env::temp_dir().join(format!("flux-c-header-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary C header directory should be writable");
    let header_path = root.join("flux_api.h");
    fs::write(&header_path, &header).expect("generated C header should be writable");
    let output = Command::new("clang")
        .args(["-std=c11", "-fsyntax-only"])
        .arg(&header_path)
        .output()
        .expect("clang should validate the generated C header");
    assert!(
        output.status.success(),
        "generated C header should compile: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn emits_c_header_for_public_primitive_optional_abi() {
    let source = r#"
pub type MaybeCount = i64?
pub type OptionalMapper = fn(i64?) -> bool?

pub struct OptionalScalars {
    count: i64?
    enabled: bool?
    label: str?
    failure: error?
}

pub fn passCount(value: MaybeCount) -> i64? {
    return value
}

pub fn passScalars(value: OptionalScalars) -> OptionalScalars {
    return value
}

pub fn chooseMapper(value: OptionalMapper) -> OptionalMapper {
    return value
}

fn main() -> i64 {
    return 0
}
"#;

    let header = compile_to_c_header(source)
        .expect("primitive Copy optionals should cross the C ABI by value");
    assert!(header.contains("struct flux__optional_i64 { bool has_value; int64_t value; };"));
    assert!(header.contains("struct flux__optional_bool { bool has_value; bool value; };"));
    assert!(header.contains("struct flux__optional_str { bool has_value; const char * value; };"));
    assert!(
        header.contains("struct flux__optional_error { bool has_value; const char * value; };")
    );
    assert!(header.contains("typedef struct flux__optional_i64 flux__alias_MaybeCount;"));
    assert!(header.contains(
        "typedef struct flux__optional_bool (*flux__fn_optional_i64__to__optional_bool)(struct flux__optional_i64);"
    ));
    assert!(
        header.contains(
            "typedef flux__fn_optional_i64__to__optional_bool flux__alias_OptionalMapper;"
        )
    );
    assert!(header.contains("struct flux__optional_i64 flux__field_count;"));
    assert!(header.contains("struct flux__optional_bool flux__field_enabled;"));
    assert!(header.contains("struct flux__optional_str flux__field_label;"));
    assert!(header.contains("struct flux__optional_error flux__field_failure;"));
    assert!(header.contains(
        "struct flux__optional_i64 flux__fn_passCount(flux__alias_MaybeCount flux__local_value);"
    ));
    assert!(header.contains(
        "flux__alias_OptionalMapper flux__fn_chooseMapper(flux__alias_OptionalMapper flux__local_value);"
    ));

    let root = std::env::temp_dir().join(format!("flux-c-optional-header-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary optional ABI directory should be writable");
    let header_path = root.join("flux_optional_api.h");
    let consumer_path = root.join("consumer.c");
    fs::write(&header_path, &header).expect("generated optional C header should be writable");
    fs::write(
        &consumer_path,
        "#include \"flux_optional_api.h\"\nstatic struct flux__optional_bool present(struct flux__optional_i64 value) { return (struct flux__optional_bool){ .has_value = true, .value = value.has_value }; }\nflux__alias_OptionalMapper probe(void) { struct flux__optional_i64 value = { .has_value = true, .value = 7 }; return flux__fn_chooseMapper(present) != 0 && flux__fn_passCount(value).value == 7 ? present : 0; }\n",
    )
    .expect("optional ABI C consumer should be writable");
    let output = Command::new("clang")
        .args(["-std=c11", "-fsyntax-only"])
        .arg(&consumer_path)
        .output()
        .expect("clang should validate the optional ABI consumer");
    assert!(
        output.status.success(),
        "generated optional ABI should compile: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn emits_c_header_for_public_copy_aggregate_optional_abi() {
    let source = r#"
pub struct Point {
    x: i64
}

pub enum Choice {
    Empty
    PointValue(Point)
}

pub struct Wrapper {
    point: Point?
    choice: Choice?
}

pub type MaybePoint = Point?
pub type OptionalMapper = fn(Point?) -> Choice?

pub fn pass(value: MaybePoint) -> Point? {
    return value
}

pub fn choose(value: OptionalMapper) -> OptionalMapper {
    return value
}

fn main() -> i64 {
    return 0
}
"#;

    let header = compile_to_c_header(source)
        .expect("Copy aggregate optionals should cross the C ABI by value");
    let point = header
        .find("struct flux__type_Point {")
        .expect("Point ABI layout should be emitted");
    let maybe_point = header
        .find(
            "struct flux__optional_named_Point { bool has_value; struct flux__type_Point value; };",
        )
        .expect("Point optional ABI wrapper should be emitted");
    let choice = header
        .find("struct flux__type_Choice {")
        .expect("Choice ABI layout should be emitted");
    let maybe_choice = header
        .find("struct flux__optional_named_Choice { bool has_value; struct flux__type_Choice value; };")
        .expect("Choice optional ABI wrapper should be emitted");
    let wrapper = header
        .find("struct flux__type_Wrapper {")
        .expect("Wrapper ABI layout should be emitted");
    assert!(point < maybe_point && maybe_point < choice);
    assert!(choice < maybe_choice && maybe_choice < wrapper);
    assert!(header.contains("struct flux__optional_named_Point flux__field_point;"));
    assert!(header.contains("struct flux__optional_named_Choice flux__field_choice;"));
    assert!(header.contains("typedef struct flux__optional_named_Point flux__alias_MaybePoint;"));
    assert!(header.contains(
        "typedef struct flux__optional_named_Choice (*flux__fn_optional_named_Point__to__optional_named_Choice)(struct flux__optional_named_Point);"
    ));
    assert!(header.contains(
        "typedef flux__fn_optional_named_Point__to__optional_named_Choice flux__alias_OptionalMapper;"
    ));
    assert!(header.contains(
        "struct flux__optional_named_Point flux__fn_pass(flux__alias_MaybePoint flux__local_value);"
    ));

    let root = std::env::temp_dir().join(format!(
        "flux-c-aggregate-optional-header-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root)
        .expect("temporary aggregate optional ABI directory should be writable");
    let header_path = root.join("flux_optional_aggregate_api.h");
    let consumer_path = root.join("consumer.c");
    fs::write(&header_path, &header)
        .expect("generated aggregate optional C header should be writable");
    fs::write(
        &consumer_path,
        "#include \"flux_optional_aggregate_api.h\"\nstatic struct flux__optional_named_Choice map_point(struct flux__optional_named_Point value) { (void)value; return (struct flux__optional_named_Choice){ .has_value = false }; }\nflux__alias_OptionalMapper probe(void) { struct flux__optional_named_Point value = { .has_value = true, .value = { .flux__field_x = 7 } }; return flux__fn_choose(map_point) != 0 && flux__fn_pass(value).value.flux__field_x == 7 ? map_point : 0; }\n",
    )
    .expect("aggregate optional ABI C consumer should be writable");
    let output = Command::new("clang")
        .args(["-std=c11", "-fsyntax-only"])
        .arg(&consumer_path)
        .output()
        .expect("clang should validate the aggregate optional ABI consumer");
    assert!(
        output.status.success(),
        "generated aggregate optional ABI should compile: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn emits_c_header_for_public_copy_struct_abi() {
    let source = r#"
pub struct Point {
    x: i64
    y: i64
}

pub struct Segment {
    start: Point
    end: Point
}

pub type PublicSegment = Segment

pub fn shift(segment: PublicSegment, delta: i64) -> Segment {
    return Segment { start: Point { x: segment.start.x + delta, y: segment.start.y }, end: Point { x: segment.end.x + delta, y: segment.end.y } }
}

fn main() -> i64 {
    return 0
}
"#;

    let header =
        compile_to_c_header(source).expect("public Copy structs should cross the C ABI by value");
    let point = header
        .find("struct flux__type_Point {")
        .expect("Point layout should be emitted");
    let segment = header
        .find("struct flux__type_Segment {")
        .expect("Segment layout should be emitted");
    assert!(
        point < segment,
        "nested struct dependencies must be emitted first"
    );
    assert!(header.contains("int64_t flux__field_x;"));
    assert!(header.contains("struct flux__type_Point flux__field_start;"));
    assert!(header.contains("typedef struct flux__type_Segment flux__alias_PublicSegment;"));
    assert!(header.contains(
        "struct flux__type_Segment flux__fn_shift(flux__alias_PublicSegment flux__local_segment, int64_t flux__local_delta);"
    ));

    let root = std::env::temp_dir().join(format!("flux-c-struct-header-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary C struct header directory should be writable");
    let header_path = root.join("flux_struct_api.h");
    fs::write(&header_path, &header).expect("generated struct header should be writable");
    let output = Command::new("clang")
        .args(["-std=c11", "-fsyntax-only"])
        .arg(&header_path)
        .output()
        .expect("clang should validate the generated struct C header");
    assert!(
        output.status.success(),
        "generated struct C header should compile: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn package_c_abi_exports_use_module_qualified_linker_symbols() {
    let root =
        std::env::temp_dir().join(format!("flux-module-qualified-abi-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary ABI package directory should be writable");
    fs::write(
        root.join("flux.toml"),
        "[package]\nname = \"abi_sample\"\nentry = \"main.flux\"\nversion = \"1.0.0\"\n",
    )
    .expect("ABI package manifest should be writable");
    fs::write(
        root.join("main.flux"),
        r#"pub struct Point {
    value: i64
}

pub enum Choice {
    Off
    On
}

pub type Mapper = fn(i64) -> i64
pub type PointMapper = fn(Point) -> Point
pub type MaybePoint = Point?
pub type OptionalPointMapper = fn(Point?) -> Point?

pub struct Holder {
    point: Point?
}

pub fn scale(value: i64) -> i64 {
    return value * 2
}

pub fn identity(point: Point) -> Point {
    return point
}

pub fn roundtrip(choice: Choice) -> Choice {
    return choice
}

pub fn passThrough(mapper: Mapper) -> Mapper {
    return mapper
}

pub fn passPoint(mapper: PointMapper) -> PointMapper {
    return mapper
}

pub fn maybeIdentity(point: MaybePoint) -> Point? {
    return point
}

pub fn passOptionalPoint(mapper: OptionalPointMapper) -> OptionalPointMapper {
    return mapper
}

fn main() -> i64 {
    return scale(2)
}
"#,
    )
    .expect("ABI package source should be writable");

    let header = fluxc::project::compile_to_c_header(&root)
        .expect("package C header should use stable module-qualified exports");
    let generated = fluxc::project::compile_to_c(&root)
        .expect("package C source should use stable module-qualified exports");
    let module_component = "abi_sample::main"
        .as_bytes()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    let symbol = format!("flux__abi_{module_component}__fn_scale");
    let identity_symbol = format!("flux__abi_{module_component}__fn_identity");
    let roundtrip_symbol = format!("flux__abi_{module_component}__fn_roundtrip");
    let callback_symbol = format!("flux__abi_{module_component}__fn_passThrough");
    let point_callback_symbol = format!("flux__abi_{module_component}__fn_passPoint");
    let optional_identity_symbol = format!("flux__abi_{module_component}__fn_maybeIdentity");
    let optional_callback_symbol = format!("flux__abi_{module_component}__fn_passOptionalPoint");
    let point_type = format!("flux__abi_{module_component}__type_Point");
    let optional_point_type = format!("{point_type}__optional");
    let holder_type = format!("flux__abi_{module_component}__type_Holder");
    let choice_type = format!("flux__abi_{module_component}__type_Choice");
    let choice_tag = format!("flux__abi_{module_component}__tag_Choice");

    assert!(header.contains("#define FLUX_C_ABI_VERSION 2"));
    assert!(header.contains(&format!("struct {point_type} {{")));
    assert!(header.contains(&format!(
        "struct {optional_point_type} {{ bool has_value; struct {point_type} value; }};"
    )));
    assert!(header.contains(&format!("struct {optional_point_type} flux__field_point;")));
    assert!(header.contains(&format!("struct {holder_type} {{")));
    assert!(header.contains(&format!("typedef int32_t {choice_tag};")));
    assert!(header.contains(&format!(
        "#define {choice_tag}_Off (({choice_tag})INT32_C(0))"
    )));
    assert!(header.contains(&format!("struct {choice_type} {{")));
    assert!(header.contains(&format!("int64_t {symbol}(int64_t flux__local_value);")));
    assert!(header.contains(&format!(
        "struct {point_type} {identity_symbol}(struct {point_type} flux__local_point);"
    )));
    assert!(header.contains(&format!(
        "struct {choice_type} {roundtrip_symbol}(struct {choice_type} flux__local_choice);"
    )));
    assert!(header.contains("typedef int64_t (*flux__fn_i64__to__i64)(int64_t);"));
    assert!(header.contains("typedef flux__fn_i64__to__i64 flux__alias_Mapper;"));
    assert!(header.contains(&format!(
        "typedef struct {point_type} (*flux__fn_named_Point__to__named_Point)(struct {point_type});"
    )));
    assert!(
        header.contains("typedef flux__fn_named_Point__to__named_Point flux__alias_PointMapper;")
    );
    assert!(header.contains(&format!(
        "typedef struct {optional_point_type} flux__alias_MaybePoint;"
    )));
    assert!(header.contains(&format!(
        "typedef struct {optional_point_type} (*flux__fn_optional_named_Point__to__optional_named_Point)(struct {optional_point_type});"
    )));
    assert!(header.contains(
        "typedef flux__fn_optional_named_Point__to__optional_named_Point flux__alias_OptionalPointMapper;"
    ));
    assert!(header.contains(&format!(
        "flux__alias_Mapper {callback_symbol}(flux__alias_Mapper flux__local_mapper);"
    )));
    assert!(header.contains(&format!(
        "flux__alias_PointMapper {point_callback_symbol}(flux__alias_PointMapper flux__local_mapper);"
    )));
    assert!(header.contains(&format!(
        "struct {optional_point_type} {optional_identity_symbol}(flux__alias_MaybePoint flux__local_point);"
    )));
    assert!(header.contains(&format!(
        "flux__alias_OptionalPointMapper {optional_callback_symbol}(flux__alias_OptionalPointMapper flux__local_mapper);"
    )));
    assert!(generated.contains(&format!("__asm__(\"{symbol}\")")));
    assert!(generated.contains(&format!("__asm__(\"{identity_symbol}\")")));
    assert!(generated.contains(&format!("__asm__(\"{roundtrip_symbol}\")")));
    assert!(generated.contains(&format!("__asm__(\"{callback_symbol}\")")));
    assert!(generated.contains(&format!("__asm__(\"{point_callback_symbol}\")")));
    assert!(generated.contains(&format!("__asm__(\"{optional_identity_symbol}\")")));
    assert!(generated.contains(&format!("__asm__(\"{optional_callback_symbol}\")")));

    let header_path = root.join("package.h");
    let consumer_path = root.join("consumer.c");
    let consumer_object = root.join("consumer.o");
    let cpp_consumer_path = root.join("consumer.cpp");
    fs::write(&header_path, &header).expect("package ABI header should be writable");
    fs::write(
        &consumer_path,
        format!(
            "#include \"package.h\"\nint64_t probe(void) {{ struct {point_type} point = {{ .flux__field_value = 7 }}; struct {optional_point_type} maybe = {{ .has_value = true, .value = point }}; return {identity_symbol}(point).flux__field_value + {optional_identity_symbol}(maybe).value.flux__field_value; }}\n"
        ),
    )
    .expect("package ABI C consumer should be writable");
    let consumer_compile = Command::new("clang")
        .args(["-std=c11", "-c"])
        .arg(&consumer_path)
        .arg("-o")
        .arg(&consumer_object)
        .output()
        .expect("clang should compile a consumer of the package ABI header");
    assert!(
        consumer_compile.status.success(),
        "package ABI header consumer should compile: {}",
        String::from_utf8_lossy(&consumer_compile.stderr)
    );
    fs::write(
        &cpp_consumer_path,
        format!(
            "#include \"package.h\"\nint64_t probe_cpp(struct {point_type} point) {{ return {identity_symbol}(point).flux__field_value; }}\n"
        ),
    )
    .expect("package ABI C++ consumer should be writable");
    let cpp_consumer_compile = Command::new("clang++")
        .args(["-std=c++17", "-fsyntax-only"])
        .arg(&cpp_consumer_path)
        .output()
        .expect("clang++ should compile a consumer of the package ABI header");
    assert!(
        cpp_consumer_compile.status.success(),
        "package ABI header should be C++17 compatible: {}",
        String::from_utf8_lossy(&cpp_consumer_compile.stderr)
    );

    let c_path = root.join("package.c");
    let object_path = root.join("package.o");
    fs::write(&c_path, generated).expect("generated package C should be writable");
    let compile = Command::new("clang")
        .args(["-std=c11", "-c"])
        .arg(&c_path)
        .arg("-o")
        .arg(&object_path)
        .output()
        .expect("clang should compile the package C output");
    assert!(
        compile.status.success(),
        "package C should compile: {}",
        String::from_utf8_lossy(&compile.stderr)
    );
    let symbols = Command::new("nm")
        .args(["-g", "--defined-only"])
        .arg(&object_path)
        .output()
        .expect("nm should inspect package ABI symbols");
    assert!(symbols.status.success());
    let symbols = String::from_utf8_lossy(&symbols.stdout);
    assert!(
        symbols.contains(&symbol),
        "qualified ABI symbol should be exported"
    );
    assert!(
        symbols.contains(&identity_symbol),
        "qualified aggregate ABI symbol should be exported"
    );
    assert!(
        symbols.contains(&roundtrip_symbol),
        "qualified enum ABI symbol should be exported"
    );
    assert!(
        symbols.contains(&callback_symbol),
        "qualified callback ABI symbol should be exported"
    );
    assert!(
        symbols.contains(&point_callback_symbol),
        "qualified aggregate callback ABI symbol should be exported"
    );
    assert!(
        symbols.contains(&optional_identity_symbol),
        "qualified aggregate optional ABI symbol should be exported"
    );
    assert!(
        symbols.contains(&optional_callback_symbol),
        "qualified aggregate optional callback ABI symbol should be exported"
    );
    assert!(
        !symbols.contains("flux__fn_scale"),
        "the legacy unqualified linker symbol must not leak from package builds"
    );

    let _ = fs::remove_dir_all(&root);
}

#[test]
fn native_c_can_invoke_flux_with_copy_callback() {
    let root = std::env::temp_dir().join(format!("flux-c-callback-runtime-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary C callback runtime directory should be writable");
    fs::write(
        root.join("flux.toml"),
        "[package]\nname = \"callback_runtime\"\nentry = \"main.flux\"\nversion = \"0.1.0\"\n",
    )
    .expect("callback runtime manifest should be writable");
    fs::write(
        root.join("main.flux"),
        r#"pub type Mapper = fn(i64) -> i64
pub type MapperFactory = fn(Mapper) -> Mapper

pub fn invoke(callback: Mapper, value: i64) -> i64 {
    return callback(value)
}

pub fn invokeFactory(factory: MapperFactory, callback: Mapper, value: i64) -> i64 {
    let mapped: Mapper = factory(callback)
    return mapped(value)
}

fn main() -> i64 {
    return 0
}
"#,
    )
    .expect("callback runtime source should be writable");

    let header = fluxc::project::compile_to_c_header(&root)
        .expect("package callback ABI should emit a C header");
    let generated =
        fluxc::project::compile_to_c(&root).expect("package callback ABI should emit C source");
    let module_component = "callback_runtime::main"
        .as_bytes()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    let invoke_symbol = format!("flux__abi_{module_component}__fn_invoke");
    let invoke_factory_symbol = format!("flux__abi_{module_component}__fn_invokeFactory");
    assert!(header.contains(&format!(
        "int64_t {invoke_symbol}(flux__alias_Mapper flux__local_callback, int64_t flux__local_value);"
    )));
    assert!(header.contains(&format!(
        "int64_t {invoke_factory_symbol}(flux__alias_MapperFactory flux__local_factory, flux__alias_Mapper flux__local_callback, int64_t flux__local_value);"
    )));

    let header_path = root.join("package.h");
    let generated_path = root.join("package.c");
    let object_path = root.join("package.o");
    let consumer_path = root.join("consumer.c");
    let executable_path = root.join("consumer");
    fs::write(&header_path, &header).expect("callback runtime header should be writable");
    fs::write(&generated_path, generated).expect("callback runtime C output should be writable");
    fs::write(
        &consumer_path,
        format!(
            "#include \"package.h\"\nstatic int64_t plus_one(int64_t value) {{ return value + 1; }}\nstatic flux__alias_Mapper identity_mapper(flux__alias_Mapper callback) {{ return callback; }}\nint main(void) {{ return {invoke_symbol}(plus_one, 41) == 42 && {invoke_factory_symbol}(identity_mapper, plus_one, 41) == 42 ? 0 : 1; }}\n"
        ),
    )
    .expect("callback runtime C consumer should be writable");

    let compile = Command::new("clang")
        .args(["-std=c11", "-Dmain=flux__embedded_main", "-c"])
        .arg(&generated_path)
        .arg("-o")
        .arg(&object_path)
        .output()
        .expect("clang should compile generated callback runtime C");
    assert!(
        compile.status.success(),
        "generated callback runtime C should compile: {}",
        String::from_utf8_lossy(&compile.stderr)
    );

    let link = Command::new("clang")
        .args(["-std=c11"])
        .arg(&consumer_path)
        .arg(&object_path)
        .arg("-o")
        .arg(&executable_path)
        .output()
        .expect("clang should link the native callback consumer");
    assert!(
        link.status.success(),
        "native callback consumer should link: {}",
        String::from_utf8_lossy(&link.stderr)
    );

    let run = Command::new(&executable_path)
        .output()
        .expect("native callback consumer should run");
    assert!(
        run.status.success(),
        "C -> Flux -> nested C callback invocation should return the expected value"
    );

    let _ = fs::remove_dir_all(&root);
}

#[test]
fn stable_package_c_ffi_executes_supported_copy_boundary_end_to_end() {
    let root = std::env::temp_dir().join(format!("flux-stable-c-ffi-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary stable C FFI directory should be writable");
    fs::write(
        root.join("flux.toml"),
        "[package]\nname = \"stable_ffi\"\nentry = \"main.flux\"\nversion = \"1.0.0\"\n",
    )
    .expect("stable C FFI manifest should be writable");
    fs::write(
        root.join("main.flux"),
        r#"pub struct Point {
    value: i64
}

pub enum Flag {
    Off
    On
}

pub interface Tool {
    fn apply(value: i64) -> i64
}

pub struct Offset {
    value: i64
}

fn pointApply(receiver: Point, value: i64) -> i64 {
    return receiver.value + value
}

fn offsetApply(receiver: Offset, value: i64) -> i64 {
    return receiver.value + value
}

impl Tool for Point {
    apply: pointApply
}

impl Tool for Offset {
    apply: offsetApply
}

pub type Mapper = fn(i64) -> i64

pub fn addOne(value: i64) -> i64 {
    return value + 1
}

pub fn passOptional(value: i64?) -> i64? {
    return value
}

pub fn passPoint(value: Point) -> Point {
    return value
}

pub fn passFlag(value: Flag) -> Flag {
    return value
}

pub fn invoke(mapper: Mapper, value: i64) -> i64 {
    return mapper(value)
}

pub fn passText(value: str) -> str {
    return value
}

pub fn applyTool(tool: Tool, value: i64) -> i64 {
    return Tool.apply(tool, value)
}

pub fn passTool(tool: Tool?) -> Tool? {
    return tool
}

fn main() -> i64 {
    return 0
}
"#,
    )
    .expect("stable C FFI source should be writable");

    let header = fluxc::project::compile_to_c_header(&root)
        .expect("stable package C FFI should emit a header");
    let generated =
        fluxc::project::compile_to_c(&root).expect("stable package C FFI should emit C source");
    assert!(header.contains("#define FLUX_C_ABI_VERSION 2"));

    let module_component = "stable_ffi::main"
        .as_bytes()
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    let point_type = format!("flux__abi_{module_component}__type_Point");
    let offset_type = format!("flux__abi_{module_component}__type_Offset");
    let flag_type = format!("flux__abi_{module_component}__type_Flag");
    let flag_tag = format!("flux__abi_{module_component}__tag_Flag");
    let tool_type = format!("flux__abi_{module_component}__interface_Tool");
    let tool_optional_type = format!("{tool_type}__optional");
    let tool_point_tag = format!("flux__abi_{module_component}__interface_tag_Tool_Point");
    let add_one = format!("flux__abi_{module_component}__fn_addOne");
    let pass_optional = format!("flux__abi_{module_component}__fn_passOptional");
    let pass_point = format!("flux__abi_{module_component}__fn_passPoint");
    let pass_flag = format!("flux__abi_{module_component}__fn_passFlag");
    let invoke = format!("flux__abi_{module_component}__fn_invoke");
    let pass_text = format!("flux__abi_{module_component}__fn_passText");
    let apply_tool = format!("flux__abi_{module_component}__fn_applyTool");
    let pass_tool = format!("flux__abi_{module_component}__fn_passTool");

    let header_path = root.join("package.h");
    let generated_path = root.join("package.c");
    let object_path = root.join("package.o");
    let consumer_path = root.join("consumer.c");
    let executable_path = root.join("consumer");
    fs::write(&header_path, &header).expect("stable C FFI header should be writable");
    fs::write(&generated_path, generated).expect("stable C FFI output should be writable");
    fs::write(
        &consumer_path,
        format!(
            "#include \"package.h\"\n#include <string.h>\nstatic int64_t double_value(int64_t value) {{ return value * 2; }}\nint main(void) {{\n    struct flux__optional_i64 maybe = {{ .has_value = true, .value = 9 }};\n    struct {point_type} point = {{ .flux__field_value = 11 }};\n    struct {offset_type} offset = {{ .flux__field_value = 5 }};\n    struct {flag_type} flag = {{ .tag = {flag_tag}_On }};\n    struct {tool_type} tool = {{0}};\n    tool.tag = {tool_point_tag};\n    tool.value.flux__value_Point = point;\n    if ({add_one}(41) != 42) return 1;\n    struct flux__optional_i64 optional_result = {pass_optional}(maybe);\n    if (!optional_result.has_value || optional_result.value != 9) return 2;\n    if ({pass_point}(point).flux__field_value != 11) return 3;\n    if ({pass_flag}(flag).tag != {flag_tag}_On) return 4;\n    if ({invoke}(double_value, 21) != 42) return 5;\n    if (strcmp({pass_text}(\"flux\"), \"flux\") != 0) return 6;\n    if ({apply_tool}(tool, 31) != 42) return 7;\n    struct {tool_optional_type} optional_tool = {{ .has_value = true, .value = tool }};\n    struct {tool_optional_type} optional_tool_result = {pass_tool}(optional_tool);\n    if (!optional_tool_result.has_value || {apply_tool}(optional_tool_result.value, 31) != 42) return 8;\n    if (offset.flux__field_value != 5) return 9;\n    return 0;\n}}\n"
        ),
    )
    .expect("stable C FFI consumer should be writable");

    let compile = Command::new("clang")
        .args(["-std=c11", "-Dmain=flux__embedded_main", "-c"])
        .arg(&generated_path)
        .arg("-o")
        .arg(&object_path)
        .output()
        .expect("clang should compile stable Flux C output");
    assert!(
        compile.status.success(),
        "stable Flux C output should compile: {}",
        String::from_utf8_lossy(&compile.stderr)
    );

    let link = Command::new("clang")
        .args(["-std=c11"])
        .arg(&consumer_path)
        .arg(&object_path)
        .arg("-o")
        .arg(&executable_path)
        .output()
        .expect("clang should link the stable C FFI consumer");
    assert!(
        link.status.success(),
        "stable C FFI consumer should link: {}",
        String::from_utf8_lossy(&link.stderr)
    );

    let run = Command::new(&executable_path)
        .output()
        .expect("stable C FFI consumer should execute");
    assert!(
        run.status.success(),
        "stable C FFI consumer should round-trip every supported boundary category"
    );

    let _ = fs::remove_dir_all(&root);
}

#[test]
fn emits_c_header_for_public_copy_enum_abi() {
    let source = r#"
pub struct Point {
    x: i64
}

pub enum Choice {
    Empty
    PointValue(Point)
    Pair(i64, bool)
}

pub type PublicChoice = Choice

pub fn choose(value: PublicChoice) -> Choice {
    return value
}

fn main() -> i64 {
    return 0
}
"#;

    let header =
        compile_to_c_header(source).expect("public Copy enums should cross the C ABI by value");
    let generated = compile_to_c(source).expect("public Copy enums should lower with stable tags");
    let point = header
        .find("struct flux__type_Point {")
        .expect("payload struct layout should be emitted");
    let choice = header
        .find("struct flux__type_Choice {")
        .expect("enum layout should be emitted");
    assert!(
        point < choice,
        "enum payload dependencies must be emitted first"
    );
    assert!(header.contains("typedef int32_t flux__tag_Choice;"));
    assert!(header.contains("#define flux__tag_Choice_Empty ((flux__tag_Choice)INT32_C(0))"));
    assert!(header.contains("#define flux__tag_Choice_PointValue ((flux__tag_Choice)INT32_C(1))"));
    assert!(header.contains("#define flux__tag_Choice_Pair ((flux__tag_Choice)INT32_C(2))"));
    assert!(header.contains("flux__tag_Choice tag;"));
    assert!(header.contains("struct flux__type_Point v0;"));
    assert!(header.contains("int64_t v0;"));
    assert!(header.contains("bool v1;"));
    assert!(header.contains("typedef struct flux__type_Choice flux__alias_PublicChoice;"));
    assert!(header.contains(
        "struct flux__type_Choice flux__fn_choose(flux__alias_PublicChoice flux__local_value);"
    ));
    assert!(generated.contains("struct flux__type_Choice {\n    int32_t tag;"));

    let root = std::env::temp_dir().join(format!("flux-c-enum-header-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary C enum header directory should be writable");
    let header_path = root.join("flux_enum_api.h");
    let consumer_path = root.join("consumer.c");
    fs::write(&header_path, &header).expect("generated enum header should be writable");
    fs::write(
        &consumer_path,
        "#include \"flux_enum_api.h\"\nstruct flux__type_Choice probe(void) { struct flux__type_Choice value = { .tag = flux__tag_Choice_Pair, .payload.flux__payload_Pair = { .v0 = 7, .v1 = true } }; return value; }\n",
    )
    .expect("enum header consumer should be writable");
    let output = Command::new("clang")
        .args(["-std=c11", "-fsyntax-only"])
        .arg(&consumer_path)
        .output()
        .expect("clang should validate the generated enum C header");
    assert!(
        output.status.success(),
        "generated enum C header should compile: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    let _ = fs::remove_dir_all(&root);
}

