#[test]
fn eliminates_dead_immutable_bindings_without_dropping_rhs_effects() {
    let source = r#"
fn observe(value: i64) -> i64 {
    print(value)
    return value
}

fn main() -> i64 {
    let source: i64 = 7
    let deadCopy: i64 = source
    if false:
        print(deadCopy)
    let deadConstant: i64 = 10 + 20
    if false:
        print(deadConstant)
    let observed: i64 = observe(4)
    if false:
        print(observed)
    let dynamic: i64 = time.unixMillis()
    let deadAddLeft: i64 = 0 + dynamic
    if false:
        print(deadAddLeft)
    let deadAddRight: i64 = dynamic + 0
    if false:
        print(deadAddRight)
    let deadSubtract: i64 = dynamic - 0
    if false:
        print(deadSubtract)
    let deadSelfSubtract: i64 = dynamic - dynamic
    if false:
        print(deadSelfSubtract)
    let deadZeroProduct: i64 = dynamic * 0
    if false:
        print(deadZeroProduct)
    let deadMultiplyLeft: i64 = 1 * dynamic
    if false:
        print(deadMultiplyLeft)
    let deadMultiplyRight: i64 = dynamic * 1
    if false:
        print(deadMultiplyRight)
    let deadDivide: i64 = dynamic / 1
    if false:
        print(deadDivide)
    let deadSafeDivide: i64 = dynamic / 2
    if false:
        print(deadSafeDivide)
    let effectfulZeroProduct: i64 = observe(5) * 0
    if false:
        print(effectfulZeroProduct)
    let trappingNegation: i64 = 0 - dynamic
    if false:
        print(trappingNegation)
    let checked: i64 = dynamic + 1
    if false:
        print(checked)
    return source
}
"#;

    check_source(source).expect("dead immutable bindings should typecheck");
    let generated = compile_to_c(source).expect("dead immutable bindings should optimize safely");
    assert!(!generated.contains("flux__local_deadCopy"));
    assert!(!generated.contains("flux__local_deadConstant"));
    assert!(!generated.contains("flux__local_deadAddLeft"));
    assert!(!generated.contains("flux__local_deadAddRight"));
    assert!(!generated.contains("flux__local_deadSubtract"));
    assert!(!generated.contains("flux__local_deadSelfSubtract"));
    assert!(!generated.contains("flux__local_deadZeroProduct"));
    assert!(!generated.contains("flux__local_deadMultiplyLeft"));
    assert!(!generated.contains("flux__local_deadMultiplyRight"));
    assert!(!generated.contains("flux__local_deadDivide"));
    assert!(!generated.contains("flux__local_deadSafeDivide"));
    assert!(!generated.contains("flux__local_observed"));
    assert!(generated.contains("(void)(flux__fn_observe(INT64_C(4)));"));
    assert!(!generated.contains("flux__local_effectfulZeroProduct"));
    assert!(generated.contains("flux__fn_observe(INT64_C(5))"));
    assert!(!generated.contains("flux__local_trappingNegation"));
    assert!(generated.contains("(void)(flux_neg_i64(flux__local_dynamic));"));
    assert!(!generated.contains("flux__local_checked"));
    assert!(generated.contains("(void)(flux_add_i64(flux__local_dynamic, INT64_C(1)));"));

    let aggregates = r#"
struct Pair {
    left: i64
    right: i64
}

fn observe(value: i64) -> i64 {
    print(value)
    return value
}

fn main() -> i64 {
    let seed: Pair = Pair { left: 1, right: 2 }
    let deadLiteral: Pair = Pair { left: 10, right: 20 }
    if false:
        print(deadLiteral.left)
    let deadUpdate: Pair = Pair { ..seed, right: 3 }
    if false:
        print(deadUpdate.right)
    let deadField: i64 = Pair { left: 30, right: 40 }.left
    if false:
        print(deadField)
    let deadIndex: i64 = [6, 7][1]
    if false:
        print(deadIndex)
    let deadLength: i64 = [1, 2, 3].length
    if false:
        print(deadLength)
    let dynamicIndex: i64 = time.unixMillis()
    let checkedIndex: i64 = [6, 7][dynamicIndex]
    if false:
        print(checkedIndex)
    let checkedNegation: i64 = -dynamicIndex
    if false:
        print(checkedNegation)
    let observed: Pair = Pair { left: observe(4), right: 5 }
    if false:
        print(observed.left)
    return seed.left
}
"#;
    check_source(aggregates).expect("dead Copy aggregate bindings should typecheck");
    let aggregate_generated =
        compile_to_c(aggregates).expect("dead Copy aggregates should optimize safely");
    assert!(!aggregate_generated.contains("flux__local_deadLiteral"));
    assert!(!aggregate_generated.contains("flux__local_deadUpdate"));
    assert!(!aggregate_generated.contains("flux__local_deadField"));
    assert!(!aggregate_generated.contains("flux__local_deadIndex"));
    assert!(!aggregate_generated.contains("flux__local_deadLength"));
    assert!(!aggregate_generated.contains("flux__local_checkedIndex"));
    assert!(aggregate_generated.contains("flux_list_at("));
    assert!(!aggregate_generated.contains("flux__local_checkedNegation"));
    assert!(aggregate_generated.contains("flux_neg_i64(flux__local_dynamicIndex)"));
    assert!(aggregate_generated.contains("flux__fn_observe(INT64_C(4))"));
    assert!(!aggregate_generated.contains("flux__local_observed"));

    let moved_source = r#"
fn main() -> i64 {
    let source: i64[] = [1, 2]
    let moved: i64[] = source
    if false:
        print(moved.length)
    return 0
}
"#;
    check_source(moved_source).expect("dead non-copy moves should remain semantically valid");
    let moved_generated =
        compile_to_c(moved_source).expect("dead non-copy moves should preserve ownership lowering");
    assert!(moved_generated.contains("flux__local_moved = flux__local_source"));

    let dead_list_literal = r#"
fn main() -> i64 {
    let deadList: i64[] = [1, 2, 3]
    if false:
        print(deadList.length)
    return 0
}
"#;
    check_source(dead_list_literal).expect("dead non-escaping list literal should typecheck");
    let dead_list_generated = compile_to_c(dead_list_literal)
        .expect("dead non-escaping list literal should be eliminated");
    assert!(!dead_list_generated.contains("flux__local_deadList"));
    assert!(!dead_list_generated.contains("INT64_C(1), INT64_C(2), INT64_C(3)"));
}

