#[test]
fn integer_arithmetic_lowers_through_checked_helpers() {
    let source = r#"
fn calculate(left: i64, right: i64) -> i64 {
    let sum: i64 = left + right
    let difference: i64 = sum - right
    let product: i64 = difference * right
    return -product
}

fn main() -> i64 {
    print(calculate(4, 3))
    return 0
}
"#;

    check_source(source).expect("checked integer arithmetic should typecheck");
    let generated = compile_to_c(source).expect("checked integer arithmetic should lower");
    assert!(generated.contains("flux_add_i64(flux__local_left, flux__local_right)"));
    assert!(generated.contains("(flux__local_sum) - (flux__local_right)"));
    assert!(generated.contains("flux_mul_i64(flux__local_difference, flux__local_right)"));
    assert!(generated.contains("return flux_neg_i64(flux__local_product);"));
    assert!(generated.contains("__builtin_add_overflow"));
    assert!(generated.contains("__builtin_mul_overflow"));
}

#[test]
fn eliminates_checked_integer_helpers_for_proven_safe_reductions() {
    let identities = r#"
const DIVISOR: i64 = 2

fn identities(value: i64) -> i64 {
    let addedLeft: i64 = 0 + value
    let addedRight: i64 = addedLeft + 0
    let subtracted: i64 = addedRight - 0
    let multipliedLeft: i64 = 1 * subtracted
    let multipliedRight: i64 = multipliedLeft * 1
    return multipliedRight / 1
}

fn negateMultiplyLeft(value: i64) -> i64 {
    return -1 * value
}

fn negateMultiplyRight(value: i64) -> i64 {
    return value * -1
}

fn negateDivide(value: i64) -> i64 {
    return value / -1
}

fn subtractFromZero(value: i64) -> i64 {
    return 0 - value
}

fn subtractSelf(value: i64) -> i64 {
    return value - value
}

fn divideSelf(value: i64) -> i64 {
    return value / value
}

fn divideByConstant(value: i64) -> i64 {
    return value / DIVISOR
}

fn divideByNegativeConstant(value: i64) -> i64 {
    return value / -2
}

fn cancelWithNegatedRight(value: i64) -> i64 {
    return value + -value
}

fn cancelWithNegatedLeft(value: i64) -> i64 {
    return -value + value
}

fn equalSelf(value: i64) -> bool {
    return value == value
}

fn lessSelf(value: i64) -> bool {
    return value < value
}

fn equalTextSelf(value: str) -> bool {
    return value == value
}

fn andSelf(value: bool) -> bool {
    return value && value
}

fn orSelf(value: bool) -> bool {
    return value || value
}

fn main() -> i64 {
    print(identities(7))
    print(negateMultiplyLeft(8))
    print(negateMultiplyRight(9))
    print(negateDivide(10))
    print(subtractSelf(12))
    print(divideSelf(13))
    print(divideByConstant(9))
    print(divideByNegativeConstant(-9))
    print(cancelWithNegatedRight(10))
    print(cancelWithNegatedLeft(11))
    print(equalSelf(4))
    print(lessSelf(4))
    print(equalTextSelf("flux"))
    print(andSelf(true))
    print(orSelf(false))
    return subtractFromZero(11)
}
"#;

    check_source(identities).expect("identity arithmetic should typecheck");
    let generated = compile_to_c(identities).expect("identity arithmetic should lower natively");
    assert!(!generated.contains("flux_add_i64("));
    assert!(!generated.contains("flux_sub_i64("));
    assert!(!generated.contains("flux_mul_i64("));
    assert!(!generated.contains("flux_div_i64("));
    assert!(!generated.contains("flux_sub_i64(flux__local_value, flux__local_value)"));
    assert!(generated.contains("return INT64_C(0);"));
    assert!(generated.contains("return flux_div_self_i64(flux__local_value);"));
    assert!(generated.contains("flux_div_self_i64(int64_t value) { if (value == 0)"));
    assert!(!generated.contains("b == 0 || (a == INT64_MIN && b == -1)"));
    assert_eq!(
        generated
            .matches("return flux_neg_i64(flux__local_value);")
            .count(),
        4
    );
    assert!(generated.contains("return ((flux__local_value) / INT64_C(2));"));
    assert!(generated.contains("return ((flux__local_value) / INT64_C(-2));"));
    assert_eq!(
        generated
            .matches("return ((void)(flux_neg_i64(flux__local_value)), INT64_C(0));")
            .count(),
        2
    );
    assert!(generated.contains("static inline bool flux__fn_equalSelf"));
    assert!(generated.contains("static inline bool flux__fn_lessSelf"));
    assert!(generated.contains("static inline bool flux__fn_equalTextSelf"));
    assert!(generated.contains("static inline bool flux__fn_andSelf"));
    assert!(generated.contains("static inline bool flux__fn_orSelf"));
    assert!(!generated.contains("flux__local_value == flux__local_value"));
    assert!(!generated.contains("flux__local_value < flux__local_value"));
    assert!(!generated.contains("strcmp(flux__local_value, flux__local_value)"));
    assert!(!generated.contains("flux__local_value && flux__local_value"));
    assert!(!generated.contains("flux__local_value || flux__local_value"));

    let boolean_effects = r#"
fn observeBool(value: bool) -> bool {
    print(value)
    return value
}

fn combine(value: bool) -> bool {
    return observeBool(value) && observeBool(value)
}

fn main() -> i64 {
    print(combine(true))
    return 0
}
"#;
    let boolean_effects_generated = compile_to_c(boolean_effects)
        .expect("effectful boolean operands must retain short-circuit evaluation");
    assert!(boolean_effects_generated.contains(
        "flux__fn_observeBool(flux__local_value) && flux__fn_observeBool(flux__local_value)"
    ));

    let annihilators = r#"
fn observe(value: i64) -> i64 {
    print(value)
    return value
}

fn zeroLeft(value: i64) -> i64 {
    return 0 * observe(value)
}

fn zeroRight(value: i64) -> i64 {
    return observe(value) * 0
}

fn zeroChecked(value: i64) -> i64 {
    return (value + 1) * 0
}

fn main() -> i64 {
    print(zeroLeft(7))
    print(zeroRight(9))
    return zeroChecked(4)
}
"#;
    check_source(annihilators).expect("zero-multiplication arithmetic should typecheck");
    let annihilator_generated = compile_to_c(annihilators)
        .expect("zero multiplication should lower without overflow checks");
    assert!(!annihilator_generated.contains("flux_mul_i64("));
    assert_eq!(
        annihilator_generated
            .matches("((void)(flux__fn_observe(flux__local_value)), INT64_C(0))")
            .count(),
        2
    );
    assert!(annihilator_generated.contains("flux_add_i64(flux__local_value, INT64_C(1))"));

    let checked = r#"
fn increment(value: i64) -> i64 {
    return value + 1
}

fn divide(value: i64, divisor: i64) -> i64 {
    return value / divisor
}

fn main() -> i64 {
    print(increment(7))
    return divide(8, 2)
}
"#;
    let checked_generated =
        compile_to_c(checked).expect("non-identity arithmetic should retain checked lowering");
    assert!(checked_generated.contains("flux_add_i64(flux__local_value, INT64_C(1))"));
    assert!(checked_generated.contains("flux_div_i64(flux__local_value, flux__local_divisor)"));

    let ui = r#"
view Counter {
    grid columns: 1fr
    grid rows: auto auto auto auto
    state count: i64 = 1
    state active: bool = true
    Text status at 1,1
        text: "Active"
        visible: count - count == 0
    Text ratio at 2,1
        text: "Safe"
        visible: count / count == 1
    Text boolean at 3,1
        text: "Ready"
        visible: active && active
    Button action at 4,1
        text: "Keep"
        visible: count >= count
        onPress: count => count * 1
}
app Counter
"#;
    let ui_generated =
        compile_to_c(ui).expect("UI identity arithmetic should use the same proven lowering");
    assert!(!ui_generated.contains("flux_sub_i64("));
    assert!(!ui_generated.contains("flux_mul_i64("));
    assert!(ui_generated.contains("flux_div_self_i64(flux__ui_state_count)"));
    assert!(!ui_generated.contains("flux__ui_state_count >= flux__ui_state_count"));
    assert!(!ui_generated.contains("flux__ui_state_active && flux__ui_state_active"));
}

#[test]
fn eliminates_redundant_boolean_short_circuit_work_for_proven_constants() {
    let source = r#"
fn observe(value: bool) -> bool {
    print(value)
    return value
}

fn andTrue(value: bool) -> bool {
    return value && true
}

fn orFalse(value: bool) -> bool {
    return value || false
}

fn trueAnd(value: bool) -> bool {
    return true && value
}

fn falseOr(value: bool) -> bool {
    return false || value
}

fn andComplement(value: bool) -> bool {
    return value && !value
}

fn orComplement(value: bool) -> bool {
    return value || !value
}

fn complementAnd(value: bool) -> bool {
    return !value && value
}

fn complementOr(value: bool) -> bool {
    return !value || value
}

fn andFalse(value: bool) -> bool {
    return observe(value) && false
}

fn orTrue(value: bool) -> bool {
    return observe(value) || true
}

fn skipAnd(value: bool) -> bool {
    return false && observe(value)
}

fn skipOr(value: bool) -> bool {
    return true || observe(value)
}

fn main() -> i64 {
    print(andTrue(true))
    print(orFalse(false))
    print(trueAnd(true))
    print(falseOr(false))
    print(andComplement(true))
    print(orComplement(false))
    print(complementAnd(false))
    print(complementOr(true))
    print(andFalse(true))
    print(orTrue(false))
    print(skipAnd(true))
    print(skipOr(false))
    return 0
}
"#;

    check_source(source).expect("boolean identity reductions should typecheck");
    let generated = compile_to_c(source).expect("boolean identities should lower natively");
    assert_eq!(generated.matches("return flux__local_value;").count(), 5);
    assert!(generated.contains("return ((void)(flux__local_value), false);"));
    assert!(generated.contains("return ((void)(flux__local_value), true);"));
    assert!(generated.contains("return ((void)((!flux__local_value)), false);"));
    assert!(generated.contains("return ((void)((!flux__local_value)), true);"));
    assert!(generated.contains("return ((void)(flux__fn_observe(flux__local_value)), false);"));
    assert!(generated.contains("return ((void)(flux__fn_observe(flux__local_value)), true);"));
    assert_eq!(
        generated
            .matches("flux__fn_observe(flux__local_value)")
            .count(),
        2
    );
    assert!(generated.contains("static inline bool flux__fn_skipAnd"));
    assert!(generated.contains("static inline bool flux__fn_skipOr"));
    assert!(generated.contains("return false;"));
    assert!(generated.contains("return true;"));

    let ui = r#"
view Status {
    grid columns: 1fr
    grid rows: auto auto auto auto
    state active: bool = true
    Text first at 1,1
        text: "One"
        visible: active && true
    Text second at 2,1
        text: "Two"
        visible: active || false
    Text third at 3,1
        text: "Three"
        visible: active && !active
    Text fourth at 4,1
        text: "Four"
        visible: !active || active
}
app Status
"#;
    let ui_generated = compile_to_c(ui).expect("UI boolean identities should share lowering");
    assert!(!ui_generated.contains("flux__ui_state_active && true"));
    assert!(!ui_generated.contains("flux__ui_state_active || false"));
    assert!(!ui_generated.contains("flux__ui_state_active && (!(flux__ui_state_active))"));
    assert!(!ui_generated.contains("(!(flux__ui_state_active)) && flux__ui_state_active"));
    assert!(ui_generated.contains("((void)(flux__ui_state_active), false)"));
    assert!(ui_generated.contains("((void)((!(flux__ui_state_active))), true)"));
}

#[test]
fn eliminates_redundant_boolean_comparisons_against_constants() {
    let source = r#"
const YES: bool = true
const NO: bool = false

fn observe(value: bool) -> bool {
    print(value)
    return value
}

fn equalTrue(value: bool) -> bool {
    return value == true
}

fn trueEqual(value: bool) -> bool {
    return YES == value
}

fn equalFalse(value: bool) -> bool {
    return value == false
}

fn falseEqual(value: bool) -> bool {
    return NO == value
}

fn notEqualFalse(value: bool) -> bool {
    return value != false
}

fn falseNotEqual(value: bool) -> bool {
    return NO != value
}

fn notEqualTrue(value: bool) -> bool {
    return value != true
}

fn trueNotEqual(value: bool) -> bool {
    return YES != value
}

fn effectful(value: bool) -> bool {
    return observe(value) == false
}

fn main() -> i64 {
    print(equalTrue(true))
    print(trueEqual(false))
    print(equalFalse(true))
    print(falseEqual(false))
    print(notEqualFalse(true))
    print(falseNotEqual(false))
    print(notEqualTrue(true))
    print(trueNotEqual(false))
    print(effectful(true))
    return 0
}
"#;

    check_source(source).expect("boolean comparison identities should typecheck");
    let generated =
        compile_to_c(source).expect("boolean comparison identities should lower natively");
    assert_eq!(generated.matches("return flux__local_value;").count(), 5);
    assert_eq!(
        generated.matches("return (!(flux__local_value));").count(),
        4
    );
    assert!(generated.contains("return (!(flux__fn_observe(flux__local_value)));"));
    assert_eq!(
        generated
            .matches("flux__fn_observe(flux__local_value)")
            .count(),
        1,
        "effectful comparison operands must still evaluate exactly once",
    );
    assert!(!generated.contains("flux__local_value == true"));
    assert!(!generated.contains("flux__local_value == false"));
    assert!(!generated.contains("flux__local_value != true"));
    assert!(!generated.contains("flux__local_value != false"));

    let ui = r#"
view Status {
    grid columns: 1fr
    grid rows: auto auto auto auto
    state active: bool = true
    Text first at 1,1
        text: "One"
        visible: active == true
    Text second at 2,1
        text: "Two"
        visible: false == active
    Text third at 3,1
        text: "Three"
        visible: active != false
    Text fourth at 4,1
        text: "Four"
        visible: true != active
}
app Status
"#;
    let ui_generated =
        compile_to_c(ui).expect("UI boolean comparison identities should share lowering");
    assert!(!ui_generated.contains("flux__ui_state_active == true"));
    assert!(!ui_generated.contains("false == flux__ui_state_active"));
    assert!(!ui_generated.contains("flux__ui_state_active != false"));
    assert!(!ui_generated.contains("true != flux__ui_state_active"));
    assert!(ui_generated.contains("flux__ui_state_active"));
    assert!(ui_generated.contains("(!(flux__ui_state_active))"));
}

#[test]
fn eliminates_complementary_same_binding_boolean_comparisons() {
    let source = r#"
fn observe(value: bool) -> bool {
    print(value)
    return value
}

fn equalComplement(value: bool) -> bool {
    return value == !value
}

fn complementEqual(value: bool) -> bool {
    return !value == value
}

fn notEqualComplement(value: bool) -> bool {
    return value != !value
}

fn complementNotEqual(value: bool) -> bool {
    return !value != value
}

fn equalNegated(value: bool) -> bool {
    return !value == !value
}

fn notEqualNegated(value: bool) -> bool {
    return !value != !value
}

fn effectful(value: bool) -> bool {
    return observe(value) == !observe(value)
}

fn main() -> i64 {
    print(equalComplement(true))
    print(complementEqual(false))
    print(notEqualComplement(true))
    print(complementNotEqual(false))
    print(equalNegated(true))
    print(notEqualNegated(false))
    print(effectful(true))
    return 0
}
"#;

    check_source(source).expect("same-binding boolean comparison proofs should typecheck");
    let generated =
        compile_to_c(source).expect("same-binding boolean comparison proofs should lower natively");
    assert_eq!(generated.matches("return false;").count(), 3);
    assert_eq!(generated.matches("return true;").count(), 3);
    assert_eq!(
        generated
            .matches("flux__fn_observe(flux__local_value)")
            .count(),
        2,
        "effectful comparison operands must retain both source evaluations",
    );

    let ui = r#"
view Status {
    grid columns: 1fr
    grid rows: auto auto auto auto
    state active: bool = true
    Text first at 1,1
        text: "One"
        visible: active == !active
    Text second at 2,1
        text: "Two"
        visible: !active != active
    Text third at 3,1
        text: "Three"
        visible: !active == !active
    Text fourth at 4,1
        text: "Four"
        visible: !active != !active
}
app Status
"#;
    let ui_generated =
        compile_to_c(ui).expect("UI same-binding boolean comparison proofs should share lowering");
    assert!(!ui_generated.contains("flux__ui_state_active == (!(flux__ui_state_active))"));
    assert!(!ui_generated.contains("(!(flux__ui_state_active)) != flux__ui_state_active"));
    assert!(!ui_generated.contains("(!(flux__ui_state_active)) == (!(flux__ui_state_active))"));
    assert!(!ui_generated.contains("(!(flux__ui_state_active)) != (!(flux__ui_state_active))"));
}

#[test]
fn reuses_equivalent_pure_boolean_predicates_without_dropping_effects() {
    let source = r#"
fn observe(value: i64) -> i64 {
    print(value)
    return value
}

fn repeatedAnd(value: i64, limit: i64) -> bool {
    return (value + 1 > limit) && (value + 1 > limit)
}

fn repeatedOr(value: i64, limit: i64) -> bool {
    return (value + 1 > limit) || (value + 1 > limit)
}

fn complementAnd(value: i64, limit: i64) -> bool {
    return (value + 1 > limit) && !(value + 1 > limit)
}

fn complementOr(value: i64, limit: i64) -> bool {
    return (value + 1 > limit) || !(value + 1 > limit)
}

fn equalPredicate(value: i64, limit: i64) -> bool {
    return (value + 1 > limit) == (value + 1 > limit)
}

fn unequalComplement(value: i64, limit: i64) -> bool {
    return (value + 1 > limit) != !(value + 1 > limit)
}

fn absorbPredicate(value: i64, limit: i64, other: bool) -> bool {
    return (value + 1 > limit) && ((value + 1 > limit) || other)
}

fn resolvePredicate(value: i64, limit: i64, other: bool) -> bool {
    return (value + 1 > limit) || (!(value + 1 > limit) && other)
}

fn retainEffects(value: i64, limit: i64) -> bool {
    return (observe(value) > limit) && (observe(value) > limit)
}

fn main() -> i64 {
    print(repeatedAnd(1, 1))
    print(repeatedOr(0, 1))
    print(complementAnd(1, 1))
    print(complementOr(0, 1))
    print(equalPredicate(1, 1))
    print(unequalComplement(1, 1))
    print(absorbPredicate(1, 1, false))
    print(resolvePredicate(0, 1, true))
    print(retainEffects(2, 1))
    return 0
}
"#;

    check_source(source).expect("pure boolean predicate reuse should typecheck");
    let generated = compile_to_c(source)
        .expect("pure boolean predicate reuse should lower without duplicate work");
    assert_eq!(
        generated
            .matches("flux_add_i64(flux__local_value, INT64_C(1))")
            .count(),
        8,
        "each pure repeated/complementary/absorbed predicate should evaluate its checked addition once",
    );
    assert_eq!(
        generated
            .matches("flux__fn_observe(flux__local_value)")
            .count(),
        2,
        "effectful lookalike predicates must retain both source evaluations",
    );

    let root = std::env::temp_dir().join(format!(
        "flux-pure-boolean-reuse-{}-{}",
        std::process::id(),
        std::thread::current().name().unwrap_or("test")
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary pure-boolean directory should be writable");
    let c_path = root.join("pure-boolean-reuse.c");
    let exe_path = root.join("pure-boolean-reuse");
    fs::write(&c_path, &generated).expect("generated pure-boolean C should be writable");
    let compile = Command::new("clang")
        .args(["-std=c11", "-O2"])
        .arg(&c_path)
        .arg("-o")
        .arg(&exe_path)
        .output()
        .expect("clang should compile pure-boolean C");
    assert!(
        compile.status.success(),
        "pure-boolean C should compile: {}",
        String::from_utf8_lossy(&compile.stderr)
    );
    let output = Command::new(&exe_path)
        .output()
        .expect("pure-boolean program should run");
    assert!(output.status.success());
    assert_eq!(
        String::from_utf8_lossy(&output.stdout),
        "true\nfalse\nfalse\ntrue\ntrue\ntrue\ntrue\ntrue\n2\n2\ntrue\n"
    );
    let _ = fs::remove_dir_all(root);

    let ui = r#"
view Status {
    grid columns: 1fr
    grid rows: auto auto auto auto auto
    state count: i64 = 1
    Text first at 1,1
        text: "One"
        visible: (count + 1 > 1) && (count + 1 > 1)
    Text second at 2,1
        text: "Two"
        visible: (count + 1 > 1) && !(count + 1 > 1)
    Text third at 3,1
        text: "Three"
        visible: (count + 1 > 1) == (count + 1 > 1)
    Text fourth at 4,1
        text: "Four"
        visible: (count + 1 > 1) && ((count + 1 > 1) || false)
    Text fifth at 5,1
        text: "Five"
        visible: (count + 1 > 1) || (!(count + 1 > 1) && true)
}
app Status
"#;
    let ui_generated =
        compile_to_c(ui).expect("UI pure boolean predicate reuse should share native lowering");
    assert!(!ui_generated.contains("&& (flux_add_i64(flux__ui_state_count, INT64_C(1))"));
    assert!(!ui_generated.contains("== (flux_add_i64(flux__ui_state_count, INT64_C(1))"));
    assert!(!ui_generated.contains("|| (!(flux_add_i64(flux__ui_state_count, INT64_C(1))"));
}

#[test]
