    assert_eq!(
        String::from_utf8_lossy(&first_run.stdout),
        "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad\nnil\n1\n"
    );

    let object_dir = cache.join("native/objects");
