    let entry = root.join("main.flux");
    let initial = "pub fn helper() -> i64 { 1 }\n\nview Screen {\n    grid columns: 1fr\n    grid rows: auto\n    Text label at 1,1\n        text: \"ready\"\n}\napp Screen\n";
