#[test]
fn development_ui_string_patch_hot_applies_text_emphasis_declaration_lifecycle() {
    let root = std::env::temp_dir().join(format!(
        "flux-development-text-emphasis-lifecycle-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root)
        .expect("temporary text emphasis lifecycle project should be writable");
    let entry = root.join("main.flux");
    let initial = r#"view Screen {
    grid columns: 1fr
    grid rows: auto
    Text label at 1,1
        text: "Label"
}
app Screen
"#;
    fs::write(&entry, initial).expect("initial text emphasis lifecycle source should be writable");

    let mut cache = fluxc::project::ProjectAnalysisCache::default();
    let first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("initial text emphasis lifecycle source should analyze");
    let generated = first
        .emit_c()
        .expect("text emphasis lifecycle fixture should lower for Linux");
    for property in ["italic", "underline", "strikethrough"] {
        assert!(generated.contains(&format!(
            "strcmp(property, \"{property}\") == 0 && bool_value_valid && flux__ui_label != NULL"
        )));
    }

    let entry = fs::canonicalize(entry).expect("text emphasis lifecycle entry should canonicalize");
    let explicit_default = initial.replace(
        "        text: \"Label\"\n",
        "        text: \"Label\"\n        italic: false\n        underline: false\n        strikethrough: false\n",
    );
    fs::write(&entry, &explicit_default)
        .expect("explicit text emphasis defaults should be writable");
    cache.invalidate_path(&entry);
    let second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("explicit text emphasis defaults should analyze");
    assert_eq!(
        second.development_abi(),
        first.development_abi(),
        "adding false text emphasis defaults must not change the development ABI"
    );
    assert_eq!(
        second.development_ui_string_patch_from(&first),
        Some(Vec::new()),
        "adding false text emphasis defaults should be an in-process no-op"
    );

    let emphasized = explicit_default
        .replace("italic: false", "italic: true")
        .replace("underline: false", "underline: true")
        .replace("strikethrough: false", "strikethrough: true");
    fs::write(&entry, emphasized).expect("enabled text emphasis source should be writable");
    cache.invalidate_path(&entry);
    let third = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("enabled text emphasis source should analyze");
    assert_eq!(third.development_abi(), first.development_abi());
    let enabled_patch = third
        .development_ui_string_patch_from(&second)
        .expect("enabling text emphasis should hot-apply")
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    for property in ["italic", "underline", "strikethrough"] {
        assert_eq!(
            enabled_patch.get(&("label".to_string(), property.to_string())),
            Some(&"1".to_string())
        );
    }
    assert_eq!(enabled_patch.len(), 3);

    fs::write(&entry, initial).expect("removed text emphasis source should be writable");
    cache.invalidate_path(&entry);
    let fourth = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("removed text emphasis source should analyze");
    assert_eq!(fourth.development_abi(), third.development_abi());
    let restored_patch = fourth
        .development_ui_string_patch_from(&third)
        .expect("removing text emphasis should restore implicit false defaults")
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    for property in ["italic", "underline", "strikethrough"] {
        assert_eq!(
            restored_patch.get(&("label".to_string(), property.to_string())),
            Some(&"0".to_string())
        );
    }
    assert_eq!(restored_patch.len(), 3);

    let dynamic = initial
        .replace(
            "        text: \"Label\"\n",
            "        text: \"Label\"\n        italic: emphasized\n",
        )
        .replace(
            "    grid rows: auto\n",
            "    grid rows: auto\n    state emphasized: bool = false\n",
        );
    fs::write(&entry, dynamic).expect("dynamic text emphasis source should be writable");
    cache.invalidate_path(&entry);
    let dynamic = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("dynamic text emphasis source should analyze");
    assert_ne!(dynamic.development_abi(), fourth.development_abi());
    assert!(
        dynamic.development_ui_string_patch_from(&fourth).is_none(),
        "state-driven text emphasis must retain controlled restart"
    );

    let _ = fs::remove_dir_all(root);
}

#[test]
fn development_ui_string_patch_hot_applies_default_variant_bold_lifecycle() {
    let root = std::env::temp_dir().join(format!(
        "flux-development-bold-lifecycle-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary bold lifecycle project should be writable");
    let entry = root.join("main.flux");
    let initial = r#"view Screen {
    grid columns: 1fr
    grid rows: auto
    Text label at 1,1
        text: "Label"
}
app Screen
"#;
    fs::write(&entry, initial).expect("initial bold lifecycle source should be writable");

    let mut cache = fluxc::project::ProjectAnalysisCache::default();
    let first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("initial bold lifecycle source should analyze");
    let generated = first
        .emit_c()
        .expect("bold lifecycle fixture should lower for Linux");
    assert!(generated.contains("strcmp(property, \"bold\") == 0 && flux__ui_label != NULL"));
    assert!(generated.contains("strcmp(value, \"__flux_text_semantic_override_default__\") == 0"));
    assert!(generated.contains("flux__ui_text_bold_explicit_label = false"));

    let entry = fs::canonicalize(entry).expect("bold lifecycle entry should canonicalize");
    let explicit_default = initial.replace(
        "        text: \"Label\"\n",
        "        text: \"Label\"\n        bold: false\n",
    );
    fs::write(&entry, &explicit_default).expect("explicit bold default should be writable");
    cache.invalidate_path(&entry);
    let second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("explicit bold default should analyze");
    assert_eq!(
        second.development_abi(),
        first.development_abi(),
        "adding bold: false to default body Text must not change the development ABI"
    );
    assert_eq!(
        second
            .development_ui_string_patch_from(&first)
            .expect("adding an explicit body-default bold override should hot-apply ownership"),
        vec![fluxc::project::DevelopmentUiStringPatch {
            element: "label".to_string(),
            property: "bold".to_string(),
            value: "0".to_string(),
        }]
    );

    let bold = explicit_default.replace("bold: false", "bold: true");
    fs::write(&entry, bold).expect("bold source should be writable");
    cache.invalidate_path(&entry);
    let third = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("bold source should analyze");
    assert_eq!(third.development_abi(), first.development_abi());
    assert_eq!(
        third
            .development_ui_string_patch_from(&second)
            .expect("bold: true should hot-apply for default body Text"),
        vec![fluxc::project::DevelopmentUiStringPatch {
            element: "label".to_string(),
            property: "bold".to_string(),
            value: "1".to_string(),
        }]
    );

    fs::write(&entry, initial).expect("removed bold source should be writable");
    cache.invalidate_path(&entry);
    let fourth = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("removed bold source should analyze");
    assert_eq!(fourth.development_abi(), third.development_abi());
    assert_eq!(
        fourth
            .development_ui_string_patch_from(&third)
            .expect("removing bold should restore body default false"),
        vec![fluxc::project::DevelopmentUiStringPatch {
            element: "label".to_string(),
            property: "bold".to_string(),
            value: "__flux_text_semantic_override_default__".to_string(),
        }]
    );

    let heading_with_override = initial.replace(
        "        text: \"Label\"\n",
        "        text: \"Label\"\n        variant: \"heading\"\n        bold: true\n",
    );
    fs::write(&entry, &heading_with_override)
        .expect("heading bold override source should be writable");
    cache.invalidate_path(&entry);
    let heading_with_override = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("heading bold override source should analyze");

    let heading_without_override = heading_with_override
        .sources
        .iter()
        .find(|source| source.path == entry)
        .expect("heading source should remain loaded")
        .text
        .replace("        bold: true\n", "");
    fs::write(&entry, heading_without_override)
        .expect("heading without bold override should be writable");
    cache.invalidate_path(&entry);
    let heading_without_override = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("heading without bold override should analyze");
    assert_eq!(
        heading_without_override.development_abi(),
        heading_with_override.development_abi()
    );
    assert_eq!(
        heading_without_override
            .development_ui_string_patch_from(&heading_with_override)
            .expect("removing bold beside a semantic variant should restore inherited bold"),
        vec![fluxc::project::DevelopmentUiStringPatch {
            element: "label".to_string(),
            property: "bold".to_string(),
            value: "__flux_text_semantic_override_default__".to_string(),
        }]
    );

    let _ = fs::remove_dir_all(root);
}

#[test]
fn development_ui_string_patch_hot_applies_password_declaration_lifecycle() {
    let root = std::env::temp_dir().join(format!(
        "flux-development-password-lifecycle-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary password lifecycle project should be writable");
    let entry = root.join("main.flux");
    let initial = r#"view Screen {
    grid columns: 1fr
    grid rows: auto
    TextInput input at 1,1
        text: "Secret"
}
app Screen
"#;
    fs::write(&entry, initial).expect("initial password lifecycle source should be writable");

    let mut cache = fluxc::project::ProjectAnalysisCache::default();
    let first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("initial password lifecycle source should analyze");
    let generated = first
        .emit_c()
        .expect("password lifecycle fixture should lower for Linux");
    assert!(generated.contains(
        "strcmp(property, \"password\") == 0 && bool_value_valid && flux__ui_input != NULL"
    ));
    assert!(generated.contains("gtk_entry_set_visibility(GTK_ENTRY(flux__ui_input), !bool_value)"));

    let entry = fs::canonicalize(entry).expect("password lifecycle entry should canonicalize");
    let explicit_default = initial.replace(
        "        text: \"Secret\"\n",
        "        text: \"Secret\"\n        password: false\n",
    );
    fs::write(&entry, &explicit_default).expect("explicit password default should be writable");
    cache.invalidate_path(&entry);
    let second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("explicit password default should analyze");
    assert_eq!(
        second.development_abi(),
        first.development_abi(),
        "adding password: false must not change the development ABI"
    );
    assert_eq!(
        second.development_ui_string_patch_from(&first),
        Some(Vec::new()),
        "adding password: false should be an in-process no-op"
    );

    let protected = explicit_default.replace("password: false", "password: true");
    fs::write(&entry, protected).expect("protected password source should be writable");
    cache.invalidate_path(&entry);
    let third = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("protected password source should analyze");
    assert_eq!(third.development_abi(), first.development_abi());
    assert_eq!(
        third
            .development_ui_string_patch_from(&second)
            .expect("password: true should hot-apply"),
        vec![fluxc::project::DevelopmentUiStringPatch {
            element: "input".to_string(),
            property: "password".to_string(),
            value: "1".to_string(),
        }]
    );

    fs::write(&entry, initial).expect("removed password source should be writable");
    cache.invalidate_path(&entry);
    let fourth = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("removed password source should analyze");
    assert_eq!(fourth.development_abi(), third.development_abi());
    assert_eq!(
        fourth
            .development_ui_string_patch_from(&third)
            .expect("removing password should restore the implicit false value"),
        vec![fluxc::project::DevelopmentUiStringPatch {
            element: "input".to_string(),
            property: "password".to_string(),
            value: "0".to_string(),
        }]
    );

    let dynamic = initial
        .replace(
            "    grid rows: auto\n",
            "    grid rows: auto\n    state protected: bool = false\n",
        )
        .replace(
            "        text: \"Secret\"\n",
            "        text: \"Secret\"\n        password: protected\n",
        );
    fs::write(&entry, dynamic).expect("dynamic password source should be writable");
    cache.invalidate_path(&entry);
    let dynamic = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("dynamic password source should analyze");
    assert_ne!(dynamic.development_abi(), fourth.development_abi());
    assert!(
        dynamic.development_ui_string_patch_from(&fourth).is_none(),
        "state-driven password must retain controlled restart"
    );

    let multiline = initial.replace(
        "        text: \"Secret\"\n",
        "        text: \"Secret\"\n        multiline: true\n        password: false\n",
    );
    fs::write(&entry, multiline).expect("multiline password source should be writable");
    cache.invalidate_path(&entry);
    let multiline = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("multiline password source should analyze");
    assert_ne!(
        multiline.development_abi(),
        fourth.development_abi(),
        "multiline password remains outside the compatible lifecycle path"
    );
    assert!(
        multiline
            .development_ui_string_patch_from(&fourth)
            .is_none(),
        "multiline password must retain controlled restart"
    );

    let _ = fs::remove_dir_all(root);
}

#[test]
fn development_ui_string_patch_hot_applies_callback_free_selection_lifecycle() {
    let root = std::env::temp_dir().join(format!(
        "flux-development-selection-lifecycle-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary selection lifecycle project should be writable");
    let entry = root.join("main.flux");
    let initial = r#"view Screen {
    grid columns: 1fr
    grid rows: auto auto
    Toggle toggle at 1,1
        label: "Toggle"
    Radio radio at 2,1
        label: "Radio"
}
app Screen
"#;
    fs::write(&entry, initial).expect("initial selection lifecycle source should be writable");

    let mut cache = fluxc::project::ProjectAnalysisCache::default();
    let first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("initial selection lifecycle source should analyze");
    let generated = first
        .emit_c()
        .expect("selection lifecycle fixture should lower for Linux");
    assert!(generated.contains(
        "strcmp(property, \"checked\") == 0 && bool_value_valid && flux__ui_toggle != NULL"
    ));
    assert!(generated.contains(
        "strcmp(property, \"selected\") == 0 && bool_value_valid && flux__ui_radio != NULL"
    ));

    let entry = fs::canonicalize(entry).expect("selection lifecycle entry should canonicalize");
    let explicit_default = initial
        .replace(
            "        label: \"Toggle\"\n",
            "        label: \"Toggle\"\n        checked: false\n",
        )
        .replace(
            "        label: \"Radio\"\n",
            "        label: \"Radio\"\n        selected: false\n",
        );
    fs::write(&entry, &explicit_default).expect("explicit selection defaults should be writable");
    cache.invalidate_path(&entry);
    let second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("explicit selection defaults should analyze");
    assert_eq!(
        second.development_abi(),
        first.development_abi(),
        "adding false callback-free selection defaults must not change the development ABI"
    );
    assert_eq!(
        second.development_ui_string_patch_from(&first),
        Some(Vec::new()),
        "adding false callback-free selection defaults should be an in-process no-op"
    );

    let active = explicit_default
        .replace("checked: false", "checked: true")
        .replace("selected: false", "selected: true");
    fs::write(&entry, active).expect("active selection source should be writable");
    cache.invalidate_path(&entry);
    let third = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("active selection source should analyze");
    assert_eq!(third.development_abi(), first.development_abi());
    let active_patch = third
        .development_ui_string_patch_from(&second)
        .expect("callback-free selection activation should hot-apply")
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    assert_eq!(
        active_patch.get(&("toggle".to_string(), "checked".to_string())),
        Some(&"1".to_string())
    );
    assert_eq!(
        active_patch.get(&("radio".to_string(), "selected".to_string())),
        Some(&"1".to_string())
    );
    assert_eq!(active_patch.len(), 2);

    fs::write(&entry, initial).expect("removed selection source should be writable");
    cache.invalidate_path(&entry);
    let fourth = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("removed selection source should analyze");
    assert_eq!(fourth.development_abi(), third.development_abi());
    let restored_patch = fourth
        .development_ui_string_patch_from(&third)
        .expect("removing callback-free selection should restore false defaults")
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    assert_eq!(
        restored_patch.get(&("toggle".to_string(), "checked".to_string())),
        Some(&"0".to_string())
    );
    assert_eq!(
        restored_patch.get(&("radio".to_string(), "selected".to_string())),
        Some(&"0".to_string())
    );
    assert_eq!(restored_patch.len(), 2);

    let _ = fs::remove_dir_all(root);
}

