#[test]
fn development_ui_string_patch_hot_applies_minimum_size_declaration_lifecycle() {
    let root = std::env::temp_dir().join(format!(
        "flux-development-minimum-size-lifecycle-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary minimum-size lifecycle project should be writable");
    let entry = root.join("main.flux");
    let initial = r#"view Screen {
    grid columns: 120
    grid rows: auto auto
    Text label at 1,1
        text: "Sized"
    Button action at 2,1
        text: "Go"
}
app Screen
"#;
    fs::write(&entry, initial).expect("initial minimum-size lifecycle source should be writable");

    let mut cache = fluxc::project::ProjectAnalysisCache::default();
    let first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("initial minimum-size lifecycle source should analyze");
    let generated = first
        .emit_c()
        .expect("minimum-size lifecycle fixture should lower for Linux");
    assert!(
        generated
            .contains("strcmp(property, \"min_width\") == 0 && flux__ui_constraint_label != NULL")
    );
    assert!(
        generated
            .contains("strcmp(property, \"min_height\") == 0 && flux__ui_constraint_label != NULL")
    );
    assert!(
        generated.contains(
            "strcmp(property, \"min_height\") == 0 && flux__ui_constraint_action != NULL"
        )
    );
    assert!(generated.contains("strcmp(value, \"__flux_minimum_size_default__\") == 0"));
    assert!(generated.contains("long long patched_size = INT64_C(120)"));
    assert!(generated.contains("long long patched_size = INT64_C(-1)"));
    assert!(generated.contains("long long patched_size = INT64_C(40)"));

    let entry = fs::canonicalize(entry).expect("minimum-size lifecycle entry should canonicalize");
    let explicit = initial
        .replace(
            "    Text label at 1,1\n",
            "    Text label at 1,1\n        minWidth: 140\n        minHeight: 30\n",
        )
        .replace(
            "    Button action at 2,1\n",
            "    Button action at 2,1\n        minHeight: 60\n",
        );
    fs::write(&entry, &explicit).expect("explicit minimum-size source should be writable");
    cache.invalidate_path(&entry);
    let second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("explicit minimum-size source should analyze");
    assert_eq!(
        second.development_abi(),
        first.development_abi(),
        "adding literal minimum-size declarations must not change the development ABI"
    );
    let patch = second
        .development_ui_string_patch_from(&first)
        .expect("adding literal minimum sizes should hot-apply")
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    assert_eq!(
        patch.get(&("label".to_string(), "min_width".to_string())),
        Some(&"140".to_string())
    );
    assert_eq!(
        patch.get(&("label".to_string(), "min_height".to_string())),
        Some(&"30".to_string())
    );
    assert_eq!(
        patch.get(&("action".to_string(), "min_height".to_string())),
        Some(&"60".to_string())
    );
    assert_eq!(patch.len(), 3);

    fs::write(&entry, initial).expect("removed minimum-size declarations should be writable");
    cache.invalidate_path(&entry);
    let third = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("removed minimum-size declarations should analyze");
    assert_eq!(third.development_abi(), second.development_abi());
    let patch = third
        .development_ui_string_patch_from(&second)
        .expect("removing literal minimum sizes should restore omitted defaults")
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    for key in [
        ("label".to_string(), "min_width".to_string()),
        ("label".to_string(), "min_height".to_string()),
        ("action".to_string(), "min_height".to_string()),
    ] {
        assert_eq!(
            patch.get(&key),
            Some(&"__flux_minimum_size_default__".to_string())
        );
    }
    assert_eq!(patch.len(), 3);

    let dynamic = initial.replace(
        "    Text label at 1,1\n",
        "    state width: i64 = 140\n    Text label at 1,1\n        minWidth: width\n",
    );
    fs::write(&entry, dynamic).expect("dynamic minimum-size source should be writable");
    cache.invalidate_path(&entry);
    let dynamic = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("dynamic minimum-size source should analyze");
    assert!(
        dynamic.development_ui_string_patch_from(&third).is_none(),
        "state-driven minimum sizes must retain controlled restart"
    );

    let _ = fs::remove_dir_all(root);
}

#[test]
fn development_ui_string_patch_hot_applies_unconstrained_minimum_sizes() {
    let root = std::env::temp_dir().join(format!(
        "flux-development-minimum-size-patch-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary minimum-size patch project should be writable");
    let entry = root.join("main.flux");
    let initial = r#"view Screen {
    grid columns: 120
    grid rows: auto
    Text label at 1,1
        text: "Sized"
        minWidth: 80
        minHeight: 20
}
app Screen
"#;
    fs::write(&entry, initial).expect("initial minimum-size patch source should be writable");

    let mut cache = fluxc::project::ProjectAnalysisCache::default();
    let first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("initial minimum-size patch analysis should succeed");

    let updated = initial
        .replace("minWidth: 80", "minWidth: 140")
        .replace("minHeight: 20", "minHeight: 30");
    fs::write(&entry, &updated).expect("updated minimum-size patch source should be writable");
    let entry = fs::canonicalize(entry).expect("minimum-size patch entry should canonicalize");
    cache.invalidate_path(&entry);
    let second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("updated minimum-size patch analysis should succeed");
    let patch = second
        .development_ui_string_patch_from(&first)
        .expect("unconstrained minimum sizes should hot-apply");
    let patch = patch
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    assert_eq!(
        patch.get(&("label".to_string(), "min_width".to_string())),
        Some(&"140".to_string())
    );
    assert_eq!(
        patch.get(&("label".to_string(), "min_height".to_string())),
        Some(&"30".to_string())
    );
    assert_eq!(patch.len(), 2);

    let generated = second
        .emit_c()
        .expect("minimum-size patch fixture should lower for Linux");
    assert!(generated.contains("strcmp(property, \"min_width\") == 0 && flux__ui_label != NULL"));
    assert!(
        generated.contains(
            "gtk_widget_get_size_request(flux__ui_label, &current_width, &current_height)"
        )
    );
    assert!(generated.contains("if (patched_size < INT64_C(120)) patched_size = INT64_C(120)"));
    assert!(generated.contains(
        "gtk_widget_set_size_request(flux__ui_label, (int)patched_size, current_height)"
    ));
    assert!(
        generated.contains(
            "gtk_widget_set_size_request(flux__ui_label, current_width, (int)patched_size)"
        )
    );

    let invalid = updated.replace("minWidth: 140", "minWidth: 0");
    fs::write(&entry, invalid).expect("invalid minimum-size edit should be writable");
    cache.invalidate_path(&entry);
    let invalid = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("invalid minimum size remains semantically an i64");
    assert!(
        invalid.development_ui_string_patch_from(&second).is_none(),
        "target-invalid minimum size must use normal rebuild validation"
    );
    assert!(
        invalid.emit_c().is_err(),
        "target-invalid minimum size must still reach native validation"
    );

    let constrained_initial =
        initial.replace("minWidth: 80", "minWidth: 80\n        maxWidth: 200");
    fs::write(&entry, &constrained_initial)
        .expect("constrained minimum-size source should be writable");
    cache.invalidate_path(&entry);
    let constrained_first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("constrained minimum-size source should analyze");
    let constrained_updated = constrained_initial.replace("minWidth: 80", "minWidth: 100");
    fs::write(&entry, constrained_updated)
        .expect("constrained minimum-size edit should be writable");
    cache.invalidate_path(&entry);
    let constrained_second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("constrained minimum-size edit should analyze");
    let constrained_patch = constrained_second
        .development_ui_string_patch_from(&constrained_first)
        .expect("literal minimum-size edits paired with a literal maximum should hot-apply");
    assert_eq!(
        constrained_patch,
        vec![fluxc::project::DevelopmentUiStringPatch {
            element: "label".to_string(),
            property: "min_width".to_string(),
            value: "100".to_string(),
        }]
    );
    let constrained_generated = constrained_second
        .emit_c()
        .expect("constrained minimum-size patch fixture should lower for Linux");
    assert!(
        constrained_generated
            .contains("strcmp(property, \"min_width\") == 0 && flux__ui_constraint_label != NULL")
    );
    assert!(constrained_generated.contains(
        "gtk_widget_set_size_request(flux__ui_constraint_label, (int)patched_size, current_height)"
    ));

    let invalid_pair = constrained_initial.replace("minWidth: 80", "minWidth: 220");
    fs::write(&entry, invalid_pair).expect("invalid constrained minimum edit should be writable");
    cache.invalidate_path(&entry);
    let invalid_pair = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("invalid constrained minimum remains semantically typed");
    assert!(
        invalid_pair
            .development_ui_string_patch_from(&constrained_first)
            .is_none(),
        "a literal minimum above its maximum must fall back to normal target validation"
    );
    assert!(
        invalid_pair.emit_c().is_err(),
        "a literal minimum above its maximum must still fail native validation"
    );

    let dynamic_maximum = r#"view Screen {
    grid columns: 120
    grid rows: auto
    state limit: i64 = 200
    Text label at 1,1
        text: "Sized"
        minWidth: 80
        maxWidth: limit
}
app Screen
"#;
    fs::write(&entry, dynamic_maximum)
        .expect("dynamic-maximum minimum-size source should be writable");
    cache.invalidate_path(&entry);
    let dynamic_first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("dynamic-maximum minimum-size source should analyze");
    let dynamic_updated = dynamic_maximum.replace("minWidth: 80", "minWidth: 100");
    fs::write(&entry, dynamic_updated)
        .expect("dynamic-maximum minimum-size edit should be writable");
    cache.invalidate_path(&entry);
    let dynamic_second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("dynamic-maximum minimum-size edit should analyze");
    assert!(
        dynamic_second
            .development_ui_string_patch_from(&dynamic_first)
            .is_none(),
        "minimum-size edits paired with a dynamic maximum must retain normal rebuild validation"
    );

    let _ = fs::remove_dir_all(root);
}

#[test]
fn development_ui_string_patch_hot_applies_maximum_size_declaration_lifecycle() {
    let root = std::env::temp_dir().join(format!(
        "flux-development-maximum-size-lifecycle-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary maximum-size lifecycle project should be writable");
    let entry = root.join("main.flux");
    let initial = r#"view Screen {
    grid columns: 240
    grid rows: 120
    Text label at 1,1
        text: "Sized"
}
app Screen
"#;
    fs::write(&entry, initial).expect("initial maximum-size lifecycle source should be writable");

    let mut cache = fluxc::project::ProjectAnalysisCache::default();
    let first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("initial maximum-size lifecycle source should analyze");
    let generated = first
        .emit_c()
        .expect("maximum-size lifecycle fixture should lower for Linux");
    assert!(generated.contains(
        "#ifdef FLUX_DEVELOPMENT_RELOAD\nstatic GtkWidget *flux__ui_constraint_label = NULL;"
    ));
    assert!(
        generated.contains(
            "flux__ui_constraint_label = flux_size_constraint_new(flux__ui_label, -1, -1)"
        )
    );
    assert!(
        generated
            .contains("strcmp(property, \"max_width\") == 0 && flux__ui_constraint_label != NULL")
    );
    assert!(
        generated
            .contains("strcmp(property, \"max_height\") == 0 && flux__ui_constraint_label != NULL")
    );
    assert!(generated.contains("strcmp(value, \"__flux_maximum_size_default__\") == 0"));

    let entry = fs::canonicalize(entry).expect("maximum-size lifecycle entry should canonicalize");
    let explicit = initial.replace(
        "    Text label at 1,1\n",
        "    Text label at 1,1\n        maxWidth: 200\n        maxHeight: 80\n",
    );
    fs::write(&entry, &explicit).expect("explicit maximum-size source should be writable");
    cache.invalidate_path(&entry);
    let second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("explicit maximum-size source should analyze");
    assert_eq!(
        second.development_abi(),
        first.development_abi(),
        "adding literal maximum-size declarations must not change the development ABI"
    );
    let patch = second
        .development_ui_string_patch_from(&first)
        .expect("adding literal maximum sizes should hot-apply")
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    assert_eq!(
        patch.get(&("label".to_string(), "max_width".to_string())),
        Some(&"200".to_string())
    );
    assert_eq!(
        patch.get(&("label".to_string(), "max_height".to_string())),
        Some(&"80".to_string())
    );
    assert_eq!(patch.len(), 2);

    fs::write(&entry, initial).expect("removed maximum-size declarations should be writable");
    cache.invalidate_path(&entry);
    let third = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("removed maximum-size declarations should analyze");
    assert_eq!(third.development_abi(), second.development_abi());
    let patch = third
        .development_ui_string_patch_from(&second)
        .expect("removing literal maximum sizes should restore omitted defaults")
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    for key in [
        ("label".to_string(), "max_width".to_string()),
        ("label".to_string(), "max_height".to_string()),
    ] {
        assert_eq!(
            patch.get(&key),
            Some(&"__flux_maximum_size_default__".to_string())
        );
    }
    assert_eq!(patch.len(), 2);

    let dynamic = initial.replace(
        "    Text label at 1,1\n",
        "    state limit: i64 = 200\n    Text label at 1,1\n        maxWidth: limit\n",
    );
    fs::write(&entry, dynamic).expect("dynamic maximum-size source should be writable");
    cache.invalidate_path(&entry);
    let dynamic = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("dynamic maximum-size source should analyze");
    assert!(
        dynamic.development_ui_string_patch_from(&third).is_none(),
        "state-driven maximum sizes must retain controlled restart"
    );

    let _ = fs::remove_dir_all(root);
}

#[test]
fn development_ui_string_patch_hot_applies_unconstrained_maximum_sizes() {
    let root = std::env::temp_dir().join(format!(
        "flux-development-maximum-size-patch-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary maximum-size patch project should be writable");
    let entry = root.join("main.flux");
    let initial = r#"view Screen {
    grid columns: 240
    grid rows: 120
    Text label at 1,1
        text: "Sized"
        maxWidth: 200
        maxHeight: 80
}
app Screen
"#;
    fs::write(&entry, initial).expect("initial maximum-size patch source should be writable");

    let mut cache = fluxc::project::ProjectAnalysisCache::default();
    let first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("initial maximum-size patch analysis should succeed");

    let updated = initial
        .replace("maxWidth: 200", "maxWidth: 180")
        .replace("maxHeight: 80", "maxHeight: 70");
    fs::write(&entry, &updated).expect("updated maximum-size patch source should be writable");
    let entry = fs::canonicalize(entry).expect("maximum-size patch entry should canonicalize");
    cache.invalidate_path(&entry);
    let second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("updated maximum-size patch analysis should succeed");
    let patch = second
        .development_ui_string_patch_from(&first)
        .expect("unconstrained maximum sizes should hot-apply");
    let patch = patch
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    assert_eq!(
        patch.get(&("label".to_string(), "max_width".to_string())),
        Some(&"180".to_string())
    );
    assert_eq!(
        patch.get(&("label".to_string(), "max_height".to_string())),
        Some(&"70".to_string())
    );
    assert_eq!(patch.len(), 2);

    let generated = second
        .emit_c()
        .expect("maximum-size patch fixture should lower for Linux");
    assert!(
        generated
            .contains("strcmp(property, \"max_width\") == 0 && flux__ui_constraint_label != NULL")
    );
    assert!(generated.contains(
        "flux_size_constraint_set_max_width(flux__ui_constraint_label, (int)integer_value)"
    ));
    assert!(generated.contains(
        "flux_size_constraint_set_max_height(flux__ui_constraint_label, (int)integer_value)"
    ));

    let invalid = updated.replace("maxWidth: 180", "maxWidth: 0");
    fs::write(&entry, invalid).expect("invalid maximum-size edit should be writable");
    cache.invalidate_path(&entry);
    let invalid = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("invalid maximum size remains semantically an i64");
    assert!(
        invalid.development_ui_string_patch_from(&second).is_none(),
        "target-invalid maximum size must use normal rebuild validation"
    );
    assert!(
        invalid.emit_c().is_err(),
        "target-invalid maximum size must still reach native validation"
    );

    let constrained_initial =
        initial.replace("maxWidth: 200", "minWidth: 80\n        maxWidth: 200");
    fs::write(&entry, &constrained_initial)
        .expect("constrained maximum-size source should be writable");
    cache.invalidate_path(&entry);
    let constrained_first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("constrained maximum-size source should analyze");
    let constrained_updated = constrained_initial.replace("maxWidth: 200", "maxWidth: 180");
    fs::write(&entry, constrained_updated)
        .expect("constrained maximum-size edit should be writable");
    cache.invalidate_path(&entry);
    let constrained_second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("constrained maximum-size edit should analyze");
    let constrained_patch = constrained_second
        .development_ui_string_patch_from(&constrained_first)
        .expect("literal maximum-size edits paired with a literal minimum should hot-apply");
    assert_eq!(
        constrained_patch,
        vec![fluxc::project::DevelopmentUiStringPatch {
            element: "label".to_string(),
            property: "max_width".to_string(),
            value: "180".to_string(),
        }]
    );
    let constrained_generated = constrained_second
        .emit_c()
        .expect("constrained maximum-size patch fixture should lower for Linux");
    assert!(
        constrained_generated
            .contains("strcmp(property, \"max_width\") == 0 && flux__ui_constraint_label != NULL")
    );
    assert!(constrained_generated.contains(
        "flux_size_constraint_set_max_width(flux__ui_constraint_label, (int)integer_value)"
    ));

    let invalid_pair = constrained_initial.replace("maxWidth: 200", "maxWidth: 60");
    fs::write(&entry, invalid_pair).expect("invalid constrained maximum edit should be writable");
    cache.invalidate_path(&entry);
    let invalid_pair = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("invalid constrained maximum remains semantically typed");
    assert!(
        invalid_pair
            .development_ui_string_patch_from(&constrained_first)
            .is_none(),
        "a literal maximum below its minimum must fall back to normal target validation"
    );
    assert!(
        invalid_pair.emit_c().is_err(),
        "a literal maximum below its minimum must still fail native validation"
    );

    let _ = fs::remove_dir_all(root);
}

#[test]
fn development_ui_string_patch_restarts_for_selection_state_with_callbacks() {
    let root = std::env::temp_dir().join(format!(
        "flux-development-selection-handler-patch-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root)
        .expect("temporary selection-handler patch project should be writable");
    let entry = root.join("main.flux");
    let initial = r#"view Screen {
    state enabled: bool = true
    state selected: i64 = 0
    grid columns: 1fr
    grid rows: auto auto
    Toggle toggle at 1,1
        label: "Toggle"
        checked: true
        onChange: enabled => !enabled
    Radio radio at 2,1
        label: "Radio"
        selected: false
        onSelect: selected => 1
}
app Screen
"#;
    let updated = initial
        .replace("checked: true", "checked: false")
        .replace("selected: false", "selected: true");
    fs::write(&entry, initial).expect("initial selection-handler source should be writable");

    let mut cache = fluxc::project::ProjectAnalysisCache::default();
    let first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("initial selection-handler analysis should succeed");

    fs::write(&entry, updated).expect("updated selection-handler source should be writable");
    let entry = fs::canonicalize(entry).expect("selection-handler patch entry should canonicalize");
    cache.invalidate_path(&entry);
    let second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("updated selection-handler analysis should succeed");

    assert!(
        second.development_ui_string_patch_from(&first).is_none(),
        "Toggle.checked or Radio.selected with callbacks must use controlled restart instead of synthesizing application selection events"
    );

    let _ = fs::remove_dir_all(root);
}

