#[test]
fn development_ui_string_patch_hot_applies_context_menu_item_labels() {
    let root = std::env::temp_dir().join(format!(
        "flux-development-context-menu-items-patch-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root)
        .expect("temporary context-menu items patch project should be writable");
    let entry = root.join("main.flux");
    let initial = r#"fn menuSelected(index: i64) -> void {
    print(index)
}

view ContextCard {
    grid columns: 1fr
    grid rows: auto
    Text card at 1,1
        text: "Options"
        contextMenuItems: ["Open", "Delete"]
        onContextMenuItemSelect: menuSelected
}
app ContextCard
"#;
    fs::write(&entry, initial).expect("initial context-menu items source should be writable");

    let mut cache = fluxc::project::ProjectAnalysisCache::default();
    let first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("initial context-menu items analysis should succeed");

    let updated = initial.replace(
        "contextMenuItems: [\"Open\", \"Delete\"]",
        "contextMenuItems: [\"Archive\", \"Delete\"]",
    );
    fs::write(&entry, &updated).expect("updated context-menu items source should be writable");
    let entry =
        fs::canonicalize(entry).expect("context-menu items patch entry should canonicalize");
    cache.invalidate_path(&entry);
    let second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("updated context-menu items analysis should succeed");
    let patch = second
        .development_ui_string_patch_from(&first)
        .expect("same-shape context menu item edits should hot-apply");
    assert_eq!(patch.len(), 1);
    assert_eq!(patch[0].element, "card");
    assert_eq!(patch[0].property, "context_menu_items");
    assert_eq!(patch[0].value, "2|7:Archive6:Delete");

    let generated = second
        .emit_c()
        .expect("context-menu items patch fixture should lower for Linux");
    assert!(
        generated.contains("static const char *flux__ui_context_menu_item_card_0 = \"Archive\"")
    );
    assert!(generated.contains("static char **flux__ui_context_menu_items_owned_card = NULL"));
    assert!(generated.contains("static size_t flux__ui_context_menu_items_count_card = 2"));
    assert!(generated.contains("strcmp(property, \"context_menu_items\") == 0"));
    assert!(generated.contains("flux__ui_context_menu_items_patch_card(value, value_length)"));
    assert!(generated.contains(
        "for (size_t item_index = 0; item_index < flux__ui_context_menu_items_count_card; ++item_index)"
    ));
    assert!(generated.contains("gtk_button_new_with_label(item_label)"));
    assert!(generated.contains("flux__ui_context_menu_items_clear_card();"));
    if Command::new("pkg-config")
        .args(["--exists", "gtk4"])
        .status()
        .is_ok_and(|status| status.success())
    {
        let c_path = root.join("context-menu-hot-reload.c");
        fs::write(&c_path, &generated)
            .expect("generated context-menu hot-reload C should be writable");
        let cflags = String::from_utf8(
            Command::new("pkg-config")
                .args(["--cflags", "gtk4"])
                .output()
                .expect("pkg-config should return GTK cflags")
                .stdout,
        )
        .expect("GTK cflags should be UTF-8");
        let compile = Command::new("clang")
            .args(["-std=c17", "-fsyntax-only", "-DFLUX_DEVELOPMENT_RELOAD"])
            .args(cflags.split_whitespace())
            .arg(&c_path)
            .output()
            .expect("Clang should validate context-menu development C");
        assert!(
            compile.status.success(),
            "context-menu development C should compile: {}",
            String::from_utf8_lossy(&compile.stderr)
        );
    }

    let reshaped = updated.replace(
        "contextMenuItems: [\"Archive\", \"Delete\"]",
        "contextMenuItems: [\"Archive\", \"Delete\", \"Share\"]",
    );
    fs::write(&entry, &reshaped).expect("reshaped context-menu items source should be writable");
    cache.invalidate_path(&entry);
    let third = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("reshaped context-menu items analysis should succeed");
    assert_eq!(third.development_abi(), second.development_abi());
    assert_eq!(
        third
            .development_ui_string_patch_from(&second)
            .expect("context menu item count growth should hot-apply"),
        vec![fluxc::project::DevelopmentUiStringPatch {
            element: "card".to_string(),
            property: "context_menu_items".to_string(),
            value: "3|7:Archive6:Delete5:Share".to_string(),
        }]
    );

    let shrunk = reshaped.replace(
        "contextMenuItems: [\"Archive\", \"Delete\", \"Share\"]",
        "contextMenuItems: [\"Archive\"]",
    );
    fs::write(&entry, shrunk).expect("shrunk context-menu items source should be writable");
    cache.invalidate_path(&entry);
    let fourth = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("shrunk context-menu items analysis should succeed");
    assert_eq!(fourth.development_abi(), third.development_abi());
    assert_eq!(
        fourth
            .development_ui_string_patch_from(&third)
            .expect("context menu item count shrink should hot-apply"),
        vec![fluxc::project::DevelopmentUiStringPatch {
            element: "card".to_string(),
            property: "context_menu_items".to_string(),
            value: "1|7:Archive".to_string(),
        }]
    );

    let _ = fs::remove_dir_all(root);
}

#[test]
fn development_ui_string_patch_hot_applies_shortcut_declaration_lifecycle() {
    let root = std::env::temp_dir().join(format!(
        "flux-development-shortcut-lifecycle-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary shortcut lifecycle project should be writable");
    let entry = root.join("main.flux");
    let initial = r#"view Shortcuts {
    grid columns: 1fr
    grid rows: auto
    state count: i64 = 0
    Button action at 1,1
        text: "Add"
        onPress: count => count + 1
}
app Shortcuts
"#;
    fs::write(&entry, initial).expect("initial shortcut lifecycle source should be writable");

    let mut cache = fluxc::project::ProjectAnalysisCache::default();
    let first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("initial shortcut lifecycle analysis should succeed");
    let generated = first
        .emit_c()
        .expect("shortcut lifecycle fixture should lower for Linux");
    assert!(
        generated
            .contains("#ifdef FLUX_DEVELOPMENT_RELOAD\nstatic gboolean flux__ui_shortcut_action")
    );
    assert!(generated.contains(
        "#ifdef FLUX_DEVELOPMENT_RELOAD\n    flux__ui_shortcut_controller_action = GTK_SHORTCUT_CONTROLLER(gtk_shortcut_controller_new())"
    ));
    assert!(generated.contains(
        "strcmp(property, \"shortcut\") == 0 && flux__ui_shortcut_controller_action != NULL"
    ));
    assert!(
        generated.contains("if (value_length == 0) { if (flux__ui_shortcut_object_action != NULL)")
    );

    let entry = fs::canonicalize(entry).expect("shortcut lifecycle entry should canonicalize");
    let explicit = initial.replace(
        "        text: \"Add\"\n",
        "        text: \"Add\"\n        shortcut: \"Ctrl+K\"\n",
    );
    fs::write(&entry, &explicit).expect("added shortcut source should be writable");
    cache.invalidate_path(&entry);
    let second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("added shortcut analysis should succeed");
    assert_eq!(
        second.development_abi(),
        first.development_abi(),
        "adding a shortcut to an existing typed action must not change the development ABI"
    );
    assert_eq!(
        second
            .development_ui_string_patch_from(&first)
            .expect("adding a shortcut should hot-apply to the dormant native controller"),
        vec![fluxc::project::DevelopmentUiStringPatch {
            element: "action".to_string(),
            property: "shortcut".to_string(),
            value: "<Control>k".to_string(),
        }]
    );

    let updated = explicit.replace("shortcut: \"Ctrl+K\"", "shortcut: \"Ctrl+L\"");
    fs::write(&entry, &updated).expect("updated shortcut source should be writable");
    cache.invalidate_path(&entry);
    let third = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("updated shortcut analysis should succeed");
    assert_eq!(
        third
            .development_ui_string_patch_from(&second)
            .expect("shortcut trigger edits should hot-apply to the existing native controller"),
        vec![fluxc::project::DevelopmentUiStringPatch {
            element: "action".to_string(),
            property: "shortcut".to_string(),
            value: "<Control>l".to_string(),
        }]
    );

    fs::write(&entry, initial).expect("removed shortcut source should be writable");
    cache.invalidate_path(&entry);
    let fourth = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("removed shortcut analysis should succeed");
    assert_eq!(fourth.development_abi(), third.development_abi());
    assert_eq!(
        fourth
            .development_ui_string_patch_from(&third)
            .expect("removing a shortcut should detach the active native shortcut object"),
        vec![fluxc::project::DevelopmentUiStringPatch {
            element: "action".to_string(),
            property: "shortcut".to_string(),
            value: String::new(),
        }]
    );

    let explicit_generated = third
        .emit_c()
        .expect("explicit shortcut fixture should lower for Linux");
    assert!(explicit_generated.contains(
        "flux__ui_shortcut_object_action = gtk_shortcut_new(gtk_shortcut_trigger_parse_string(\"<Control>l\")"
    ));
    assert!(explicit_generated.contains(
        "GtkShortcut *replacement = gtk_shortcut_new(trigger, gtk_callback_action_new(flux__ui_shortcut_action"
    ));
    assert!(explicit_generated.contains(
        "gtk_shortcut_controller_remove_shortcut(flux__ui_shortcut_controller_action, flux__ui_shortcut_object_action)"
    ));

    let _ = fs::remove_dir_all(root);
}

#[test]
fn development_ui_string_patch_hot_applies_focusable_declaration_lifecycle() {
    let root = std::env::temp_dir().join(format!(
        "flux-development-focusable-lifecycle-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary focusable lifecycle project should be writable");
    let entry = root.join("main.flux");
    let initial = r#"fn key_notice(key: str) -> void {
    print(key)
}

view Focus {
    state enabled: bool = true
    grid columns: 1fr
    grid rows: auto auto auto
    Text plain at 1,1
        text: "Plain"
    Text keyed at 2,1
        text: "Keyed"
        onKey: key_notice
    Button action at 3,1
        text: "Action"
}
app Focus
"#;
    fs::write(&entry, initial).expect("initial focusable lifecycle source should be writable");

    let mut cache = fluxc::project::ProjectAnalysisCache::default();
    let first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("initial focusable lifecycle source should analyze");
    let generated = first
        .emit_c()
        .expect("focusable lifecycle fixture should lower for Linux");
    for element in ["plain", "keyed", "action"] {
        assert!(generated.contains(&format!(
            "static bool flux__ui_focusable_default_{element} = false;"
        )));
        assert!(generated.contains(&format!(
            "strcmp(name, \"{element}\") == 0 && strcmp(property, \"focusable\") == 0"
        )));
        assert!(generated.contains(&format!(
            "gtk_widget_set_focusable(flux__ui_{element}, flux__ui_focusable_default_{element})"
        )));
    }
    assert!(generated.contains(
        "flux__ui_focusable_default_plain = gtk_widget_get_focusable(flux__ui_plain) || false;"
    ));
    assert!(generated.contains(
        "flux__ui_focusable_default_keyed = gtk_widget_get_focusable(flux__ui_keyed) || true;"
    ));
    assert!(generated.contains(
        "flux__ui_focusable_default_action = gtk_widget_get_focusable(flux__ui_action) || false;"
    ));

    let explicit = initial
        .replace(
            "        text: \"Plain\"\n",
            "        text: \"Plain\"\n        focusable: true\n",
        )
        .replace(
            "        text: \"Keyed\"\n",
            "        text: \"Keyed\"\n        focusable: false\n",
        )
        .replace(
            "        text: \"Action\"\n",
            "        text: \"Action\"\n        focusable: false\n",
        );
    fs::write(&entry, &explicit).expect("explicit focusable source should be writable");
    let entry = fs::canonicalize(entry).expect("focusable lifecycle entry should canonicalize");
    cache.invalidate_path(&entry);
    let second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("explicit focusable source should analyze");
    let patch = second
        .development_ui_string_patch_from(&first)
        .expect("adding literal focusable declarations should hot-apply")
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    assert_eq!(
        patch.get(&("plain".to_string(), "focusable".to_string())),
        Some(&"1".to_string())
    );
    assert_eq!(
        patch.get(&("keyed".to_string(), "focusable".to_string())),
        Some(&"0".to_string())
    );
    assert_eq!(
        patch.get(&("action".to_string(), "focusable".to_string())),
        Some(&"0".to_string())
    );
    assert_eq!(patch.len(), 3);

    fs::write(&entry, initial).expect("removed focusable source should be writable");
    cache.invalidate_path(&entry);
    let third = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("removed focusable source should analyze");
    let patch = third
        .development_ui_string_patch_from(&second)
        .expect("removing literal focusable declarations should restore omitted behavior")
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    for element in ["plain", "keyed", "action"] {
        assert_eq!(
            patch.get(&(element.to_string(), "focusable".to_string())),
            Some(&"__flux_focusable_default__".to_string())
        );
    }
    assert_eq!(patch.len(), 3);

    let dynamic = initial.replace(
        "        text: \"Plain\"\n",
        "        text: \"Plain\"\n        focusable: enabled\n",
    );
    fs::write(&entry, dynamic).expect("dynamic focusable source should be writable");
    cache.invalidate_path(&entry);
    let dynamic = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("dynamic focusable source should analyze");
    assert!(
        dynamic.development_ui_string_patch_from(&third).is_none(),
        "state-driven focusable declaration changes must retain controlled restart"
    );

    let _ = fs::remove_dir_all(root);
}

