    let error = compile_to_c(empty_family).expect_err("empty font family should fail");
    assert!(error.message.contains("Text.font_family cannot be empty"));

    let bad_line_height = r#"
view Screen {
    grid columns: 1fr
    grid rows: auto
    Text title at 1,1
        text: "Flux"
        line_height_percent: 0
}
app Screen
"#;
