#[test]
fn native_elements_support_static_and_state_driven_transforms() {
    let source = r#"
view Transformed {
    grid columns: 1fr
    grid rows: auto
    Button action at 1,1
        text: "Transform"
        translate_x: 12
        translate_y: -4
        rotate_degrees: 15
        scale_percent: 125
        scale_x_percent: 150
        scale_y_percent: 80
        skew_x_degrees: 5
        skew_y_degrees: -3
        transform_origin_x_percent: 0
        transform_origin_y_percent: 100
}
app Transformed
"#;
    check_source(source).expect("transform properties should typecheck as common i64 properties");
    let generated = compile_to_c(source).expect("transforms should lower through native GTK CSS");
    assert!(generated.contains(
        "transform: translate(12px, -4px) rotate(15deg) scale(1.50, 0.80) skewX(5deg) skewY(-3deg);"
    ));
    assert!(generated.contains("transform-origin: 0% 100%;"));

    let dynamic_transform = r#"
view Transformed {
    state moved: i64 = 0
    grid columns: 1fr
    grid rows: auto auto
    Text title at 1,1
        text: "Dynamic"
        translate_x: moved
        rotate_degrees: moved
        scale_percent: 100 + moved
        scale_y_percent: 100 - moved
        skew_x_degrees: moved
        transform_origin_x_percent: 50 + moved
        transition_ms: 180
        transition_delay_ms: 20
        transition_easing: "springSnappy"
    Button toggle at 2,1
        text: "Move"
        on_press: moved => moved + 4
}
app Transformed
"#;
    check_source(dynamic_transform)
        .expect("state-derived transforms should reuse typed primitive UI expressions");
    let generated = compile_to_c(dynamic_transform)
        .expect("state-derived transforms should lower to a refreshable native CSS provider");
    assert!(generated.contains("static GtkCssProvider *flux__transform_style_title = NULL;"));
    assert!(generated.contains("g_strdup_printf(\"#flux-ui-title { transform:"));
    assert!(generated.contains("transform-origin: %lld%% %lld%%;"));
    assert!(generated.contains("flux__ui_state_moved"));
    assert!(generated.contains("gtk_css_provider_load_from_data(flux__transform_style_title"));
    assert!(generated.contains("transition-property: all;"));
    assert!(generated.contains("transition-duration: 180ms;"));
    assert!(generated.contains("transition-delay: 20ms;"));
    assert!(generated.contains("transition-timing-function: cubic-bezier(0.16, 1.30, 0.30, 1);"));
    assert!(generated.contains("@media (prefers-reduced-motion: reduce)"));
    assert!(generated.contains("\"gtk-interface-reduced-motion\""));
    assert!(generated.contains("\"prefers-reduced-motion\""));

    let invalid_transition = r#"
view Transformed {
    grid columns: 1fr
    grid rows: auto
    Text title at 1,1
        text: "Bad transition"
        transition_easing: "ease_out"
}
app Transformed
"#;
    check_source(invalid_transition).expect("transition options have compiler-owned types");
    let error = compile_to_c(invalid_transition)
        .expect_err("transition easing without a duration should fail clearly");
    assert!(error.message.contains("require transition_ms"));

    let invalid_easing = r#"
view Transformed {
    grid columns: 1fr
    grid rows: auto
    Text title at 1,1
        text: "Bad easing"
        transition_ms: 180
        transition_easing: "wobbleForever"
}
app Transformed
"#;
    let easing_error = check_source(invalid_easing)
        .expect_err("unknown transition easing should fail during static checking");
    assert!(
        easing_error
            .message
            .contains("unsupported transitionEasing 'wobbleForever'")
    );
    assert!(
        easing_error
            .notes
            .iter()
            .any(|note| { note.contains("springGentle") && note.contains("springSnappy") })
    );

    let oversized = r#"
view Transformed {
    grid columns: 1fr
    grid rows: auto
    Text title at 1,1
        text: "Too far"
        translate_x: 2147483648
}
app Transformed
"#;
    check_source(oversized).expect("transform dimensions are ordinary i64 properties");
    let error = compile_to_c(oversized)
        .expect_err("static native transform must fit GTK CSS integer range");
    assert!(
        error
            .message
            .contains("translate_x must fit within a 32-bit signed integer")
    );
}

#[test]
fn native_layout_transitions_animate_visibility_reflow_without_controller_objects() {
    let source = r#"
view AnimatedLayout {
    state shown: bool = true
    grid columns: 1fr
    grid rows: auto auto
    Text detail at 1,1
        text: "Now you see me"
        visible: shown
        layoutTransitionMs: motionNormal
    Button toggle at 2,1
        text: "Toggle"
        onPress: shown => !shown
}
app AnimatedLayout
"#;
    check_source(source).expect("layout transitions should typecheck on built-in elements");

    let linux = compile_to_c(source).expect("layout transitions should lower on Linux");
    assert!(linux.contains("static GtkWidget *flux__ui_layout_detail = NULL;"));
    assert!(linux.contains("flux__ui_layout_detail = gtk_revealer_new()"));
    assert!(linux.contains("GTK_REVEALER_TRANSITION_TYPE_SLIDE_DOWN"));
    assert!(linux.contains(
        "gtk_revealer_set_transition_duration(GTK_REVEALER(flux__ui_layout_detail), (guint)200)"
    ));
    assert!(
        linux.contains(
            "gtk_revealer_set_child(GTK_REVEALER(flux__ui_layout_detail), flux__ui_detail)"
        )
    );
    assert!(linux.contains(
        "gtk_revealer_set_reveal_child(GTK_REVEALER(flux__ui_layout_detail), flux__ui_state_shown)"
    ));
    assert!(linux.contains("gtk_grid_attach(GTK_GRID(grid), flux__ui_layout_detail"));

    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::UNKNOWN)
        .expect("layout transition fixture should analyze");
    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        database.program(),
        database.signatures(),
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("layout transitions should lower on Android");
    assert!(android.contains("android/animation/LayoutTransition"));
    assert!(android.contains("\"setDuration\", \"(J)V\""));
    assert!(
        android.contains("\"setLayoutTransition\", \"(Landroid/animation/LayoutTransition;)V\"")
    );
    assert!(android.contains("(jlong)INT64_C(200)"));
    assert!(android.contains("setVisibility"));

    let ordinary = r#"
view StaticLayout {
    grid columns: 1fr
    grid rows: auto
    Text title at 1,1
        text: "Static"
}
app StaticLayout
"#;
    let linux = compile_to_c(ordinary).expect("ordinary UI should still compile");
    assert!(linux.contains(
        "#ifdef FLUX_DEVELOPMENT_RELOAD\n    flux__ui_layout_title = gtk_revealer_new();"
    ));
    assert!(linux.contains("#else\n    gtk_grid_attach(GTK_GRID(grid), flux__ui_title"));
    let database = fluxc::semantic::SemanticDatabase::analyze(ordinary, SourceId::UNKNOWN)
        .expect("ordinary UI fixture should analyze");
    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        database.program(),
        database.signatures(),
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("ordinary UI should still lower on Android");
    assert!(!android.contains("android/animation/LayoutTransition"));

    let conflicting = r#"
view ConflictingLayout {
    grid columns: 1fr
    grid rows: auto auto
    Text first at 1,1
        text: "First"
        layoutTransitionMs: 120
    Text second at 2,1
        text: "Second"
        layoutTransitionMs: 200
}
app ConflictingLayout
"#;
    check_source(conflicting)
        .expect("layout transition duration is an ordinary typed i64 property");
    let database = fluxc::semantic::SemanticDatabase::analyze(conflicting, SourceId::UNKNOWN)
        .expect("conflicting layout transition fixture should analyze before native validation");
    let error = fluxc::codegen::emit_c_for_target_with_source_paths(
        database.program(),
        database.signatures(),
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect_err("one view must use one deterministic layout transition duration");
    assert!(error.message.contains("one duration per view"));

    let partial_opt_in = r#"
view PartialLayout {
    state firstShown: bool = true
    state secondShown: bool = true
    grid columns: 1fr
    grid rows: auto auto
    Text first at 1,1
        text: "First"
        visible: firstShown
        layoutTransitionMs: 200
    Text second at 2,1
        text: "Second"
        visible: secondShown
}
app PartialLayout
"#;
    check_source(partial_opt_in).expect("layout-transition participation is validated at lowering");
    let error = compile_to_c(partial_opt_in)
        .expect_err("dynamic visibility must not be animated implicitly by another element");
    assert!(error.message.contains("must declare layoutTransitionMs"));
}

