    assert!(generated.contains("gtk_check_button_new_with_label(\"Second\")"));
    assert!(generated.contains("gtk_check_button_set_group(GTK_CHECK_BUTTON(flux__ui_second), GTK_CHECK_BUTTON(flux__ui_first))"));
