#[test]
fn accessibility_order_lowers_to_native_assistive_reading_order() {
    let source = r#"
view Screen {
    grid columns: 1fr
    grid rows: auto auto auto
    Text third at 1,1
        text: "Third"
        accessibilityOrder: 30
    Button first at 2,1
        text: "First"
        accessibilityOrder: 10
    TextInput second at 3,1
        accessibilityOrder: 20
}
app Screen
"#;
    check_source(source).expect("unique compile-time accessibility order should typecheck");
    let linux = compile_to_c(source).expect("accessibility order should lower to GTK relations");
    assert!(linux.contains("static int64_t flux__ui_accessibility_order_first = INT64_C(10)"));
    assert!(linux.contains("static int64_t flux__ui_accessibility_order_second = INT64_C(20)"));
    assert!(linux.contains("static int64_t flux__ui_accessibility_order_third = INT64_C(30)"));
    assert!(
        linux.contains(
            "gtk_accessible_reset_relation(nodes[index], GTK_ACCESSIBLE_RELATION_FLOW_TO)"
        )
    );
    assert!(linux.contains("if (orders[indices[right]] < orders[indices[left]])"));
    assert!(linux.contains(
        "gtk_accessible_update_relation(current, GTK_ACCESSIBLE_RELATION_FLOW_TO, next, -1)"
    ));
    assert!(linux.contains("flux__ui_refresh_accessibility_order();"));

    let program = fluxc::parser::parse(source).expect("accessibility-order app should parse");
    let signatures =
        fluxc::typecheck::check(&program).expect("accessibility-order app should typecheck");
    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("accessibility order should lower to Android traversal metadata");
    assert!(android.contains("setAccessibilityTraversalAfter"));
    assert!(android.contains(&format!(
        "set_accessibility_traversal_after, (jint){}",
        android_stable_view_id("Screen", "first")
    )));
    assert!(android.contains(&format!(
        "set_accessibility_traversal_after, (jint){}",
        android_stable_view_id("Screen", "second")
    )));

    let windows = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Windows,
    )
    .expect("accessibility order should lower to native Win32 child ordering");
    assert!(windows.contains(
        "SetWindowPos(flux__ui_first, HWND_TOP, 0, 0, 0, 0, SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE)"
    ));
    assert!(windows.contains(
        "SetWindowPos(flux__ui_second, flux__ui_first, 0, 0, 0, 0, SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE)"
    ));
    assert!(windows.contains(
        "SetWindowPos(flux__ui_third, flux__ui_second, 0, 0, 0, 0, SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE)"
    ));

    let duplicate = r#"
view Screen {
    grid columns: 1fr
    grid rows: auto auto
    Text first at 1,1
        accessibilityOrder: 1
    Text second at 2,1
        accessibilityOrder: 1
}
app Screen
"#;
    let errors = check_source_all(duplicate).expect_err("duplicate accessibility order must fail");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("accessibilityOrder 1 is already used")
    }));

    let dynamic = r#"
view Screen {
    state order: i64 = 1
    grid columns: 1fr
    grid rows: auto
    Text item at 1,1
        accessibilityOrder: order
}
app Screen
"#;
    let errors = check_source_all(dynamic).expect_err("runtime accessibility order must fail");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("accessibilityOrder must be a compile-time i64 value")
    }));
}

#[test]
fn development_ui_string_patch_hot_applies_accessibility_order() {
    let root = std::env::temp_dir().join(format!(
        "flux-development-accessibility-order-patch-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root)
        .expect("temporary accessibility-order patch project should be writable");
    let entry = root.join("main.flux");
    let initial = r#"view Screen {
    grid columns: 1fr
    grid rows: auto auto auto
    Text first at 1,1
        text: "First"
        accessibilityOrder: 10
    Text second at 2,1
        text: "Second"
        accessibilityOrder: 20
    Text third at 3,1
        text: "Third"
        accessibilityOrder: 30
}
app Screen
"#;
    fs::write(&entry, initial).expect("initial accessibility-order source should be writable");

    let mut cache = fluxc::project::ProjectAnalysisCache::default();
    let first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("initial accessibility-order analysis should succeed");

    let updated = initial
        .replace(
            "Text first at 1,1\n        text: \"First\"\n        accessibilityOrder: 10",
            "Text first at 1,1\n        text: \"First\"\n        accessibilityOrder: 30",
        )
        .replace(
            "Text third at 3,1\n        text: \"Third\"\n        accessibilityOrder: 30",
            "Text third at 3,1\n        text: \"Third\"\n        accessibilityOrder: 10",
        );
    fs::write(&entry, &updated).expect("updated accessibility-order source should be writable");
    let entry =
        fs::canonicalize(entry).expect("accessibility-order patch entry should canonicalize");
    cache.invalidate_path(&entry);
    let second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("updated accessibility-order analysis should succeed");
    let patch = second
        .development_ui_string_patch_from(&first)
        .expect("valid accessibility-order edits should hot-apply");
    let patch = patch
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    assert_eq!(
        patch.get(&("first".to_string(), "accessibility_order".to_string())),
        Some(&"30".to_string())
    );
    assert_eq!(
        patch.get(&("third".to_string(), "accessibility_order".to_string())),
        Some(&"10".to_string())
    );

    let generated = second
        .emit_c()
        .expect("accessibility-order patch fixture should lower for Linux");
    assert!(generated.contains("flux__ui_accessibility_order_changed = true"));
    assert!(generated.contains(
        "if (flux__ui_accessibility_order_changed) { flux__ui_accessibility_order_changed = false; flux__ui_refresh_accessibility_order(); }"
    ));

    let _ = fs::remove_dir_all(root);
}

#[test]
fn development_ui_string_patch_hot_applies_accessibility_order_declaration_lifecycle() {
    let root = std::env::temp_dir().join(format!(
        "flux-development-accessibility-order-lifecycle-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root)
        .expect("temporary accessibility-order lifecycle project should be writable");
    let entry = root.join("main.flux");
    let initial = r#"view Screen {
    grid columns: 1fr
    grid rows: auto auto auto
    Text first at 1,1
        text: "First"
    Text second at 2,1
        text: "Second"
    Text third at 3,1
        text: "Third"
}
app Screen
"#;
    fs::write(&entry, initial).expect("initial accessibility-order source should be writable");

    let mut cache = fluxc::project::ProjectAnalysisCache::default();
    let first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("initial accessibility-order lifecycle source should analyze");
    let generated = first
        .emit_c()
        .expect("omitted accessibility-order fixture should lower for Linux");
    for element in ["first", "second", "third"] {
        assert!(generated.contains(&format!(
            "static int64_t flux__ui_accessibility_order_{element} = INT64_C(-1)"
        )));
        assert!(generated.contains(&format!(
            "strcmp(name, \"{element}\") == 0 && strcmp(property, \"accessibility_order\") == 0"
        )));
    }
    assert!(generated.contains("if (orders[index] >= 0) indices[ordered_count++] = index"));
    assert!(generated.contains(
        "#ifdef FLUX_DEVELOPMENT_RELOAD\n    flux__ui_refresh_accessibility_order();\n#endif"
    ));

    let explicit = initial
        .replace(
            "        text: \"First\"\n",
            "        text: \"First\"\n        accessibilityOrder: 10\n",
        )
        .replace(
            "        text: \"Third\"\n",
            "        text: \"Third\"\n        accessibilityOrder: 30\n",
        );
    let entry = fs::canonicalize(entry).expect("accessibility-order entry should canonicalize");
    fs::write(&entry, &explicit).expect("explicit accessibility-order source should be writable");
    cache.invalidate_path(&entry);
    let second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("explicit accessibility-order source should analyze");
    assert_eq!(
        second.development_abi(),
        first.development_abi(),
        "adding literal accessibilityOrder declarations should preserve the development ABI"
    );
    let patch = second
        .development_ui_string_patch_from(&first)
        .expect("adding literal accessibilityOrder declarations should hot-apply")
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    assert_eq!(
        patch.get(&("first".to_string(), "accessibility_order".to_string())),
        Some(&"10".to_string())
    );
    assert_eq!(
        patch.get(&("third".to_string(), "accessibility_order".to_string())),
        Some(&"30".to_string())
    );
    assert_eq!(patch.len(), 2);

    fs::write(&entry, initial).expect("removed accessibility-order source should be writable");
    cache.invalidate_path(&entry);
    let third = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("removed accessibility-order source should analyze");
    assert_eq!(
        third.development_abi(),
        second.development_abi(),
        "removing literal accessibilityOrder declarations should preserve the development ABI"
    );
    let patch = third
        .development_ui_string_patch_from(&second)
        .expect("removing accessibilityOrder declarations should restore native ordering")
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    for element in ["first", "third"] {
        assert_eq!(
            patch.get(&(element.to_string(), "accessibility_order".to_string())),
            Some(&"-1".to_string())
        );
    }
    assert_eq!(patch.len(), 2);

    let duplicate = explicit.replace("accessibilityOrder: 30", "accessibilityOrder: 10");
    fs::write(&entry, duplicate).expect("duplicate accessibility-order source should be writable");
    cache.invalidate_path(&entry);
    let errors = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect_err("duplicate accessibilityOrder values must fail before hot-reload planning");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("accessibilityOrder 10 is already used")
    }));

    let _ = fs::remove_dir_all(root);
}

#[test]
fn native_controls_preserve_platform_screen_reader_bridges() {
    let source = r#"
view Screen {
    state semanticValue: str = "Off"
    grid columns: 1fr
    grid rows: auto auto auto auto auto auto
    Text title at 1,1
        text: "Title"
        accessibilityLabel: "Screen title"
        accessibilityRole: "heading"
        accessibilityOrder: 10
    Button action at 2,1
        text: "Continue"
        accessibilityDescription: "Continue to the next step"
        accessibilityRole: "button"
        accessibilityOrder: 20
    TextInput input at 3,1
        accessibilityLabel: "Name"
        accessibilityRole: "textBox"
        accessibilityOrder: 30
    Toggle toggle at 4,1
        label: "Enabled"
        accessibilityLabel: "Enabled setting"
        accessibilityValue: semanticValue
        accessibilityRole: "switch"
        accessibilityOrder: 40
    Radio radio at 5,1
        label: "Choice"
        accessibilityLabel: "Choice option"
        accessibilityRole: "radio"
        accessibilityOrder: 50
    Image image at 6,1
        source: ""
        alt: "Preview"
        accessibilityLabel: "Preview image"
        accessibilityRole: "image"
        accessibilityHidden: false
        accessibilityOrder: 60
}
app Screen
"#;

    check_source(source).expect("native accessibility bridge sample should typecheck");
    let linux =
        compile_to_c(source).expect("native accessibility bridge sample should lower on Linux");
    assert!(linux.contains("gtk_label_new"));
    assert!(linux.contains("gtk_button_new_with_label"));
    assert!(linux.contains("gtk_entry_new"));
    assert!(linux.contains("gtk_check_button_new_with_label"));
    assert!(linux.contains("gtk_picture_new"));
    assert!(linux.contains("GTK_ACCESSIBLE_PROPERTY_LABEL"));
    assert!(linux.contains("GTK_ACCESSIBLE_PROPERTY_DESCRIPTION"));
    assert!(linux.contains("GTK_ACCESSIBLE_PROPERTY_VALUE_TEXT"));
    assert!(
        linux.matches("GTK_ACCESSIBLE_PROPERTY_VALUE_TEXT").count() >= 2,
        "state-driven accessibility values should lower for initial render and refresh"
    );
    assert!(linux.contains("GTK_ACCESSIBLE_PROPERTY_ROLE_DESCRIPTION"));
    assert!(linux.contains("GTK_ACCESSIBLE_STATE_HIDDEN"));
    assert!(linux.contains("GTK_ACCESSIBLE_RELATION_FLOW_TO"));

    let program = fluxc::parser::parse(source).expect("screen-reader bridge app should parse");
    let signatures =
        fluxc::typecheck::check(&program).expect("screen-reader bridge app should typecheck");
    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("native accessibility bridge sample should lower on Android");
    for class_name in [
        "android/widget/TextView",
        "android/widget/Button",
        "app/flux/runtime/FluxActivity$FluxEditText",
        "android/widget/Switch",
        "android/widget/RadioButton",
        "android/widget/ImageView",
    ] {
        assert!(
            android.contains(class_name),
            "missing native Android accessibility-bearing control {class_name}"
        );
    }
    assert!(android.contains("setAccessibility"));
    assert!(android.contains("setAccessibilityValue"));
    assert!(
        android.matches("setAccessibilityValue").count() >= 2,
        "state-driven Android accessibility values should lower for initial render and refresh"
    );
    assert!(android.contains("setAccessibilityRole"));
    assert!(android.contains("setAccessibilityHidden"));
    assert!(android.contains("setAccessibilityTraversalAfter"));
}

