#[test]
fn application_layout_direction_validates_and_lowers_on_native_backends() {
    let rtl = r#"
view Screen {
    grid columns: 1fr
    grid rows: auto
    Text title at 1,1
        text: "مرحبا"
}
app Screen(layoutDirection: "rtl")
"#;
    check_source(rtl).expect("RTL application direction should typecheck");
    let formatted = fluxc::formatter::format_source(rtl).expect("RTL metadata should format");
    assert!(formatted.contains("app Screen(layoutDirection: \"rtl\")"));

    let linux = compile_to_c(rtl).expect("RTL direction should lower to GTK");
    assert!(linux.contains("gtk_widget_set_direction(grid, GTK_TEXT_DIR_RTL)"));

    let program = fluxc::parser::parse(rtl).expect("RTL app should parse");
    let signatures = fluxc::typecheck::check(&program).expect("RTL app should typecheck");
    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("RTL direction should lower to Android");
    assert!(android.contains("setLayoutDirection"));
    assert!(android.contains("set_layout_direction, (jint)1"));

    let windows = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Windows,
    )
    .expect("RTL direction should lower to Windows");
    assert!(windows.contains("CreateWindowExW(WS_EX_LAYOUTRTL, wc.lpszClassName"));

    let system = r#"
view Screen {
    grid columns: 1fr
    grid rows: auto
}
app Screen(layoutDirection: "system")
"#;
    let linux = compile_to_c(system).expect("system direction should preserve GTK locale choice");
    assert!(!linux.contains("gtk_widget_set_direction(grid"));
    let program = fluxc::parser::parse(system).expect("system direction app should parse");
    let signatures =
        fluxc::typecheck::check(&program).expect("system direction app should typecheck");
    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("system direction should preserve Android locale choice");
    assert!(!android.contains("setLayoutDirection"));
    let windows = fluxc::codegen::emit_c_for_target_with_source_paths(
        &program,
        &signatures,
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Windows,
    )
    .expect("system direction should preserve Windows default layout");
    assert!(windows.contains("CreateWindowExW(0, wc.lpszClassName"));

    let invalid = r#"
view Screen {
    grid columns: 1fr
    grid rows: auto
}
app Screen(layoutDirection: "vertical")
"#;
    let errors = check_source_all(invalid).expect_err("invalid layout direction must fail");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("application layoutDirection must be one of 'system', 'ltr', or 'rtl'")
    }));
}

#[test]
fn custom_application_theme_palette_validates_and_lowers() {
    let source = r##"
view Screen {
    grid columns: 1fr
    grid rows: auto
    Text title at 1,1
        text: "Flux"
        color: "accent"
}
app Screen(theme: "system", surfaceColor: "#FAFAFA", accentColor: "#123456", shadowColor: "#11223380")
"##;
    check_source(source).expect("custom semantic palette colors should typecheck");

    let linux = compile_to_c(source).expect("custom palette should lower to native GTK CSS");
    assert!(linux.contains("static char flux__ui_theme_surface[64] = \"#FAFAFA\""));
    assert!(linux.contains("static char flux__ui_theme_accent[64] = \"#123456\""));
    assert!(linux.contains("static char flux__ui_theme_shadow[64] = \"#11223380\""));
    assert!(linux.contains("@define-color flux_surface %s;"));
    assert!(linux.contains("@define-color flux_accent %s;"));
    assert!(linux.contains("@define-color flux_shadow %s;"));
    assert!(linux.contains("color: @flux_accent;"));

    let database = fluxc::semantic::SemanticDatabase::analyze(source, SourceId::UNKNOWN)
        .expect("custom palette fixture should analyze");
    let android = fluxc::codegen::emit_c_for_target_with_source_paths(
        database.program(),
        database.signatures(),
        &std::collections::HashMap::new(),
        fluxc::codegen::NativeTarget::Android,
    )
    .expect("custom palette should lower on Android");
    assert!(android.contains("Java_app_flux_runtime_FluxActivity_nativeThemeColor"));
    assert!(android.contains("strcmp(value, \"surface\") == 0"));
    assert!(android.contains("strcmp(value, \"accent\") == 0"));
    assert!(android.contains("\"#FAFAFA\""));
    assert!(android.contains("\"#123456\""));
    assert!(android.contains("\"#11223380\""));

    let semantic_override = r#"
view Screen {
    grid columns: 1fr
    grid rows: auto
}
app Screen(accentColor: "accent")
"#;
    let errors = check_source_all(semantic_override)
        .expect_err("custom palette values must resolve to concrete colors");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("application accentColor must use '#RRGGBB' or '#RRGGBBAA'")
    }));

    let wrong_type = r#"
view Screen {
    grid columns: 1fr
    grid rows: auto
}
app Screen(accentColor: 7)
"#;
    let errors = check_source_all(wrong_type).expect_err("custom palette values must be strings");
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("application accentColor must be str")
    }));
}

#[test]
fn application_environment_configuration_combines_manifest_constants_and_host_environment() {
    let root = std::env::temp_dir().join(format!(
        "flux-application-configuration-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(root.join("src")).expect("application package should be writable");
    fs::write(
        root.join("flux.toml"),
        "[package]\nname = \"configured-app\"\nentry = \"src/main.flux\"\n\n[constants]\nappTitle = \"Configured Flux\"\napiBase = \"https://example.test/v1\"\n",
    )
    .expect("application manifest should be writable");
    fs::write(
        root.join("src/main.flux"),
        r#"fn started() -> void {
    print(process.env("FLUX_APP_ENV", "development"))
}
view Screen {
    grid columns: 1fr
    grid rows: auto
    Text endpoint at 1,1
        text: package.apiBase
}
app Screen(title: package.appTitle, onStart: started)
"#,
    )
    .expect("application source should be writable");

    let generated = fluxc::project::compile_to_c(&root)
        .expect("manifest configuration and host environment should compile for an application");
    assert!(generated.contains("Configured Flux"));
    assert!(generated.contains("https://example.test/v1"));
    assert!(generated.contains("getenv("));
    assert!(
        !generated.contains("package."),
        "package configuration must fold away before native lowering"
    );

    let _ = fs::remove_dir_all(root);
}

#[test]
fn application_lifecycle_metadata_uses_typed_free_function_callbacks() {
    let source = r#"
fn started() -> void {
    print("started")
}
fn resumed() -> void {
    print("resumed")
}
fn paused() -> void {
    print("paused")
}
fn stopped() -> void {
    print("stopped")
}
fn exiting() -> void {
    print("exiting")
}
fn openUrl(value: str) -> void {
    print(value)
}
view Screen {
    grid columns: 1fr
    grid rows: auto
}
app Screen(onStart: started, onResume: resumed, onPause: paused, onStop: stopped, onExit: exiting, onOpenUrl: openUrl)
"#;
    check_source(source)
        .expect("lifecycle callbacks should typecheck as named fn() -> void values");
    let generated = compile_to_c(source).expect("lifecycle callbacks should lower natively");
    assert!(generated.contains("flux__fn_started();"));
    assert!(generated.contains("static void flux__ui_active_changed"));
    assert!(generated.contains("flux__fn_resumed();"));
    assert!(generated.contains("flux__fn_paused();"));
    assert!(generated.contains("\"notify::is-active\", G_CALLBACK(flux__ui_active_changed)"));
    assert!(generated.contains("static void flux__ui_shutdown"));
    assert!(generated.contains("flux__fn_stopped();"));
    assert!(generated.contains("flux__fn_exiting();"));
    assert!(generated.contains("\"shutdown\", G_CALLBACK(flux__ui_shutdown)"));
    assert!(
        generated.contains("static void flux__ui_open(GApplication *application, GFile **files")
    );
    assert!(
        generated.contains("gtk_application_get_windows(GTK_APPLICATION(application)) == NULL")
    );
    assert!(generated.contains("g_file_get_uri(files[index])"));
    assert!(generated.contains("flux__fn_openUrl(uri);"));
    assert!(
        generated
            .contains("gtk_application_new(\"app.flux.bootstrap\", G_APPLICATION_HANDLES_OPEN)")
    );
    assert!(generated.contains("\"open\", G_CALLBACK(flux__ui_open)"));

    let wrong = r#"
fn bad(value: i64) -> void {
}
view Screen {
    grid columns: 1fr
    grid rows: auto
}
app Screen(onStart: bad)
"#;
    let errors = check_source_all(wrong).expect_err("wrong lifecycle signature should fail");
    assert!(errors.iter().any(|error| {
        error.message.contains("application onStart callback")
            && error.message.contains("expected fn() -> void")
    }));

    let wrong_state = r#"
fn badSave() -> void {
}
fn badRestore() -> str {
    return "bad"
}
view Screen {
    grid columns: 1fr
    grid rows: auto
}
app Screen(onSaveState: badSave, onRestoreState: badRestore)
"#;
    let errors = check_source_all(wrong_state)
        .expect_err("saved-state lifecycle callbacks require exact signatures");
    assert!(errors.iter().any(|error| {
        error.message.contains("application onSaveState callback")
            && error.message.contains("expected fn() -> str")
    }));
    assert!(errors.iter().any(|error| {
        error
            .message
            .contains("application onRestoreState callback")
            && error.message.contains("expected fn(str) -> void")
    }));
}

