#[test]
fn async_await_inside_if_branches_suspends_without_blocking_worker() {
    let source = r#"
async fn addOne(value: i64) -> i64 {
    return value + 1
}

async fn choose(flag: bool) -> i64 {
    var total: i64 = 1
    if flag:
        total = total + 39
        let value: i64 = await addOne(total)
        total = value
        return total + 1
    return total + 2
}

async fn chooseElse(flag: bool) -> i64 {
    if flag:
        return 5
    else:
        let value: i64 = await addOne(40)
        return value + 2
}

async fn fallthrough(flag: bool) -> i64 {
    var total: i64 = 1
    if flag:
        let value: i64 = await addOne(40)
        total = value
    else:
        total = 2
    return total + 1
}

async fn main() -> i64 {
    let first: i64 = await choose(true)
    let second: i64 = await chooseElse(false)
    let skippedThen: i64 = await choose(false)
    let skippedElse: i64 = await chooseElse(true)
    let resumedFallthrough: i64 = await fallthrough(true)
    let skippedFallthrough: i64 = await fallthrough(false)
    return first + second + skippedThen + skippedElse + resumedFallthrough + skippedFallthrough
}
"#;

    check_source(source).expect("await inside if branches should remain supported");
    let generated = compile_to_c(source).expect("branch await lowering should remain native");
    assert!(generated.contains("flux__async_resume_choose"));
    assert!(generated.contains("flux__async_resume_chooseElse"));
    assert!(generated.contains("flux__async_resume_fallthrough"));
    assert!(!generated.contains("flux__async_body_choose("));
    assert!(!generated.contains("flux__async_body_chooseElse("));
    assert!(!generated.contains("flux__async_body_fallthrough("));
    assert!(generated.contains(
        "flux__async_start_cont_addOne(INT64_C(40), flux__async_resume_choose, flux__task)"
    ));
    assert!(generated.contains(
        "flux__async_start_cont_addOne(INT64_C(40), flux__async_resume_chooseElse, flux__task)"
    ));
    assert!(!generated.contains("flux__async_await_addOne(flux__async_start_addOne(INT64_C(40)))"));
    assert!(generated.contains("pthread_cond_wait"));
    assert!(!generated.contains("pthread_join("));

    let root = std::env::temp_dir().join(format!("flux-async-if-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("async if fixture should be writable");
    let source_path = root.join("main.flux");
    fs::write(&source_path, source).expect("async if source should be writable");
    let binary = root.join("async-if");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("async if binary should build");
    assert!(
        built.status.success(),
        "async if build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let status = Command::new(&binary)
        .status()
        .expect("async if binary should run");
    assert_eq!(status.code(), Some(138));
    let _ = fs::remove_dir_all(&root);

    let loop_source = r#"
async fn addOne(value: i64) -> i64 {
    return value + 1
}

async fn loopTwice() -> i64 {
    var value: i64 = 0
    while value < 4:
        value = await addOne(value)
        value = await addOne(value)
    return value
}

async fn main() -> i64 {
    return await loopTwice()
}
"#;
    let loop_generated = compile_to_c(loop_source)
        .expect("direct awaits in while bodies should lower to continuation states");
    assert!(loop_generated.contains("flux__async_resume_loopTwice"));
    assert!(!loop_generated.contains("flux__async_body_loopTwice("));
    assert!(loop_generated.contains(
        "flux__async_start_cont_addOne(flux__local_value, flux__async_resume_loopTwice, flux__task)"
    ));
    assert!(
        !loop_generated
            .contains("flux__async_await_addOne(flux__async_start_addOne(flux__local_value))")
    );

    let loop_root = std::env::temp_dir().join(format!("flux-async-while-{}", std::process::id()));
    let _ = fs::remove_dir_all(&loop_root);
    fs::create_dir_all(&loop_root).expect("async while fixture should be writable");
    let loop_source_path = loop_root.join("main.flux");
    fs::write(&loop_source_path, loop_source).expect("async while source should be writable");
    let loop_binary = loop_root.join("async-while");
    let loop_built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&loop_source_path)
        .arg("-o")
        .arg(&loop_binary)
        .output()
        .expect("async while binary should build");
    assert!(
        loop_built.status.success(),
        "async while build failed: {}",
        String::from_utf8_lossy(&loop_built.stderr)
    );
    let loop_status = Command::new(&loop_binary)
        .status()
        .expect("async while binary should run");
    assert_eq!(loop_status.code(), Some(4));
    let _ = fs::remove_dir_all(&loop_root);

    let loop_control_source = r#"
async fn addOne(value: i64) -> i64 {
    return value + 1
}

async fn withLoopControl() -> i64 {
    var value: i64 = 0
    var total: i64 = 0
    while value < 5:
        value = await addOne(value)
        if value == 2:
            continue
        total = total + value
        if value == 4:
            break
    return total
}

async fn main() -> i64 {
    return await withLoopControl()
}
"#;
    let loop_control_generated = compile_to_c(loop_control_source)
        .expect("while loop control should suspend through continuation states");
    assert!(loop_control_generated.contains("flux__async_resume_withLoopControl"));
    assert!(!loop_control_generated.contains("flux__async_body_withLoopControl("));
    assert!(
        !loop_control_generated
            .contains("flux__async_await_addOne(flux__async_start_addOne(flux__local_value))")
    );

    let loop_control_root =
        std::env::temp_dir().join(format!("flux-async-while-control-{}", std::process::id()));
    let _ = fs::remove_dir_all(&loop_control_root);
    fs::create_dir_all(&loop_control_root).expect("async while control fixture should be writable");
    let loop_control_path = loop_control_root.join("main.flux");
    let loop_control_binary = loop_control_root.join("async-while-control");
    fs::write(&loop_control_path, loop_control_source)
        .expect("async while control source should be writable");
    let loop_control_built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&loop_control_path)
        .arg("-o")
        .arg(&loop_control_binary)
        .output()
        .expect("async while control fixture should build");
    assert!(
        loop_control_built.status.success(),
        "async while control build failed: {}",
        String::from_utf8_lossy(&loop_control_built.stderr)
    );
    let loop_control_status = Command::new(&loop_control_binary)
        .status()
        .expect("async while control fixture should run");
    assert_eq!(loop_control_status.code(), Some(8));
    let _ = fs::remove_dir_all(&loop_control_root);
}

