#[test]
fn async_await_inside_enum_match_suspends_without_blocking_worker() {
    let source = r#"
enum Choice {
    Value(i64)
    Empty
}

async fn addOne(value: i64) -> i64 {
    return value + 1
}

async fn loadChoice(choice: Choice) -> Choice {
    return choice
}

async fn choose(choice: Choice) -> i64 {
    var total: i64 = 1
    match await loadChoice(choice):
        Choice.Value(value):
            total = await addOne(value)
            total = await addOne(total)
        Choice.Empty():
            total = 4
    return total
}

async fn main() -> i64 {
    let selected: i64 = await choose(Choice.Value(40))
    let empty: i64 = await choose(Choice.Empty())
    return selected + empty
}
"#;

    check_source(source).expect("await inside enum match arms should remain supported");
    let generated =
        compile_to_c(source).expect("enum match awaits should lower to continuation states");
    assert!(generated.contains("flux__async_resume_choose"));
    assert!(!generated.contains("flux__async_body_choose("));
    assert!(generated.contains(
        "flux__async_start_cont_loadChoice(flux__local_choice, flux__async_resume_choose, flux__task)"
    ));
    assert!(!generated.contains("flux__async_await_loadChoice(flux__async_start_loadChoice"));
    assert!(generated.contains(
        "flux__async_start_cont_addOne(flux__local_value, flux__async_resume_choose, flux__task)"
    ));
    assert!(generated.contains(
        "flux__async_start_cont_addOne(flux__local_total, flux__async_resume_choose, flux__task)"
    ));
    assert!(
        !generated
            .contains("flux__async_await_addOne(flux__async_start_addOne(flux__local_value))")
    );

    let guarded_source = r#"
enum Choice {
    Value(i64)
    Empty
}

async fn addOne(value: i64) -> i64 {
    return value + 1
}

async fn choose(choice: Choice) -> i64 {
    let offset: i64 = 5
    match choice:
        Choice.Value(value) if value > offset + 5:
            return await addOne(value)
        Choice.Value(< 0 && > -99):
            return await addOne(10)
        Choice.Value(value):
            return value
        Choice.Empty():
            return 0
}

async fn main() -> i64 {
    let positive: i64 = await choose(Choice.Value(40))
    let negative: i64 = await choose(Choice.Value(-1))
    let zero: i64 = await choose(Choice.Value(0))
    let empty: i64 = await choose(Choice.Empty())
    return positive + negative + zero + empty
}
"#;
    let guarded_generated = compile_to_c(guarded_source)
        .expect("guarded match awaits should lower to continuation states");
    assert!(guarded_generated.contains("flux__async_resume_choose"));
    assert!(!guarded_generated.contains("flux__async_body_choose("));
    assert!(guarded_generated.contains(
        "flux__async_start_cont_addOne(flux__local_value, flux__async_resume_choose, flux__task)"
    ));
    assert!(guarded_generated.contains("< INT64_C(0)"));
    assert!(guarded_generated.contains("&&"));
    assert!(!guarded_generated.contains("flux_add_i64(flux__local_offset, INT64_C(5))"));
    assert!(guarded_generated.contains(
        "flux__async_start_cont_addOne(INT64_C(10), flux__async_resume_choose, flux__task)"
    ));

    let root = std::env::temp_dir().join(format!("flux-async-match-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("async match fixture directory should be writable");
    let source_path = root.join("main.flux");
    let binary = root.join("async-match");
    fs::write(&source_path, source).expect("async match source should be writable");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("async match fixture should build");
    assert!(
        built.status.success(),
        "async match fixture build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let status = Command::new(&binary)
        .status()
        .expect("async match fixture should run");
    assert_eq!(status.code(), Some(46));
    let _ = fs::remove_dir_all(&root);

    let guarded_root =
        std::env::temp_dir().join(format!("flux-async-guarded-match-{}", std::process::id()));
    let _ = fs::remove_dir_all(&guarded_root);
    fs::create_dir_all(&guarded_root).expect("guarded async match directory should be writable");
    let guarded_path = guarded_root.join("main.flux");
    let guarded_binary = guarded_root.join("async-guarded-match");
    fs::write(&guarded_path, guarded_source)
        .expect("guarded async match source should be writable");
    let guarded_built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&guarded_path)
        .arg("-o")
        .arg(&guarded_binary)
        .output()
        .expect("guarded async match fixture should build");
    assert!(
        guarded_built.status.success(),
        "guarded async match build failed: {}",
        String::from_utf8_lossy(&guarded_built.stderr)
    );
    let guarded_status = Command::new(&guarded_binary)
        .status()
        .expect("guarded async match fixture should run");
    assert_eq!(guarded_status.code(), Some(52));
    let _ = fs::remove_dir_all(&guarded_root);
}

