#[test]
fn websocket_client_handshake_surface_is_typed_and_native() {
    let source = r#"
fn main() -> i64 {
    let (session, handshakeError) = websocket.connect(3, "localhost")
    if handshakeError != nil:
        return 1
    let (_bytes, readError) = websocket.readText(session, 1024, fn(value: str) { print(value) })
    if readError != nil:
        return 2
    let writeError: error = websocket.writeText(session, "hello")
    if writeError != nil:
        return 3
    let pingError: error = websocket.ping(session, "probe")
    if pingError != nil:
        return 4
    let pongError: error = websocket.pong(session, "probe")
    if pongError != nil:
        return 5
    let closeError: error = websocket.close(session)
    if closeError != nil:
        return 6
    return 0
}
"#;
    check_source(source).expect("WebSocket client surface should typecheck");
    let generated = compile_to_c(source).expect("WebSocket client surface should lower");
    assert!(generated.contains("flux__websocket_connect("));
    assert!(generated.contains("WebSocket requires a TCP socket"));
    assert!(generated.contains("WebSocket requires a connected TCP socket"));
    assert!(generated.contains("flux__websocket_bounded_length(host, 255, &host_length)"));
    assert!(generated.contains("flux__websocket_find_bytes(const char *value, size_t length"));
    assert!(
        generated.contains("flux__websocket_find_bytes(response, response_length, \"\\r\\n\", 2)")
    );
    assert!(generated.contains("flux__websocket_find_bytes(cursor, remaining, \"\\r\\n\", 2)"));
    assert!(!generated.contains("char *status_end = strstr(response, \"\\r\\n\")"));
    assert!(generated.contains("/dev/urandom"));
    assert!(generated.contains("flux__websocket_response_header(response, response_length, \"Sec-WebSocket-Accept\", expected, false)"));
    assert!(generated.contains(
        "while (cursor + 1 < limit && !(cursor[0] == '\\r' && cursor[1] == '\\n')) cursor += 1"
    ));
    assert!(!generated.contains("const char *line_end = strstr(cursor, \"\\r\\n\")"));
    assert!(generated.contains("HTTP/1.1 101 Switching Protocols"));
    assert!(generated.contains("WebSocket client handshake contains NUL"));
    assert!(generated.contains("flux__websocket_is_client(session)"));
    assert!(generated.contains("flux__websocket_write_control"));
    assert!(generated.contains("WebSocket control frame must be final and at most 125 bytes"));
    assert!(generated.contains("WebSocket opcode is reserved or unsupported"));
    assert!(generated.contains("flux__websocket_write_ping("));
    assert!(generated.contains("flux__websocket_write_pong("));
    assert!(generated.contains("flux__websocket_bounded_length(value, 125"));
    assert!(generated.contains("flux__websocket_close_with_code("));
    assert!(generated.contains("flux__websocket_bounded_length(reason, 123"));
    assert!(generated.contains("flux__websocket_bounded_length(value, 65535"));
    assert!(generated.contains("WebSocket close reason contains invalid UTF-8"));
    assert!(generated.contains("failed to create WebSocket control mask"));
    assert!(generated.contains("fread(mask, 1, sizeof(mask), random_source) != sizeof(mask)"));
    assert!(generated.contains("WebSocket text frame contains invalid UTF-8"));
}

