#[test]
fn websocket_server_reads_fragmented_text_and_answers_ping() {
    let probe = TcpListener::bind("127.0.0.1:0").expect("WebSocket probe should bind");
    let port = probe.local_addr().unwrap().port();
    drop(probe);
    let source = format!(
        r#"fn onText(value: str) -> void {{
    print(value)
}}

fn main() -> i64 {{
    let (listener, listenError) = net.listen("127.0.0.1", {port}, 8)
    if listenError != nil:
        return 1
    let (socket, acceptError) = net.accept(listener)
    if acceptError != nil:
        return 2
    let (session, handshakeError) = websocket.accept(socket)
    if handshakeError != nil:
        return 3
    let (_bytes, readError) = websocket.readText(session, 64, onText)
    if readError != nil:
        return 4
    let writeError: error = websocket.writeText(session, "ok")
    if writeError != nil:
        return 5
    let closeError: error = websocket.close(session)
    if closeError != nil:
        return 6
    return 0
}}
"#
    );
    let root = std::env::temp_dir().join(format!("flux-websocket-e2e-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("WebSocket E2E fixture should be writable");
    let source_path = root.join("main.flux");
    fs::write(&source_path, source).expect("WebSocket E2E source should be writable");
    let binary = root.join("websocket-e2e");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .args(["build", source_path.to_str().unwrap(), "-o"])
        .arg(&binary)
        .output()
        .expect("WebSocket E2E binary should build");
    assert!(
        built.status.success(),
        "WebSocket E2E build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );
    let server = thread::spawn(move || {
        let output = Command::new(&binary)
            .output()
            .expect("WebSocket E2E server should run");
        assert!(
            output.status.success(),
            "WebSocket E2E server failed: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        assert_eq!(String::from_utf8_lossy(&output.stdout), "hello\n");
    });
    thread::sleep(Duration::from_millis(100));
    let mut client = std::net::TcpStream::connect(("127.0.0.1", port))
        .expect("WebSocket E2E client should connect");
    client
        .set_read_timeout(Some(Duration::from_secs(2)))
        .unwrap();
    client
        .write_all(
            b"GET /chat HTTP/1.1\r\nHost: localhost\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: SGVsbG9GbHV4V29ybGQ=\r\nSec-WebSocket-Version: 13\r\n\r\n",
        )
        .unwrap();
    let mut handshake = Vec::new();
    let mut byte = [0_u8; 1];
    while !handshake.ends_with(b"\r\n\r\n") {
        client.read_exact(&mut byte).unwrap();
        handshake.push(byte[0]);
    }
    assert!(String::from_utf8_lossy(&handshake).contains("101 Switching Protocols"));
    fn masked_frame(fin: bool, opcode: u8, payload: &[u8], key: [u8; 4]) -> Vec<u8> {
        let mut frame = vec![
            if fin { 0x80 | opcode } else { opcode },
            0x80 | payload.len() as u8,
        ];
        frame.extend_from_slice(&key);
        frame.extend(
            payload
                .iter()
                .enumerate()
                .map(|(index, byte)| byte ^ key[index % 4]),
        );
        frame
    }
    client
        .write_all(&masked_frame(false, 1, b"hel", [1, 2, 3, 4]))
        .unwrap();
    client
        .write_all(&masked_frame(true, 9, b"?", [5, 6, 7, 8]))
        .unwrap();
    client
        .write_all(&masked_frame(true, 0, b"lo", [9, 10, 11, 12]))
        .unwrap();
    let mut response = Vec::new();
    let mut chunk = [0_u8; 128];
    while !(response.windows(2).any(|window| window == [0x8A, 1])
        && response.windows(3).any(|window| window == [0x81, 2, b'o']))
    {
        let received = client.read(&mut chunk).unwrap();
        assert!(
            received > 0,
            "WebSocket server should send pong and text response"
        );
        response.extend_from_slice(&chunk[..received]);
    }
    server.join().unwrap();
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn websocket_blocked_io_is_worker_cancellable() {
    let probe = TcpListener::bind("127.0.0.1:0").expect("WebSocket cancellation probe should bind");
    let port = probe.local_addr().unwrap().port();
    drop(probe);
    let source = format!(
        r#"fn onText(_value: str) -> void {{
}}

fn blockedRead(session: i64) -> void {{
    let (_bytes, readError) = websocket.readText(session, 64, onText)
    if readError != nil && worker.cancelled():
        print(readError)
}}

fn main() -> i64 {{
    let (listener, listenError) = net.listen("127.0.0.1", {port}, 8)
    if listenError != nil:
        return 1
    let (socket, acceptError) = net.accept(listener)
    if acceptError != nil:
        return 2
    let (session, handshakeError) = websocket.accept(socket)
    if handshakeError != nil:
        return 3
    let (handle, startError) = worker.startWith(blockedRead, session)
    if startError != nil:
        return 4
    time.sleep(100)
    let cancelError: error = worker.cancel(handle)
    if cancelError != nil:
        return 5
    let joinError: error = worker.join(handle)
    if joinError != nil:
        return 6
    let closeError: error = websocket.close(session)
    if closeError != nil:
        return 7
    let listenerCloseError: error = net.close(listener)
    if listenerCloseError != nil:
        return 8
    return 0
}}
"#
    );
    check_source(&source).expect("worker-cancellable WebSocket read should typecheck");
    let generated =
        compile_to_c(&source).expect("worker-cancellable WebSocket read should lower natively");
    assert!(generated.contains("static inline int flux__net_poll_cancellable"));
    assert!(generated.contains("int ready = flux__net_poll_cancellable(&descriptor, 1, -1);"));
    assert!(generated.contains("MSG_DONTWAIT"));
    assert!(generated.contains("errno = ECANCELED"));
    assert!(generated.contains("WebSocket read cancelled by worker scope"));
    assert!(generated.contains("WebSocket write cancelled by worker scope"));

    let root = std::env::temp_dir().join(format!("flux-websocket-cancel-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("WebSocket cancellation fixture should be writable");
    let source_path = root.join("main.flux");
    fs::write(&source_path, source).expect("WebSocket cancellation source should be writable");
    let binary = root.join("websocket-cancel");
    let built = Command::new(env!("CARGO_BIN_EXE_flux"))
        .args(["build", source_path.to_str().unwrap(), "-o"])
        .arg(&binary)
        .output()
        .expect("WebSocket cancellation binary should build");
    assert!(
        built.status.success(),
        "WebSocket cancellation build failed: {}",
        String::from_utf8_lossy(&built.stderr)
    );

    let mut server = Command::new(&binary)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("WebSocket cancellation server should start");
    thread::sleep(Duration::from_millis(100));
    let mut client = std::net::TcpStream::connect(("127.0.0.1", port))
        .expect("WebSocket cancellation client should connect");
    client
        .set_read_timeout(Some(Duration::from_secs(2)))
        .unwrap();
    client
        .write_all(
            b"GET /cancel HTTP/1.1\r\nHost: localhost\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: SGVsbG9GbHV4V29ybGQ=\r\nSec-WebSocket-Version: 13\r\n\r\n",
        )
        .unwrap();
    let mut handshake = Vec::new();
    let mut byte = [0_u8; 1];
    while !handshake.ends_with(b"\r\n\r\n") {
        client.read_exact(&mut byte).unwrap();
        handshake.push(byte[0]);
    }
    assert!(String::from_utf8_lossy(&handshake).contains("101 Switching Protocols"));

    let deadline = Instant::now() + Duration::from_secs(2);
    let status = loop {
        if let Some(status) = server
            .try_wait()
            .expect("WebSocket cancellation server status should be readable")
        {
            break status;
        }
        if Instant::now() >= deadline {
            let _ = server.kill();
            let _ = server.wait();
            panic!("worker cancellation should interrupt blocked WebSocket I/O");
        }
        thread::sleep(Duration::from_millis(20));
    };
    let output = server
        .wait_with_output()
        .expect("WebSocket cancellation server output should be readable");
    assert!(
        status.success(),
        "WebSocket cancellation server failed: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    assert_eq!(
        String::from_utf8_lossy(&output.stdout),
        "WebSocket read cancelled by worker scope
"
    );
    let _ = fs::remove_dir_all(&root);
}

#[test]
fn local_time_offset_is_typed_native_and_dst_aware() {
    let source = r#"
fn main() -> i64 {
    print(time.localOffset(1577836800000))
    print(time.localOffset(1593561600000))
    print(time.localOffset(-1))
    return 0
}
"#;
    check_source(source).expect("local offset should typecheck");
    let generated = compile_to_c(source).expect("local offset should lower natively");
    assert!(generated.contains("flux__time_local_offset_safe(int64_t unix_ms)"));
    assert!(
        generated.contains("local_value.__tm_gmtoff")
            || generated.contains("local_value.tm_gmtoff")
    );

    let root = std::env::temp_dir().join(format!("flux-local-offset-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("local offset fixture should be writable");
    let source_path = root.join("main.flux");
    fs::write(&source_path, source).expect("local offset source should be writable");
    let binary = root.join("local-offset");
    let build = Command::new(env!("CARGO_BIN_EXE_flux"))
        .arg("build")
        .arg(&source_path)
        .arg("-o")
        .arg(&binary)
        .output()
        .expect("local offset binary should build");
    assert!(
        build.status.success(),
        "local offset build failed: {}",
        String::from_utf8_lossy(&build.stderr)
    );
    let run = Command::new(&binary)
        .env("TZ", "America/New_York")
        .output()
        .expect("local offset binary should run");
    assert!(run.status.success());
    let values = String::from_utf8_lossy(&run.stdout)
        .lines()
        .map(|line| {
            line.parse::<i64>()
                .expect("local offset output should be i64")
        })
        .collect::<Vec<_>>();
    assert_eq!(values, vec![-300, -240, -300]);
    let _ = fs::remove_dir_all(root);
}

#[test]
fn json_encodes_copy_scalar_optionals_as_null_or_value() {
    let source = r#"
fn encoded(value: str) -> void {
    print(value)
}
fn main() -> i64 {
    let present: i64? = 42
    let absent: bool? = none
    let text: str? = "Flux"
    let noText: str? = none
    print(json.encode(present, encoded))
    print(json.encode(absent, encoded))
    print(json.encode(text, encoded))
    print(json.encode(noText, encoded))
    return 0
}
"#;
    check_source(source).expect("scalar optional JSON values should typecheck");
    let generated = compile_to_c(source).expect("scalar optional JSON values should lower");
    assert!(generated.contains("flux__json_encode_optional_i64"));
    assert!(generated.contains("flux__json_encode_optional_bool"));
    assert!(generated.contains("flux__json_encode_optional_str"));
    let root = std::env::temp_dir().join(format!("flux-json-optional-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary JSON optional directory should be writable");
    let c_path = root.join("json-optional.c");
    let exe_path = root.join("json-optional");
    fs::write(&c_path, generated).expect("generated JSON optional C should be writable");
    let compile = Command::new("clang")
        .args(["-std=c11", "-O2"])
        .arg(&c_path)
        .arg("-o")
        .arg(&exe_path)
        .output()
        .expect("clang should compile JSON optional code");
    assert!(
        compile.status.success(),
        "{}",
        String::from_utf8_lossy(&compile.stderr)
    );
    let output = Command::new(&exe_path)
        .output()
        .expect("JSON optional program should run");
    assert!(output.status.success());
    assert_eq!(
        String::from_utf8_lossy(&output.stdout),
        "42\nnil\nnull\nnil\n\"Flux\"\nnil\nnull\nnil\n"
    );
    let _ = fs::remove_dir_all(root);
}

#[test]
fn development_ui_string_patch_hot_applies_uncontrolled_selection_declaration_lifecycle() {
    let root = std::env::temp_dir().join(format!(
        "flux-development-selection-lifecycle-{}",
        std::process::id()
    ));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("temporary selection lifecycle project should be writable");
    let entry = root.join("main.flux");
    let initial = r#"view Screen {
    grid columns: 1fr
    grid rows: auto auto
    Toggle toggle at 1,1
        label: "Toggle"
    Radio radio at 2,1
        label: "Radio"
}
app Screen
"#;
    fs::write(&entry, initial).expect("initial selection lifecycle source should be writable");

    let mut cache = fluxc::project::ProjectAnalysisCache::default();
    let first = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("initial selection lifecycle source should analyze");
    let generated = first
        .emit_c()
        .expect("selection lifecycle fixture should lower for Linux");
    assert!(generated.contains(
        "strcmp(property, \"checked\") == 0 && bool_value_valid && flux__ui_toggle != NULL"
    ));
    assert!(generated.contains(
        "strcmp(property, \"selected\") == 0 && bool_value_valid && flux__ui_radio != NULL"
    ));

    let entry = fs::canonicalize(entry).expect("selection lifecycle entry should canonicalize");
    let explicit_default = initial
        .replace(
            "        label: \"Toggle\"\n",
            "        label: \"Toggle\"\n        checked: false\n",
        )
        .replace(
            "        label: \"Radio\"\n",
            "        label: \"Radio\"\n        selected: false\n",
        );
    fs::write(&entry, &explicit_default).expect("explicit selection defaults should be writable");
    cache.invalidate_path(&entry);
    let second = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("explicit selection defaults should analyze");
    assert_eq!(second.development_abi(), first.development_abi());
    assert_eq!(
        second.development_ui_string_patch_from(&first),
        Some(Vec::new()),
        "adding false selection defaults should be an in-process no-op"
    );

    let active = explicit_default
        .replace("checked: false", "checked: true")
        .replace("selected: false", "selected: true");
    fs::write(&entry, active).expect("active selection source should be writable");
    cache.invalidate_path(&entry);
    let third = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("active selection source should analyze");
    assert_eq!(third.development_abi(), first.development_abi());
    let active_patch = third
        .development_ui_string_patch_from(&second)
        .expect("uncontrolled selection values should hot-apply")
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    assert_eq!(
        active_patch.get(&("toggle".to_string(), "checked".to_string())),
        Some(&"1".to_string())
    );
    assert_eq!(
        active_patch.get(&("radio".to_string(), "selected".to_string())),
        Some(&"1".to_string())
    );
    assert_eq!(active_patch.len(), 2);

    fs::write(&entry, initial).expect("removed selection source should be writable");
    cache.invalidate_path(&entry);
    let fourth = cache
        .analyze_with_overlays(&entry, &std::collections::HashMap::new())
        .expect("removed selection lifecycle source should analyze");
    assert_eq!(fourth.development_abi(), third.development_abi());
    let restored_patch = fourth
        .development_ui_string_patch_from(&third)
        .expect("removing selection declarations should restore false defaults")
        .into_iter()
        .map(|record| ((record.element, record.property), record.value))
        .collect::<std::collections::BTreeMap<_, _>>();
    assert_eq!(
        restored_patch.get(&("toggle".to_string(), "checked".to_string())),
        Some(&"0".to_string())
    );
    assert_eq!(
        restored_patch.get(&("radio".to_string(), "selected".to_string())),
        Some(&"0".to_string())
    );
    assert_eq!(restored_patch.len(), 2);

    let _ = fs::remove_dir_all(root);
}
